/* 令和8年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r08.committeeSessions.push(...[{"id":"r08-20260414-6","meetingId":"r08-m0405","date":"2026年4月14日","dateIso":"2026-04-14","committee":"区民委員会","time":"午後 １時００分～午後 ３時１４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年度 町会・自治会課題解決支援事業","agenda":"令和７年度 町会・自治会課題解決支援事業","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"やはり担い手不足といったところが一番大きいのかなと思うのですけれども、その中でも担い手を確保するため、また、それを町会内で啓発、周知していく手法といったところでしていると思うのですけれども、いわゆる専門家の方に寄り添っていただいて、課題を洗い出して、それをどういう形で解消に向けていくのかという事業の中で報告書も見させていただいたわけなのですが、この寄り添うのは。","respondent":"平原地域活動課長","answer":"大きくは幾つかのパターンに分かれるのですけれども、まず１つ目は、１年間でこの事業によって、課題解決に着手することができた、一定の到達点までできた、ただ、まだそこからは先に進むのに少し課題があるといった場合に。","voiceIndex":12,"id":"exchange-001"},{"speaker":"こんの委員","kind":"質問","question":"そうしたときに、確かに専門家の方にアドバイスをいただいてそこをするのですが、その専門家からいただいたアドバイスを地域センターも当然、共有しながら、この町会はこうしたところが課題だね、対策はこうだねということを個別にきちんと把握しながら、町会・自治会のサポートというよりも、同じレベルで走っていただくというような位置づけのサポート体制というのですか、では具体的にどうなの。","respondent":"平原地域活動課長","answer":"ただ一方で、先ほどご紹介いただきましたけれども、センターによっても必ず、何か悩みに対してお答えできているわけではないといったところは、私どもしっかり反省させていただきたいと思ってありますけれども、直ちにお答えができないとしても。","voiceIndex":14,"id":"exchange-002"},{"speaker":"こんの委員","kind":"質問","question":"せっかくやる事業なので、今後こうした事業をもっと生かせる、そこの中で出てきた課題を、ではこういう仕組みでサポートできるものにしていこうというものに展開できるのではないかなとは思うので、そういったことを今後は考えていくのも必要なのではないですかといったところです。何かお答えがありましたらお願いします。","respondent":"平原地域活動課長","answer":"サポートというようなお話ですけれども、まず、どういう形でこの事業を広めていくことができるのか、私ども横展開という言い方をしていますけれども、この事業を受けた方々と一緒に、それ以外の地域の方々を含めまして入っていくことによりまして。","voiceIndex":16,"id":"exchange-003"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ですので、今回こうやって得られた知見などをまた、ほかの町会・自治会への横展開というか共有していただきたいなと思うのですが、令和８年度の実施予定の一番最後のところにも、他団体への浸透（横展開）と書いてありますけれども、そういった面で今までの、こうやったほうがいいよといったノウハウやアドバイスなどをほかにも伝えていって悩みを解決するという観点から。","respondent":"平原地域活動課長","answer":"入り口としてはそういったことにはなるのですけれども、もう一点、今年度については、実際に受けた町会の町会長などといった方に、ほかの町会、ほかの地域の場で何かご説明する場などを用意させていただいて。","voiceIndex":18,"id":"exchange-004"},{"speaker":"おぎの委員","kind":"質問・要望","question":"すごくいいやり方だなと思います。実際経験された方が生の声で、今悩んでいる方に伝えていくという、また、町会同士の関係づくりにもなりますので、ぜひ進めていただきたいなと思います。今後もマンションはますます増えていきますので、ぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２０１の町会・自治会がある中で、限られた町会の支援をするという中で、いろいろ品川区内でも、町会・自治会というのはそれぞれ温度差があると思うのです。そうすると、この前、昨年の１２月ですか、おとなりんくという、町会・自治会、あと、青少年委員の方が主となってやった、八潮全体でやるイベントの中で、私も実際お邪魔をして、若い人が結構来ている。","respondent":"平原地域活動課長","answer":"それが、ほかの地区でも同じような形で広がっていくようにしてまいりたいと考えています。","voiceIndex":24,"id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"提案","question":"それで、この報告書の１０ページで、これは東中延一丁目町会で、マンションとの関係づくりに向けた支援実施、これ幾つかの町会があるのですが、委託会社はダイナックス都市環境研究所ですよね。マンションの中では管理者がいて、開発事業者向けと管理組合向けの依頼状というのがあるのですけれども、これはダイナックス都市環境研究所が提案して作成したのかどうかを、まず、１つ質問です。","respondent":"平原地域活動課長","answer":"そういう中で、まず、基礎資料といたしましては、全町会に配付させていただいたもの、その上で、さらに個別具体的なものという２段階で進めていったところですけれども、先ほどのご質疑の中でもございましたとおり、今、横展開を図っていくという中では。","voiceIndex":26,"id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ、これも改めて周知をよろしくお願いしたいのと、やはりマンションのところに入って加入促進をするという依頼もある、依頼状があって、マンションと戸建てというのは違いがある、防災訓練があったときにそういう告知をしていてもなかなか、来る人、来ない人もいるので、やはり一番やり方としては、防災を主としたときに、こういう依頼状というのかな、竣工時もそうなのですけれども、それも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-008"},{"speaker":"こしば委員","kind":"質問","question":"前提としてお聞きしたいのは、町会・自治会の課題解決支援事業の中で、立候補された町会がどのくらいあったのか教えてください。結果としては８町会を選定して、事業に取り組まれたのですけれども、まず、立候補した町会についてお願いします。","respondent":"平原地域活動課長","answer":"令和７年度につきましては、採択した８団体が立候補団体ということになりますので、いわゆるイコールの関係です。","voiceIndex":30,"id":"exchange-009"},{"speaker":"こしば委員","kind":"質問・要望","question":"ですので、この８町会しか立候補がなかったのかと思っています。そういった、本当にイベントも実施ができないような町会・自治会、恐らく地域センターからも情報が上がってきていると思うので把握はされていると思うのですけれども、そういった町会への支援について、この伴走型支援以外についても教えていただきたいと思います。","respondent":"平原地域活動課長","answer":"別の例では、いろいろやりたいことはあるけれども単独町会では難しいといったときに、近隣の町会と手を結ぶやり方があるのではないかということで、今回の伴走型支援を使って、近隣町会と手をつないで情報のデジタル化などを進めたというような事例もありますので。","voiceIndex":32,"id":"exchange-010"},{"speaker":"こしば委員","kind":"質問・要望","question":"どのレベルの町会・自治会でも、こういった事業に応募することができるということは確認いたしました。そういう中でありますけれど、また、さらにもっとフランクな形でいいので、そういう町会の役員と地域センターの方とのふれあいというのをぜひ実施していただきたいなと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-011"},{"speaker":"せらく委員","kind":"質問・要望","question":"こんの委員からありましたように、この事業、実施期間が短いものになりますので、その後というところの重要性は私も感じているところです。質問させていただきたいのは、令和８年度実施予定の効果検証についてなのです。こちら、令和４年度から実施している延べ団体数などが分かれば教えていただきたく、また、効果検証の内容とその検証結果をどのように役立てていくのか、現時点のお考えをお聞かせください。","respondent":"平原地域活動課長","answer":"効果検証の内容はこれから詰めていくことになりますので、まだ、どういった効果がというようなところまで出てはいないのですけれども、町会・自治会に対して私どもが何をしていくのか、あるいはどういったところにこそお困り事があるのかしっかり分析して。","voiceIndex":36,"id":"exchange-012"},{"speaker":"せらく委員","kind":"質問・要望","question":"この辺りは、防災をテーマにというような方向があったのか確認させてください。マンションはやはり回覧板が回ってこないということもあったりしまして、掲示板に表示とかお知らせなどをしているとは思うのですけれども、マンションこそＳＮＳでの情報発信というのが求められているのではないかなと思ったのですが、その辺りの考えもお聞かせください。","respondent":"平原地域活動課長","answer":"マンションとの関係づくりといったところでは、必ずしも防災だけに限ったような話ということではないのですけれども、やはりお互いの活動が見えるというようなところでは、防災が非常に分かりやすいということで、防災の話が前面に出ながら。","voiceIndex":38,"id":"exchange-013"}]},{"id":"topic-02","title":"令和８年経済センサス－活動調査","agenda":"令和８年経済センサス－活動調査","exchanges":[{"speaker":"おぎの委員","kind":"意見","question":"これは５年に１度、総務省、経済産業省がやる、日本経済の国勢調査のようなものかなと認識しております。これ、品川区内で、外資、日本企業関係なく全て調査するのかということと、そうしますと調査員の外国語の対応はどうされているのかなというところが１点。最後に、地域活性化や災害時の復旧計画などを含め、区政にどういった形で活かしていくのか、お考えがあればお聞かせいただけたらと思います。","respondent":"平原地域活動課長","answer":"あくまでも、第１次産業に該当する事業者以外のものは対象という形で今回行わせていただきますけれども、令和８年の調査につきましては、基本がインターネット調査ということになりますので、例えば、なかなか外国語だけで日本語での意思疎通が難しいということでありましたら。","voiceIndex":44,"id":"exchange-014"},{"speaker":"おぎの委員","kind":"質問・要望","question":"大がかりにやる調査ですので、ぜひこの情報を様々な角度で分析して、区内の事業者の活性等に役立てていただきたいなと考えています。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-015"},{"speaker":"こんの委員","kind":"質問・要望","question":"何点かお聞きしたいと思います。このご説明は地域活動課長がされたというところが少し「えっ」と思ったのですけれど、経済センサスなので地域産業振興課が所管するものではないですかというのが少し気になりました。その点が１点。２番の（１）で調査員の対象の事業所と直轄の対象の事業所、この違いはどういうものなのかというのを教えていただきたい。","respondent":"平原地域活動課長","answer":"そういったところで、私どもあくまでも統計調査を実施するということになりますので、その統計調査の公表後の数値を分析するというのは、実際の各所管がどのような数字を使って自分のところの施策にどう生かしていくのかというのは、個別の問題ですので。","voiceIndex":48,"id":"exchange-016"},{"speaker":"こんの委員","kind":"質問","question":"そうしましたら、先ほどの質疑でもありましたけれども、この調査結果が出たものを区としてどう活用していくか、展開していくかといったところも少しお聞きしてもいいですか。事業所も起業されたり廃業されたり、その年によって様々あると思うのですが、一定数品川区として、これまでも５年に１度やってきた中で、常にずっと長く継続していらっしゃる会社は把握をされてきているのだと思うのです。","respondent":"平原地域活動課長、吉岡地域産業振興課長","answer":"経済センサスから離れますけれども、昨年実施いたしました国勢調査などでしたら、人口の趨勢というものが正しい数値で見えてまいりますので、そういったところでは、私どもの今後の人口動態などを考えていくというところで役立てて。情報通信業、こういったところの高まりを受けまして、担当課長を設置したりですとか、そういう創業・スタートアップ、こういったところの事業の拡充を図ったということがあります。","voiceIndex":50,"id":"exchange-017"},{"speaker":"こんの委員","kind":"質問・要望","question":"今、私は中小零細企業に角度を当てて質問させていただきましたけれども、学校や保育園等々も入ってくるというお話での統計だということを確認させていただきました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-018"}]},{"id":"topic-03","title":"しながわ生活応援事業の進捗報告","agenda":"しながわ生活応援事業の進捗報告","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"スケジュールの確認なのですけれども、ここに記載の１人世帯・２人世帯が４月下旬以降、３人世帯は４月１８日、下旬はいつからが下旬か、要するに４月１８日は中旬という認識だと、これ１人世帯・２人世帯は４月下旬、では３人世帯の方から配送ですか。このスケジュール感を確認させてください。","respondent":"今井しながわ生活応援担当課長","answer":"現状ですと、１人世帯・２人世帯につきましては４月２５日頃から発送開始ということで調整をしているのですが、まずは、３人世帯の封入を先に完了させて、４月１７日に郵便局に持ち込んで１８日からこの世帯の配送を開始するというところまではスケジュールが固まっておりまして。","voiceIndex":58,"id":"exchange-019"},{"speaker":"こんの委員","kind":"確認","question":"そのときに、隣の家は来たのだけれどうちはまだ来ていないみたいな声が上がってくるので、私たちとしても、認識しておいたほうがいいねと会派で確認をしたところ、こういう日程だということが今分かったので、そうすると、３人世帯の方が最初に配られていくという認識でよろしいということですね。","respondent":"今井しながわ生活応援担当課長","answer":"ご認識のとおり、一番最初に３人世帯が配られるというスケジュールです。","voiceIndex":60,"id":"exchange-020"},{"speaker":"おぎの委員","kind":"質問・要望","question":"私もスケジュールのところなのですが、４月１８日からは発送が始まるということで、ふれあい掲示板に貼るポスターが５月１日から３１日というのは、少しタイミング的に、この間頂いたお知らせの紙と、詐欺の電話にご注意くださいという、この啓発のほうだと思うのですけれども、このポスターが５月１日からというのは、少し遅くないかなと思うのですが、このタイミングになった理由が特別あれば。","respondent":"今井しながわ生活応援担当課長","answer":"ポスターにつきましては、事業者に委託して、作成していただいているというところですので、その作成ができ次第、なるべく早いタイミングで掲示をお願いするということで、５月１日という日付を設定させていただいたところです。","voiceIndex":63,"id":"exchange-021"}]},{"id":"topic-04","title":"保有個人情報の開示等における区の対応をめぐる国家賠償請求事件","agenda":"保有個人情報の開示等における区の対応をめぐる国家賠償請求事件","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"ここにも原因が1)、2)とありますけれども、そもそも知らなかったという、理解をしていなかった、いわゆるこの情報公開・個人情報保護制度を十分理解されていなかったというのは、非常にそもそも論で、全職員がこういうことが、どの窓口でもこういう公開請求を受けるといったことがあると思うので、その辺のところが、お答えができる範囲で、新卒で入った方ならまだしも、そうではなかった方だったのか。","respondent":"築山戸籍住民課長","answer":"そうしたところによって、制度上１４日以内に回答しなければならないというところをまずは、しっかりと押さえてもらいまして、ほかの職員にもそういったところで情報共有をしながら再発防止に努めてまいりたいと考えております。","voiceIndex":70,"id":"exchange-022"},{"speaker":"こんの委員","kind":"提案","question":"ですので、これ、特にここのセクションで起きたということですが、全庁的に起きることを考えると、職員の研修だけでなく、常にそのことが情報共有される、何か仕組みなり、そうした意識啓発なり、周知なり、していくことが必要かなと、では具体は何かというのは今、提案ができないですけれども、そうしたことを考えていっていただきたいなと思います。","respondent":"築山戸籍住民課長","answer":"訴訟費用については、原告側がどのように申し出るかというところになってくるかと思います。こういったことも含めまして、原告と連絡を取って額の確定をしたいと考えております。","voiceIndex":72,"id":"exchange-023"},{"speaker":"こしば委員","kind":"質問・要望","question":"この国家賠償請求事件なのですけれども、口頭弁論はもう全て出し尽くして、判決が既に確定したという認識でよろしかったですか。残念ですけれど、これがモデルケースになってしまって、端緒にもなってしまっていますので、そこを何としても覆していって信頼回復に努めていただきたいと思いますけれども、こちらは今後、区では公開される予定なのでしょうか。","respondent":"築山戸籍住民課長","answer":"研修についてです。繰り返しというところなのですけれども、これはもう深く反省しておりますので、引き続き継続して、職員が同様の過ちを起こさないよう、研修を徹底してまいりたいと考えております。","voiceIndex":75,"id":"exchange-024"},{"speaker":"こしば委員","kind":"質問・要望","question":"そうですね、もうとにかく徹底して、本当に１年に１回ではなくて、ワンシーズンに１回ぐらい、同じことでもいいので繰り返して、それこそテストも行って、この場合はどうですかといった、そこまでして、知識を血肉化していけるような研修をぜひ実施していただきたいと思いますし、先ほど、こんの委員からもありましたけれども、会計年度任用職員でも窓口業務に携わっておりますので、今回の件は。","respondent":"川島地域振興部長","answer":"１点、対応したところの知識不足というのもあったのですけれども、一つ大きな問題として大事なところが、組織的な対応が取れなかったという、係として、課として、区としてといったところもありますので、しっかり職員の教育、知識、研修等もありますし。","voiceIndex":77,"id":"exchange-025"}]},{"id":"topic-05","title":"中東情勢の変化に伴う区内中小企業向け特別相談窓口の開設","agenda":"中東情勢の変化に伴う区内中小企業向け特別相談窓口の開設","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"こちらの件、３月２６日から開設ということで、非常に早く動いていただきありがとうあります。非常に、区内中小企業、心配する声が届いているのですが、今までの相談件数というのは、現時点でどれぐらい来ているのでしょうか。","respondent":"吉岡地域産業振興課長","answer":"この特別相談窓口は開設して３週間弱となるのですけれども、この特別相談窓口でのご相談というのは今、１件もないというところではありますが、基本的に経営相談の中で、原油価格の高騰を心配して今後の資金の相談というところは、２件ほど把握しています。","voiceIndex":86,"id":"exchange-026"},{"speaker":"おぎの委員","kind":"意見","question":"普段から経営相談等で窓口があるので、そちらのほうで相談されている方もいらっしゃるのかなと思いました。ニュースなどを見ていますとやはり情勢が厳しいよねと、すごく皆さん心配されていますので、私のＳＮＳ等でこれを流してはいますけれども、広く告知も併せてお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-027"},{"speaker":"こんの委員","kind":"質問・要望","question":"早くから開設していただいてありがとうあります。その材料を求めて各企業が取り合いになってきているというようなところで、では今、何をしてほしいですかとお聞きすると、材料が入ってこないことには何も仕事にならない、だから財政支援がどうのとかいうレベルではないと。","respondent":"吉岡地域産業振興課長","answer":"そういったところを引き続き聞き取りながら、どういった具体的な施策に結びつけていくのか、実際の中東情勢の進行状況も見ながら、しっかりと検討していきたいと考えております。","voiceIndex":90,"id":"exchange-028"},{"speaker":"こんの委員","kind":"意見","question":"ご検討いただくのですが、というところで、具体的な支援というところを細かく、ご相談に来れば相談に乗るのですけれども、こんなことを相談してもね、と思って走っていらっしゃる企業も中にはいるかなという想像を巡らせていただきながら、具体的な支援策というところをお願いしたいなと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-029"}]},{"id":"topic-06","title":"しながわ観光プランの策定","agenda":"しながわ観光プランの策定","exchanges":[{"speaker":"おぎの委員","kind":"質問・要望","question":"私からは、質問というよりは要望が２点あります。両方とも要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-030"},{"speaker":"こんの委員","kind":"質問・要望","question":"ご参考までに伺いたいのですけれども、これまで計画を策定されてきて今回で３回目という形になるのでしょうか。前回、平成２８年に策定をされて、１０年たって今回は新しくしたと。どの辺がどんなふうに変わったのか、今回の計画の特徴などを教えていただきたいのが１点。それと、別添の資料として、全体計画は計画年数を定めない長期計画、一方で実施計画は３年程度という短中期の計画だと。","respondent":"大森文化観光戦略課長","answer":"大きなところの最終アウトカムとか中間アウトカムというところになると、なかなか理念的なものになっていくのですけれども、下に落ちていくに従って具体的な事柄に近づいてまいりますので、そこの基になるところが活動といった部分になるので、その活動の部分というのは。","voiceIndex":105,"id":"exchange-031"},{"speaker":"こんの委員","kind":"質問","question":"非常に大事なことだと思いますので、それを実際に展開したときに出てくるいろいろな不具合だとか課題だとか、スムーズにいかないな、みたいなところをいかにマッチングさせて、その事業を展開できるかというのが次、鍵かなとは思うところなので、そんなところはどう考えているのか、現時点でありましたら教えてください。","respondent":"大森文化観光戦略課長","answer":"これまでの都市型観光という名称はなくなりましたけれども、やはり、その礎、この１０年があって今があるというか、このプランにつながっていくとは思っているので、これまで一つずつ積み上げてきた地域の皆様との関係ですとか新しい情報を覚えておいて。","voiceIndex":107,"id":"exchange-032"},{"speaker":"こんの委員","kind":"質問・要望","question":"期待しておりますので、どうか、この計画が、より形として、区民の皆さんに「品川区って観光資源がたくさんあるんだね」といったことにつながるよう頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-033"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは今後に対して期待をしておりますので、要望とします。このインバウンドの誘客というのですか、今度、ラクロス世界選手権大会の来訪者対応、少し細かいことになるのですけれども、東京都で２回目になるのかな、東京都では大井ふ頭中央海浜公園のホッケー競技場と秩父宮ラグビー場で７月から開催するのが決定していますよね。","respondent":"大森文化観光戦略課長","answer":"先ほど、委員おっしゃられたとおりの日程でやるのですけれども、まず、ラクロスの選手の方、家族の方、それから、国外からも１６か国の方々がいらっしゃるというような形になっているので、品川区のいいところを知っていただければということで。","voiceIndex":111,"id":"exchange-034"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"全体計画を見たら、ラクロス世界選手権大会での来訪者対応ときちんと記載してあったのですが、何かまだ今、決まっているようで決まっていないということなのかなと、少し残念だった答弁でした。それで、一番直近だと７月にスポーツ系だとラクロスがあるわけではないですか。ロスオリンピックの競技にもなった。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-035"},{"speaker":"こしば委員","kind":"質問・要望","question":"観光の魅力というのは様々、品川区はたくさんあると思います。当然海岸エリアもそうですし、また、大井地域でしたら歴史がたくさん眠っております。その上で、まず、聞きたいのですが、区に、例えば観光業界、産業から、例えば、バスツアーをやりたいのだけれど、例えば品川区でこういったところ、こういう魅力的なところがありますか、などといったお問合せ等というのはこれまでは来ていたのですか。","respondent":"大森文化観光戦略課長","answer":"少ないながらも、少しずつそういった実績を積んでいるというようなところはありますので、最終的に品川区で収まる、それで皆さんが楽しんでいただければ、それは一番いいことなのですけれども、外に出ていただいても品川区を少しでも楽しんでいただくというところで考えますと。","voiceIndex":115,"id":"exchange-036"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひそれをマッチングしていただいて、新たなツアーの中に盛り込んで、多くの外国人の方も、また、国内の方も来られるような施策をぜひ取り組んでいただきたいと思いますし、例えば、お寺というのは一つの観光という形は表現が間違っているかもしれないですけれども、お寺で精神文化を体験していく、座禅を組んで、少し日常とは違う非日常の経験を体験していくというのも、区から少し。","respondent":"大森文化観光戦略課長","answer":"開けたお寺もあれば、やはりお墓を守るということがそもそものところであるので、やはり観光にはあまり協力できないよというふうに門戸を閉ざされるといったことも過去にありましたので、そういったところ、皆さん様々なご事情を抱えているなというところで、できるところから。","voiceIndex":117,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7365#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":42511,"voices":121}},{"id":"r08-20260414-7","meetingId":"r08-m0405","date":"2026年4月14日","dateIso":"2026-04-14","committee":"厚生委員会","time":"午後 １時００分～午後 ２時４２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"東品川三丁目における都有地（品川消防署東品川出張所跡地）を活用した認知症高齢者グループホームの整備・運営事業者の公募","agenda":"東品川三丁目における都有地（品川消防署東品川出張所跡地）を活用した認知症高齢者グループホームの整備・運営事業者の公募","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"それから４番のスケジュールのところで、４月下旬から事業者公募を行うということなのですけれども、公募要領はホームページに公表するということになるかなと思うのですが、それがいつ頃公表されるのかということと、できればその公募要領も厚生委員会に資料として出していただけると、私たちももう少し詳しく見ることができるので、私は厚生委員会にも資料として出していただきたいと思うのですけれども。","respondent":"宮澤福祉計画課長","answer":"それで、この間協議を東京都と進めておりまして、来月協定を結ぶ予定になっております。その協定のときに最終的な賃料というものが確定するという形になっておりますが、今回福祉インフラの整備という形で減額を受けている形になります。","voiceIndex":26,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"賃料についてなのですけれども、今福祉施設、区の土地を無償で提供というところが、結構この間も、例えば障害者のグループホームだったり、そのようなことで無償で提供ということでしてきて、民設民営にしてもそのようなところが多いと思うのですが、そのような中で、ここは東京都から借り受ける賃料をそのまま事業者に払ってもらうというようなことになるというのは、どのような判断で。","respondent":"宮澤福祉計画課長","answer":"賃料の設定については、今回減額が５０％以上で７７％の減額というところで、かなり一定的な金額よりは安い形になっているですが、区の負担なく、事業者に負担いただくというところで考えているところです。","voiceIndex":28,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その、何というのですか、無償で提供する、品川区の土地などを無償で提供して賃料を取らないというところと、今回のように、７７％助成があって結局２３％で済むということになるのですか、そのような、安いとはいえ賃料を事業者に払ってもらうというところの考え方というものは、区としての賃料、無償か、それとも有償かというか、賃料をもらうかというようなところの、どのような区としての考え方なのか。","respondent":"宮澤福祉計画課長","answer":"今、認知症高齢者グループホームの整備というものは他も進めているところでありますが、今回の土地に関しては、東京都の福祉インフラ整備事業という転貸のスキームを使って建てるというところで賃料が発生するというところで。","voiceIndex":30,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問","question":"今回は区が東京都から借り受けて民設民営というようなことになるということなのですけれども、東京都から区が借り受けて、区立にして指定管理者という、そのような区立で運営にも責任を持つということもあるのではないかなと思いますし、この委員会の中でも、やはり区立にしてやるべきだという意見がかなり毎回出ているのですが、そのようなところというものは、区立にして指定管理者での委託という。","respondent":"宮澤福祉計画課長","answer":"したがって、自治体が借り受けた上で民間法人等に貸し出すというスキームを活用しておりますので、区が所有するという形ではなく、貸し出すことを前提としておりますので、借り受けたところが建設して民設民営という形になってあります。","voiceIndex":32,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"確認","question":"ということは、東京都が民設民営というようなことで、区が借り受けたとしても民設民営で行うというスキームというものを、既に土地を定期借地で貸すところで、スキームまで東京都が決めてしまっているという、そのようなことなのか、ちょっとその点確認させてください。","respondent":"宮澤福祉計画課長","answer":"今回、東京都の福祉インフラ整備事業に係る都有地等の区市町村貸付に伴う実施要綱というものを活用してやっておりまして、もうこの要綱自体が転貸を前提としたもので、民間法人等への貸付けという形が決められているところです。","voiceIndex":34,"id":"exchange-005"},{"speaker":"やなぎさわ委員","kind":"質問","question":"何点か上からお伺いしたいのですけれども、まず１番の都有地および整備方法の概要のところなのですが、恐らく２７人程度の認知症高齢者グループホームにするには結構ぎりぎりの敷地面積なのかなとは思っていまして、大体これぐらいの２７人だと、１,０００平米から１,２００平米ぐらい必要だと思います。すみません。すみません、ちょっと４点ほどになりましたけれども、お願いいたします。","respondent":"宮澤福祉計画課長","answer":"一方で補助金に関しては、東京都の補助金も令和７年度から令和８年度にかけて補助金の増額というところも行われておりますので、そういったところで一定程度のカバーができるのかと考えているところです。","voiceIndex":38,"id":"exchange-006"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"心配なことが、四、五階建てになると、ここの用地は海側を首都高が走っているのです。幸いここ、何というのですか、準工業地域で、たまたま周りは、目の前は都営アパートだったり、その向かい側は何か業者向けの資材屋のようなもので、それほどうるさくはないと思うのですけれども、やはり認知症の方のグループホームといったら静かな環境を整えてあげる必要はあると思うのです。","respondent":"宮澤福祉計画課長","answer":"スケジュールにつきましては先ほどのとおりで、令和１１年３月の末までを開設時期という形で、現在検討しています。過去の事例等々を見て、できると考えての設定です。","voiceIndex":40,"id":"exchange-007"},{"speaker":"やなぎさわ委員","kind":"意見","question":"分かりました。そうですね。スケジュールは今までの実績では大丈夫ということだったのですが、やはり社会情勢も大分変わっておりますし、今イランに絡む問題なども含めて、様々なものが流通が止まりかけているというようなことも、医療関係含めてあるということで聞いておりますので、その辺はぜひ柔軟に対応していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"皆さんの質疑で大分状況が分かってまいりましたが、１点気になることが、住民説明会が４月２８日ということで、もう間もなくと思うのですけれども、この住民説明会があるということのお知らせということは、だからここにどのようなものが建っていくのでというものが事前の情報としてあるということなのだと思うのですが、その地域の方たちにこの計画があるというお知らせは。","respondent":"宮澤福祉計画課長","answer":"住民説明会に向けて、近隣の住民の方にチラシというものを配布いたします。４月２８日に実施するです。区のホームページ等でのお知らせというものも、併せてしているところではありますけれども、この住民説明会の際に、概要については説明するです。","voiceIndex":44,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。できたら、やはり、もう今さらしようがないですけれども、このような情報は地域の方たちにはなるべく早く提供していただきたかったなということがあります。今からでも。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"提案","question":"その前にもうゆうゆうプラザができてしまったのですけれども、そのような意味で、この併設する施設というところについては、福祉施設に限るという意味なのか、福祉事業者がやるのでしょうからそのようなこともあるのでしょうが、何か地域の方に、当時は、例えばゆうゆうプラザが実現しましたけれども、子育てや地域の方のコミュニティの仕掛けになるようなもののようなことを要望していたのですが。","respondent":"宮澤福祉計画課長","answer":"委員ご指摘のとおり、隣にゆうゆうプラザ等もありますので、そことの何か連携的なものができるかどうか、そういったところをプロポーザルで見させていただきながら判断していくということを考えているところです。","voiceIndex":48,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"提案","question":"そういった点も踏まえて、公共施設が少ないという地域、本当にそこに固まっている、広い広い東品川三丁目、四丁目の町会の中にというところも踏まえて、ちょっと提案の仕様の仕方のようなものも、ぜひ事情としてお伝えいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-012"},{"speaker":"やなぎさわ委員","kind":"提案","question":"今あくつ委員からお話あった、１つだけ。この募集、公募の要項のところに、先ほどの併設施設、希望する場合には事前に区と協議が必要とあるのですけれども、今お話ししていたプロポーザルのときに提案ということなのか、もしくはその前に一度区のほうに確認してみて、何かオーケー出てからプロポーザルで提案なのか、その辺の流れをちょっとご説明いただきたいのですけれども。","respondent":"宮澤福祉計画課長","answer":"プロポーザルでの提案にはなります。ただその中で、公募の事業者説明会というものを実施いたします。希望される方はこれ参加が必須という形になりますので、その中で、公募説明会の中で質疑応答があれば対応していくです。","voiceIndex":52,"id":"exchange-013"}]},{"id":"topic-02","title":"品川区立小山台福祉園および品川区立小山台児童発達支援センター指定管理者候補者の公募","agenda":"品川区立小山台福祉園および品川区立小山台児童発達支援センター指定管理者候補者の公募","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"私、すごい単純なあれなのですけれども、４月ということは今ですよね。今、公募要項の公表ということなのですが、今日が１４日、そしてこれから４月中に要項が発表されるということなのでしょうか。","respondent":"石橋障害者施策推進課長","answer":"公募の要項の公表ということになりますが、こちらホームページで、今週の金曜日、４月１７日より公募の要項の公表を行う予定となっております。","voiceIndex":58,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"今までいろいろな公募をしても、なかなかいろいろなところから手を挙げてくださる方が少ないということが、この福祉の施設に限らず、もう少し早く、広く公募することはできないのかということを別の委員会でも私発言した覚えがあるのですけれども、その辺の広く応募していただくような、何か表現上の工夫なのか、それともそのような公募をしていますということを広く知らせる方法など。","respondent":"石橋障害者施策推進課長","answer":"公募の工夫というところになりますけれども、こちら３月の上旬の１週間から２週間あたりにかけまして、都内のおよそ１,５００の法人に対して、今回の本事業についての事前のご案内ということでファクスで通知をさせていただきまして。","voiceIndex":60,"id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"だからそのファクス等でということはよかったと。そのようなことをやってくださってよかったなと思うのですけれども、それに対しての何か反応など、正式な応募はこれからとしても、問合せやよい感触など、何かそのようなものがあったら教えていただきたいのですが、いかがでしょうか。","respondent":"石橋障害者施策推進課長","answer":"ファクスを送らせていただいて、１,５００のかなり大規模に送らせていただいたので、その返りというものがそこまで多くあったわけではないのですけれども、私どもの課のほうで。","voiceIndex":62,"id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"努力してくださってよかったと思います。これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ということは、私はちょっと厚生委員会にも資料として、今は資料を印刷はしていないので、サイドブックスの中に入れていただくだけなので、ぜひ資料として出していただきたいなと思います。そのようなものが、より、何というのですか、この審議をするに当たり、より理解が深まるような形での資料の提供ということで、ぜひお願いしたいと思います。その点が１つです。","respondent":"石橋障害者施策推進課長","answer":"障害者団体の方への説明というところ、今のところはちょっと、今までもやっておりませんし、今のところ本件に関しては、説明をするとか、ご意見を聴くということは、予定していないところではありますが、引き続き、何かこういった機会を捉えて。","voiceIndex":66,"id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問","question":"このようなスケジュールなども含めて、結構どうなっているのだろうという、そのような質問を受けることも結構あるのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問","question":"それ以外にも、もちろんその６事業を一括で新規申請するということは、私も介護施設ですけれども、申請の経験ありますが、結構大変だなと思っておりまして、この辺のスケジュール的に１年１か月というものが妥当なのかというところの受け止めをお伺いしたいということと、あとこの選定のスケジュール、今後の予定のところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-020"},{"speaker":"やなぎさわ委員","kind":"質問","question":"やっているようです。すみません。では、それはいいです。すみません。今のはすみません、訂正させていただいて、スケジュール感だけお伺いできればと思います。いかがでしょうか。","respondent":"石橋障害者施策推進課長","answer":"既に経験もしている、そういった知識もしっかりと持っている事業所のほうにお願いしたいと思いますので、そういったところでしっかりと協定を結んでから、区とのほうも連携を取りまして、スケジュールの遅れがないように対応していきたいと考えております。","voiceIndex":71,"id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ちょっと話変わるのですけれども、ちょっとごめんなさい、私の認識が間違っていたらご指摘いただきたいのですが、１番のところで、今回、品川区立大原児童発達支援センター条例の改正を根拠に設置されるということだと思うのですけれども、大原児童発達支援センターの開設のときはそれ用の条例を１つつくったかなと思っていて、今回はどうしてその横引きのような感じでなっていて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-022"}]},{"id":"topic-03","title":"品川区新型インフルエンザ等対策行動計画（改定）素案にかかるパブリックコメントの実施等","agenda":"品川区新型インフルエンザ等対策行動計画（改定）素案にかかるパブリックコメントの実施等","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"それともう一つは、やはり検査のことも伺いたかったのですけれども、今回は網羅的に書いてあるのかもしれませんが、積極的疫学調査というのですか、いろいろな考え方があのときもあって、悉皆にやるべきだとか、そうですよね、いろいろな考え方があった中で、この中にはどうまとめられているのか、これは新型コロナに関するだけではない行動計画だとは思うのですけれども、その辺り。","respondent":"五十嵐保健予防課長","answer":"医療の部分がありますが、医療の部分に関しましては、主には東京都が調整する部分になっておりますので、なかなかその入院の調整の部分などが、区がどのぐらい入り込めるかというところは難しいところもありますし、実際ちょっとそこまで書き込めていない部分はありますが。","voiceIndex":80,"id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問・要望","question":"この行動計画と私が問題提起させていただいたようなことというものは、ちょっとマッチングしないところもあるのかなと私も思いながらも質問したのですけれども、せっかくこのような行動計画をつくっていただいているので、こういったものを背景に、先ほど前と比べればお互い顔の見える関係、医師会との関係というものは、当然それは進んできているのかなとは思うのですが、ぜひそういったところについても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのようなところで、パブリックコメントを取るに当たっては、これから重要な計画に対しては、区としても説明会を行う方向で検討しますということを、以前質問をしたときにそのようなご答弁をいただいていたのですけれども、今回パブリックコメントを行うに当たり、説明会というものは検討されなかったのか、説明会がされないのはどうしてなのかということをまず１つ伺いたいと思います。","respondent":"五十嵐保健予防課長","answer":"説明会について、今回も一応検討はさせていただいたのですが、取りあえず今回はＹｏｕＴｕｂｅで説明している動画を作らせていただきまして、そちらを一緒に見ていただけるような形で、ホームページのほうから見ていただくことができるような形でやらせていただくということで。","voiceIndex":83,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問","question":"でもここで見つからなかったのですけれども、ここには載せていないのでしょうか。私は載せていただいたほうがいいのではないかと思うのですけれども、なぜなのかも含めてその点を伺いたいと思います。","respondent":"五十嵐保健予防課長","answer":"計画改定検討委員会につきましては１回やらせていただいて、あとパブリックコメントをしていますが、そちらが終わったら、その結果を基にまたもう１回やらせていただいて、その２回という形で考えているところです。","voiceIndex":85,"id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問","question":"そうですよね。それからあと、新型コロナ対応で課題となった事項を独立させるなど、その対策項目を８から１３に増やしたというようなことで書かれているのですけれども、その増やされた５つの項目というものは、ここ１３項目になっていますが、どれが増やされた項目なのかということをちょっと教えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのようなところで、コロナの反省を活かすとなったらば、保健所の体制というものの強化、それから、これから具体的に実効あるものにしていくというためにも、様々なことの検討だったり、連携だったり、具体化などが求められると思うのですけれども、そのときに保健所や保健予防課などの体制強化というものが必要になってくるのかなというような思いがしたのですが、その辺の体制強化という点では。","respondent":"五十嵐保健予防課長","answer":"まるっと新しい感染症ができまして、ふだんの仕事以上の仕事をしなければいけなくなったので、当然健康課なり、保健予防課や健康推進部だけでは担えない部分があったと思うのですが、その部分を今までと同じ仕事をしながら役所でやるということは到底無理な話ですので。","voiceIndex":93,"id":"exchange-028"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのような医療機関というものは、品川区ではここなのだよというような公表というものはされるのかということと、また、その医療機関というものは区内では十分確保されているということなのか、その辺のところは区としてはどう判断されているのかというあたりについても伺えたらと思います。","respondent":"五十嵐保健予防課長","answer":"〔５月１１日の厚生委員会において「東京都のホームページ上に公表されておりました」と報告あり〕一応コロナのかなり流行した時期に必要な医療機関の数が出ましたので、それについては提携できているという状況になってあります。","voiceIndex":95,"id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もう一つ、本当にコロナの感染のときは、検査なども本当に受けることが大変で、この品川区でも駐車場のところに医師会で体制を取って、検査場をつくってやったりなどというようなこともあったなと思い出したのですけれども、そのような検査体制などはきちんと取られていくということになっていくのか、それはどこに記されているのかというあたりも教えていただきたいということと、それからすごい。","respondent":"五十嵐保健予防課長","answer":"今ワクチンを国内でもつくれるようにということで、厚生労働省のほうでも考えているようですので、そのような部分は厚生労働省にお任せしつつ、ワクチンもきちんとできてきた場合には皆さんに速やかに接種していただけるようにということ。","voiceIndex":97,"id":"exchange-030"},{"speaker":"鈴木委員","kind":"質問・要望","question":"いろいろあると。そのようなところで、区民の側にとっても、本当にいろいろな、これからもしも同じようなことが起こったら、そのような教訓を活かしていただきたいなというような思いというものはすごく強くあると思いますので、そのような区民への周知や何かも含めて、今後取り組んでいただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"確認","question":"今後のスケジュールのところで、パブリックコメントの閲覧場所なのですけれども、保健予防課と区政資料コーナーということなのですが、もう少し増やしてもいいのかなと思いまして、例えば保健センターや地域センターなど、せっかくやるならもっと広げてみてはいかがかなと思うのですが、その点いかがでしょうか。","respondent":"五十嵐保健予防課長","answer":"ある程度区のほうで決められているというお話は聞いておりますが、可能であれば、閲覧場所とできるころがあれば、ちょっと検討はさせていただきたいと思います。","voiceIndex":104,"id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ぜひ前向きに検討していただければと思います。ちなみになのですけれども、類似の、以前計画を立てられた品川区の感染症予防計画や健康危機対処計画ですか、こういったものはパブリックコメントを取られていたのか、取られていたなら、もし手元に今数字があれば、どれぐらいの件数が来ていたのか、分かればでいいのですけれども、いかがでしょうか。","respondent":"五十嵐保健予防課長","answer":"品川区健康危機対処計画につきましては、基本的には内部のマニュアルということで、特に外に知らせるものではないということで、パブリックコメントは実施していないところです。","voiceIndex":106,"id":"exchange-033"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"最初の質問と重なるのですけれども、やはりより多くの方にコメント、パブリックコメントをいただけるような環境を整えていただけることを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-034"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"そこで報告された中身も、ぜひ厚生委員会にも報告していただきたいと思いますので、それをぜひお願いできないでしょうかということです。それで、これから５歳児健診をさらに今年度増やしていくという方向が出されているわけですけれども、その検証の報告、検証ごとに拡大していくわけですから、その検証結果についてご報告をいただきたいということで、お願いしたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-035"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"昨年の夏場に行われました高齢者熱中症見守り宅配事業なのですけれども、終了してアンケートも取られていたかと思いますので、その辺の報告もぜひ、そろそろ上がってくるのかなと思っているのですが、委員会での報告を要望したいのですけれども。","respondent":"田中委員長","answer":"ではそれも、高齢者熱中症見守り宅配事業の結果についても正副で協議をし、また理事者とも調整をさせていただいた上で、対応していきたいと思います。ほかにありますでしょうか。ほかにないようですので、以上でその他を終了いたします。以上で本日の予定は全て終了いたしました。","voiceIndex":117,"id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7363#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":31066,"voices":118}},{"id":"r08-20260414-8","meetingId":"r08-m0405","date":"2026年4月14日","dateIso":"2026-04-14","committee":"建設委員会","time":"午後 １時００分～午後 ５時３１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和８年陳情第１３号（品川浦周辺地区まちづくりガイドライン）","agenda":"令和８年陳情第１３号（品川浦周辺地区まちづくりガイドライン）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"最初に細かい質問であれなのですが、別紙２の３ページの下から２番目の黒丸で、「品川区が所有している大きい土地を防災施設にしてほしい」とあるのですが、区が、現在、開発区域内に所有しているまちづくり用地とは、どこに、どれぐらいあって、それをどう使おうとしているのかを伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"ガイドラインにつきましては、現在、まちづくりの検討が進められている地域に対しまして、区としての市街地将来像だとか、その具体的な方策等をしっかりと明示するために検討しているものでございまして、原則的には、まちづくりの検討が進められている範囲。","voiceIndex":18,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"既に開発地域内にまちづくり用地があるわけですよね。私もそうだと思います。このまちづくり用地について、そういった意見があるのですけれども、これをなぜ再開発種地として取得したのか伺いたいと思います。それでもいいとお考えなのでしょうかとか、「○○をつくりたいから再開発を使って住民をどかせようというのは、乱暴かつ住民の人権を無視した発想」だというようなことが書いてあります。","respondent":"大石まちづくり立体化担当課長","answer":"一方で、今後の整備の検討に当たりましては、実際にどのような施設がこの地域にふさわしいのかというところにつきましても、先ほどご答弁したとおり、地域としっかりと話し合って、具体な施設の検討については、今後、区として決定していきたいと考えているところです。","voiceIndex":20,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"種地ではないということでした。再開発の地域の中にあるものですから、これをどういうふうに活用していくのかというのは、大変重要だと思うので、区としてきちんと主体性を持って、ぜひ住民の意見を聞いて進めていくということを堅持していただきたいと思います。ですから、品川区が、やはり住民の声をまず主体で話し合ってもらう。これについて、品川区の意見を、受け止めを伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"１点目の準備組合ではなく区が主体となってですけれども、当然、区といたしましても、再開発事業に対して不安や懸念があって準備組合と直接お話しすることが難しい方、こういった方につきましては、個別に区にお問合せいただければ、可能な限りのご回答をするとともに。","voiceIndex":22,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"私もそう思うのですけれども、そういう陳情項目１は、やはり私も盛り込むべきだと思うのですけれども、いかがでしょうかという質問をしたいと思います。今後は、区として、こういったところを把握、必要な場面では発表するという姿勢になったのだと、そういう姿勢になりましたよということでいいのか、そこについては、少し確認をさせていただきたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"このため区といたしましては、いただいたご意見も踏まえまして、改めて準備組合に対して丁寧な対応を行うよう指導してまいりたい、このように考えているところです。","voiceIndex":24,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、ガイドラインに、そういう住民要望に応じて対象地域を柔軟に変えていくとか、そういったことはやはり盛り込むべきなのではないかと、盛り込んでいただきたいなというふうに思います。先日の予算特別委員会でも私も質問させていただきました。陳情項目２の内容に関わって、もう一つ伺いたいのですけれども、不利益な情報がたくさんあるのだと、でも、隠されているのだという記述があります。","respondent":"大石まちづくり立体化担当課長、高梨都市計画課長","answer":"ただ一方で、こういったことを準備組合がしっかりと説明をすることがまずは重要なことであると考えておりますので、区といたしましては、準備組合に対しまして、改めて再開発の事業とは一体どういったものなのか。この会長は、改選が行われた際に都市計画審議会の委員の互選により指名がされているというような形で選ばれているものでございまして、今後の方向性といたしましては、今年の７月が委員の改選の時期に当たりますので。","voiceIndex":26,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。ですから、そこの再開発の準備組合の動きに区がかぶせていくような動きをしてしまうと、品川区自体が、行政が再開発を後押ししているように当然見えるわけです。最後、地域のまちづくりのガイドラインであれば、いろいろ不利な情報が隠されているのではないかと指摘をさせていただきました。これについては、ぜひ盛り込むべきなのではないかと思うのですけれども、最後に伺います。","respondent":"大石まちづくり立体化担当課長","answer":"区としてまちづくりの将来像をしっかり示すことで、地域住民の意見が反映されたまちとなるように、ガイドラインの策定作業を進めているのですけれども、様々地域から意見をいただいているところでございまして。","voiceIndex":29,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川浦の再開発ということで、対象地域の住民本位の縮小、知る権利、居住権の保護の明文化を求める陳情であります。住民の皆さんが議会に陳情する際に、とても勇気が要るという話も伺います。なので、品川区に伺いたいと思いますけれども、そうしたタワーマンション建設などの高層化や再開発を進めてほしいという意見はあったのか、なかったということでよいのか伺います。","respondent":"大石まちづくり立体化担当課長","answer":"意見交換会において、いわゆるタワーマンションの建設を進めるという意見があったのかですけれども、こちらにつきましては、冒頭申したとおり、再開発とは切り離して意見交換会を開催してございまして、区が考える４つのテーマ、４つの課題ですけれども。","voiceIndex":31,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"ただ、冒頭に説明があって、区の４つのテーマがあって、それについての意見交換をしたということですけれども、その４つのテーマというのは何だったのか改めて伺いたい。ざっくりと聞いても、区ははっきりなかなかおっしゃってくれないのだけれども、陳情者も知りたいでしょうし、私も知りたいので、反対多数の意見交換会は、今後、まちづくりガイドラインにどう反映するのか伺います。","respondent":"大石まちづくり立体化担当課長","answer":"そういった中で、区として、より多く、よりきめ細やかに意見を把握するためには、１つアンケートという手法も検討していますので、それらの意見を集約した上で、今後、どのように記載をしていくかは考えていきたいと考えているところです。","voiceIndex":33,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"次のフェーズで議論するまでもなく、再開発という手法はやめるべきだと、これが区民の声だと、地域の声だと、区が主催した中で１人もいなかったのですから、今の課長の説明では。ですから、手法については次のフェーズだという説明がありましたけれども、次のフェーズにて再開発という手法はとるべきではないと、次のフェーズで再開発という手法を検討する必要はないと思いますが、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"目標といたしましては、年内にアンケートの配布をしたいなと考えているところですが、具体的な日程については、これから検討してまいりたいと考えているところです。アンケートの対象範囲や設問数、どういった項目にするのかというところも、今はまだ検討しています。","voiceIndex":35,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"これをゆがめて、今後、再開発に区が誘導していくことは決してあってはならないと強く求めておきたいと思います。もっと言ったら、全て対象者の方々に、こういう決定をするのですけれども、賛成ですか、反対ですかと、準備組合なのか、その会議の場なのか、様々な場で、何の話合いもなく決められたのかと。なぜ話合いもなく範囲が決められたのか、そこについても伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"設立時点で約７割の方が参加されているというところで、一定のまちづくりの機運が高まっているのかなというところで、区としては、賛成、反対というところではないのですけれども、そういった形で今後検討が進められていくというふうに受け止めていたところです。","voiceIndex":37,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"このようなことが許されていいのですか。このような決めた方でいいのですか。「その後の生活がままならなくなってしまう住民宅を再開発区域から除外する方向での見直しを要望します」ということです。それだけに、本会議や建設委員会での質疑をぜひ伝えていただきたいと、前も要望したと思うのですけれども、そこのところはいかがか、まとめてになりましたけれども、それぞれご答弁ください。","respondent":"大石まちづくり立体化担当課長、高梨都市計画課長","answer":"これに対して、区が範囲から外せというところを指導できるのか、仕組み上できるのかというところにもつながるのですけれども、こちらは、仕組みとして、できる、できないというところよりは、皆様の話合いの中で。そこで一定程度、議会の動き等についても情報提供をしていますが、答弁や質疑の資料提供については、今後、説明の中で、どのような形でできるか検討してまいりたいと考えています。","voiceIndex":39,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ品川区として行政を担っているわけですから、少なくとも地域の方々が強く反対しているこの品川浦の再開発は、１ミリも進めるべきではないと、まずはアンケートの話、スケジュールはまだということですけれども、丁寧な住民の意見の聞き取りを強く要望したいと思います。都市計画審議会にかかる前の説明会にも来てほしい。今以上に丁寧な対応を強く求めておきたいと思います。","respondent":"中道都市開発課長","answer":"それにつきましては、区といたしましても、まちづくりニュースの中でそういったご説明をする、または、疑問等がありましたら、区にどんどんご連絡いただいて、ご理解、内容の把握に努めていければと考えるとともに、予算特別委員会の場でもご説明したとおり、また。","voiceIndex":42,"id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"１点だけ確認させていただきたいと思います。陳情項目の２のところで、「地上げ屋による放火等の防犯も要望します」ということで記載されていますが、こういった不安の声について、区で行っている支援とか、情報提供などを行っていく、区として対応をされるのか、こういった点についてお聞きできればと思います。","respondent":"大石まちづくり立体化担当課長","answer":"町会・自治会や商店街などの地域団体が防犯カメラを設置する際に、補助金で支援を実施するとともに、個人宅において防犯対策品を購入、設置した場合に、費用の一部を助成するといった対策をしています。","voiceIndex":44,"id":"exchange-013"},{"speaker":"せお副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。そこの相互理解だったり、合意形成だったりというところがなされるように、基本的には、地域準備が中心となるわけですけれども、区が引き続き間に入って、１２月にもワークショップを開催してくださいましたし、これからアンケートもするということですので、引き続き、できるだけの対応をお願いしたいということは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-014"},{"speaker":"松永委員","kind":"質問・要望","question":"現段階で、特定の除外のルールを急いで決めるものではなくて、かえって将来の１０年的な話合いで、私たちは決めていくべきではないかと思います。最後に、先ほども意見交換の後にアンケートを皆さん一人ずつとっていく、または、先ほど、せお副委員長もありましたけれども、全体に、ぜひ皆さんが、方向性をどう求めているのかということを把握しながら進めていくべきだということを考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-015"},{"speaker":"ゆきた委員","kind":"確認","question":"陳情項目１については、再開発地域については、地域全体の一体的なまちづくりを前提として策定されるものであり、地域主体の合意に基づいた検討区域を基本としているということを確認させていただきました。陳情項目２についても、ガイドラインに合わせてとありますが、ガイドラインでは、あくまでまちづくりの方向性を示すものであるということも確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"区長も、まちづくりの主体は、そこに住む地域住民と述べているわけですから、それを仮に現実とするのであれば、やはり陳情者がここで求めているような再開発地域の住民意見に応じた見直しですとか、圧倒的に有利な立場に立つ開発企業の横暴を抑える適切なルールやガイドラインを区が持つということは私は必要なことだと思います。したがって、本日の陳情は採択すべきだと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、都市開発課長から、今後、国と意見交換の場があると、あとまた、窓口も設置するということでしたので、ぜひ建設委員会に、動きがある場合にはご報告いただきたいと思います。区が何を求めて、国がどのような回答があったのか、窓口がどのように設置され、運用されているのか、見通しがついた時点で、建設委員会に報告していただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-018"}]},{"id":"topic-02","title":"東京における都市計画道路の整備方針の策定","agenda":"東京における都市計画道路の整備方針の策定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２点伺いたいのですが、まず、補助１６３号線が優先整備路線になったのですが、現に生活を営んでいる住民もいらっしゃる路線だと思うのです。その中で、どうしてもこれを整備しなくてはいけないとは、私たちは認識していないのですけれども、具体的な整備事業効果について、区としては、どのように認識しているのか、改めて伺いたいと思います。それだけです。","respondent":"高梨都市計画課長","answer":"そういった内容から必要性が高いということで、前回の計画から引き続き優先整備路線に位置づけられているところです。現在、住宅の戸数が何戸かにつきましては、今後、事業化に向けた検討を行う中で把握してまいりたいと考えています。","voiceIndex":59,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"事業中であっても、私は、こういう特定整備路線も、必要性などを踏まえて廃止するかどうか検討すべきなのではないかなと、今回なぜ検討の対象外とされたのか。私は、廃止も含め検討すべきだったのではないかなと思うのですけれども、そうしたことに対して、区として何か意見を言ったということもあるのかということも含めて、この辺の区の認識を伺いたいと思います。","respondent":"高梨都市計画課長","answer":"事業化に当たりましては、必要性が確認され、国から事業認可を取得して事業が進められているものですので、それらの路線について、今回の検討対象から除外するといったことは、区としても同意をしているところでございまして、この点について。","voiceIndex":61,"id":"exchange-020"},{"speaker":"安藤委員","kind":"意見","question":"最後に少し補助１６３号線の、これ、道路行政のこれからの手続の話になってくるかもしれないのですけれども、実際にそこに住んでいる方への働きかけというか、意見聴取とかは、具体的には、どの段階で、これ、優先整備の路線に引き続き指定されたということは、１５年の間に事業着手するということが予定されていると思うのですけれども、具体的にどういうところで。","respondent":"森道路課長","answer":"昨年度、債務負担行為等の議決をいただきましたけれども、そこの大崎線の交差部、そこにつきましても、今、ＪＲと具体的なお話をさせていただいているところですので、１５年のうちで着手を目指すというところで、具体には。","voiceIndex":63,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"振り返ってみれば、今、道路課長が最後のほうにおっしゃった補正予算の負担行為に、かれこれ１年半ぐらいですか、この計画を議論させていただきまして、私もいろいろ述べさせていただきました。この計画は中止すべきだと考えています。こうしたものは進めるべきではないと多くの住民が願っていると思いますが、その点も伺いたいと思います。","respondent":"高梨都市計画課長","answer":"何を期待するのかといったところですが、こういった形で、東京都、都市計画道路を有する自治体全体で計画を公表しているわけですから、しっかりと優先整備路線であるとか、また、廃止候補路線等も、今ご説明させていただきましたとおり。","voiceIndex":65,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"そこで伺いたいのですけれども、１月１９日の答弁も改めて見ましたけれども、課長の説明で、優先整備路線の選定の中でも持続可能な地域へのまちづくりの貢献ということで、市街地再開発事業や鉄道立体化事業などの連携を図っていくような地区については、優先的にそういったところに関して、路線は優先整備路線に選定されるということが、この計画の中に位置づいているとおっしゃっております。","respondent":"高梨都市計画課長","answer":"ご案内のとおり、実際、建物を建てる際には、前面等の幅員であるとか、そういったところが大きなファクターになっているといったところは事実ですけれども、まだ、機が熟していないような段階で、品川区として優先整備路線を特例の再開発事業を念頭にした上で。","voiceIndex":67,"id":"exchange-023"},{"speaker":"中塚委員","kind":"確認","question":"区域の中は優先整備路線としては指定されていないと私も確認しております。補助１６３号線については、まさに区役所前ですから、ここが事業認可されないと、区の現庁舎の跡の建物の建築許可が下りないわけです。そういう関係で、補助１６３号線も新たな再開発につながるものだと思います。いずれにしても、新たな再開発をつくっていく地域を広げていく本計画は、中止すべきだと述べて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-024"},{"speaker":"ゆきた委員","kind":"確認","question":"前回の委員会では、区において、約３週間にわたり社会実験を実施し、約１２０件の意見を把握しているとのことで、４月のまちづくり特別委員会にて報告するとも伺っていましたが、現時点で把握している範囲でどのような傾向が見えてきているのかお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-025"}]},{"id":"topic-03","title":"令和８年度からの不燃化特区支援制度等","agenda":"令和８年度からの不燃化特区支援制度等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、放射２号線と補助２８号線の沿道地区は、不燃領域率が７０％に達したため除外とあるのですけれども、７０％という数字は、どのような効果があるのかを伺いたいと思います。","respondent":"小川木密整備推進課長","answer":"１点目の不燃化特区支援制度と整備地域等不燃化集中促進支援制度との違いです。資料裏面に記載していますが、不燃化特区支援制度に関しましては、工事費が助成対象となりますけれども、集中促進支援制度に関しましては、工事費は対象外という形になります。","voiceIndex":83,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"ですから、私は、道路そのものを造る必要性がもうなくなったのだと思うのです。なおさらだと思いますので、いかがでしょうか。１つ目の質問です。それが耐震化を徹底的に進めることになると思うのかどうかという認識を伺いたいのと、仮に、その実現に向けての課題といいますか、こういった手厚い建て替え支援を全区に広げていく上での課題は何だと考えているのか伺いたいと思います。","respondent":"高梨都市計画課長、小川木密整備推進課長","answer":"市街地の不燃化、耐震化と、延焼遮断帯や避難物、緊急車両の通行路となる特定整備路線を複合的に重層的に進めていくことが防災まちづくりとして重要なことである、このように認識しています。全区的に行うに当たっての課題ですが、不燃化特区支援制度につきましては、非常に充実した助成内容、金額の設定をさせていただいておりまして、そういったところでは、区域を拡大することによって。","voiceIndex":85,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"すみません、最初に聞けばよかったのですけれども、放射２号線と補助２８号線の沿道地区は、除外ということで７０％に達したということなのですが、補助２９号線沿道地区の不燃化領域率は、現在、何％なのか、それだけ最後にお伺いします。","respondent":"小川木密整備推進課長","answer":"最新の時点が令和７年１２月時点の不燃領域率の数値になりますけれども、補助２９号線沿道に関しましては、５４.８％です。","voiceIndex":88,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"しかし、準耐火建築物、つまり、木造の新築の建物であれば、隣で火災が発生しても、建築課に伺いたいのは、何時間耐えられるのかということを伺いたいのです。防火の窓ガラス、軒下の防火、あと、壁自体の防火、いわゆる準耐火建築物は、たしか１時間とか２時間かかる、これも建築課長に教えていただきたいのですけれども、一定期間、隣の火災を防ぐだけの素材を使っているというお話を伺うのです。","respondent":"小川木密整備推進課長、森建築課長、遠藤防災体制整備担当課長","answer":"こちらは試算しているわけではございませんので正確な数字を申し上げることはできませんけれども。準耐火建築物が耐えられる時間ですけれども、準耐火建築物は、通常の火事等に４５分間耐えられるようにしなければならない。東京都も感震ブレーカーの動き、また、今年度、東京都が新たに被害想定を示すといったところで、国や都の動向を踏まえながら。","voiceIndex":90,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて、ぜひ試算をした上で、区の負担がどれぐらい増えるのか、財政負担という根拠は、ぜひ試算をしていただきたいと思いますが、いかがでしょうか。ですから、準耐火建築物にお住まいの方は、家を出かけるときには窓を閉めて出かけていただきたいと。質問としては、効果はあるけれども、財政負担だけが原因なのか、効果としては全区に広げたほうがいいと思っていらっしゃるのか、この点を伺います。","respondent":"小川木密整備推進課長、遠藤防災体制整備担当課長","answer":"東京都と協調補助で取り組む支援制度になっておりまして、都の指定基準では、整備地域という、特に震災時、甚大な被害が想定される地域にまずは絞って、そこで特に危険な地域を指定して、まずは危険度の高いところを早急に。先ほど、感震ブレーカーの区内全域への支援の展開の検討の件で、１点訂正といいますか、まず、感震ブレーカーに関しましては、現在、木造住宅を中心に支援をしています。","voiceIndex":94,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"なのに、なぜ東京都の協調を強調するのか私は分かりません。大きな火災や地震から区民を守るためには、東京都の協調というよりも、区民の暮らしや生活こそ直視すべきだと思いますが、いかがでしょうか。被害の甚大さを強調するのであれば、やはり一つ一つの住宅を安全にしていく、この視点に立って考えるべきだと思いますが、最後にいかがでしょうか。","respondent":"小川木密整備推進課長","answer":"そういった声に区独自でしっかりお答えすると、対応するといったところで、今回、提案をさせていただいて、1)番の加算助成に関しましては、区独自策としてやらせていただくと。","voiceIndex":97,"id":"exchange-031"},{"speaker":"ゆきた委員","kind":"質問","question":"今回の取組は、大変意義のある取組だと感じています。前回の都市防災不燃化促進事業の答弁では、対象者への直接的なパンフレットの配布、福祉系の協議会などでの案内、福祉系イベントでのパンフレットの配布について話がありましたが、対象者へのキーパーソンとなる方々へのアプローチの仕方について、福祉部門とどう連携してアプローチしていくのかお聞きしたいと思います。","respondent":"小川木密整備推進課長","answer":"その際には、不燃化の促進の事業だけではなく、建築が行っている耐震化の事業であったり、感震ブレーカーの事業であったり、そういったものも連携しながら、一緒に周知を徹底していきたいと考えているところです。","voiceIndex":99,"id":"exchange-032"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"今の段階について、確認できました。日常的に接点のあるケアマネジャーとか、あと地域包括支援センターの職員が個別支援を行う中で制度案内を行うことができれば、さらに活用できる可能性が非常に高くなってくると思いますので、そういったところにもアプローチしていくということを一つ考えていただければと思います。要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-033"},{"speaker":"松永委員","kind":"質問・要望","question":"これはしっかりと伝えさせていただきたいと思います。その中で、要望が２つありまして、１つは、先日、ニュースでも報じられたとおり、大手最大メーカーが、中東情勢の悪化によって、原材料不足を理由に新規受注を当面停止するという事態に追い込まれました。２つ目の要望ですが、こうした行き先不透明な時代の中で、多くの高齢者世帯は不安を感じていると思います。区の考えをお知らせください。","respondent":"小川木密整備推進課長","answer":"こちらは東京都と連携して、金額について決定するものですので、引き続きしっかり東京都と連携を行いながら、物価高等へ対応していきたいと考えています。","voiceIndex":102,"id":"exchange-034"},{"speaker":"松永委員","kind":"質問","question":"それもとても大事になるのですけれども、私が言いたかったのは、今度、新規で、高齢者・障害者・要介護者に対して１５０万円の加算助成と書いてあるではないですか。高齢者他多世代同居への２００万円、これをもう少し増やせないかなですので、その辺について伺いたいと思います。","respondent":"小川木密整備推進課長","answer":"こちらの、今年度から新たに行わせていただきます加算助成の額につきましては、本年度の申請状況等を踏まえながら、見させていただいて、額の上乗せが必要かどうかは今後判断していきたいといったところです。","voiceIndex":104,"id":"exchange-035"},{"speaker":"せお副委員長","kind":"質問・要望","question":"全体的に重要な支援だと思っています。すみません、私が理解できていないのかなと思うのですけれども、この３の（１）の3)の未接道敷地の建て替えのための解消促進加算助成、これ、意味は分かるのです、重要だと思うのですけれども、どういう状況の方がこれを利用できるのかということが少し分からなくてということと、年間どれぐらいの件数を見込んでいるのか教えていただきたいです。","respondent":"小川木密整備推進課長","answer":"3)番の未接道敷地の建替えの状況です。この資料の図にありますが、道路に接道していない後ろの建物があります。こちらは道路に接続しておりませんので、建て替えができない建物になります。","voiceIndex":107,"id":"exchange-036"},{"speaker":"せお副委員長","kind":"質問","question":"ごめんなさい、どれぐらい件数を見込んでいるのか教えてください。","respondent":"小川木密整備推進課長","answer":"今年度に関しましては、８地区、今、不燃化特区をやっているのですけれども、そのうちの１地区は大井二丁目という１町丁目で１地区という指定になって、エリアが非常に狭くなっているので、７地区と捉えまして。","voiceIndex":109,"id":"exchange-037"},{"speaker":"せお副委員長","kind":"質問・要望","question":"なかなか、いや、あるのかなと思って、ごめんなさい、少し細かい話で申し訳ないのですけれども、意味としてはすごく重要だなと思っていまして、進めていっていただいて、先ほどの話にも、松永委員からもありましたけれども、進めていただいて、今後、課題とかが出てくれば、見直していただきたいなと考えていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-038"}]},{"id":"topic-04","title":"品川区耐震改修促進計画の改定","agenda":"品川区耐震改修促進計画の改定","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"大きく２つ伺いたいと思います。品川区耐震改修促進計画、これは初めてできたのは何年前だったでしょうか。福祉部門は、高齢者への接近に専門的なアプローチの仕方、専門性を持っておりますので、こうした力も借りていただいて、この品川シェルターを、言わば、今期、実績を広げていただきたいと、大きく２点伺いたいと思いますが、いかがでしょうか。","respondent":"森建築課長","answer":"ここは委員ご指摘の福祉部門とも連携いたしまして、様々進めてまいりたいと考えています。今年度は、区民の皆様に広く意見を賜れないかと考えておりまして、皆様にお伺いして、どういうふうな進め方がいいのかも含めて、品川シェルターの在り方について考えてあります。","voiceIndex":116,"id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"ですから、そういったマンションですとか、あるいは緊急輸送道路沿道建築物も、今回、２０００年基準でとはなっていないのですけれども、影響の大きさとか、居住する人の多さとかを考えると、こちらの建築物が新耐震基準のままでよいのかなということが少し気になったので、そちらについても伺いたいと思います。","respondent":"森建築課長","answer":"耐震目標の数値ですけれども、数値としては、なかなか達成が難しいかなと思うような数値ですけれども、しっかりその数字を目指して５年間やっていきたい、意欲的な目標ですが頑張っていきたいと考えています。","voiceIndex":118,"id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。今現在の知見でいうと、そういった基準で進めているということが分かりました。それと、周知については、避難訓練等という話もありましたけれども、様々徹底していただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-041"},{"speaker":"ゆきた委員","kind":"質問","question":"ここに書かれている広報紙、ケーブルテレビとか、各種ＳＮＳとか、あと、しながわ防災体験館で模型展示というのは、今までもやってきたことなので、これから、新たに示された５年計画、品川区耐震改修促進計画の中で、これからの５年間の計画のプロセスの中でどういったことが必要で、今後の展開に向けていくのかというところをお聞きしたいと思います。","respondent":"森建築課長","answer":"なかなか費用面等で耐震改修できない方々がいるということで、委員ご質問のとおり、品川シェルターをぜひお薦めしたいと考えています。","voiceIndex":121,"id":"exchange-042"},{"speaker":"ゆきた委員","kind":"質問","question":"昨年の決算特別委員会でも、私、質疑をさせていただきまして、耐震シェルターについて、状況により助成対象とするか検討していくと、ほかの耐震シェルター、品川シェルター以外の耐震シェルター。その前提に立てば、選択肢が限定されていることで普及が進んでいない現状については、国や都の方針の関係から見ても、改善の余地があるのではないかと考えますが、改めて最後にお聞きしたいと思います。","respondent":"森建築課長","answer":"その部分につきましては、委員ご指摘のとおりですので、様々意見を踏まえながら検討してまいりたいと考えています。","voiceIndex":123,"id":"exchange-043"}]},{"id":"topic-05","title":"区長会における「清掃事業の課題」に関する検討経緯等","agenda":"区長会における「清掃事業の課題」に関する検討経緯等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この関係はどういう関係になるのかということをお伺いします。これが都民が、区民が聞かれても少し分からないような資料になっているので、この資料でいうと、２番のところのごみ量推計というところの（４）辺りが、１ページ目に書いているような有料化を前提とした減量効果を含めて書いているという理解でよろしいのでしょうか、そこら辺を伺います。","respondent":"立木品川区清掃事務所長","answer":"ごみの全量焼却、こちらを今後も続けていくというところを諮るに当たって、今後、清掃工場の施設の建て替え、整備計画のほうも、順次建て替えていかなければならないということを前提とした中で、ごみを全量焼却できるような形で進めていくに当たりまして。","voiceIndex":129,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"続けて質問しますけれども、共産党としては、書いてあるような家庭ごみの有料化はやるべきではない、反対だという立場です。家庭ごみの有料化は減量効果があるのだと品川区としては考えているのか伺いたいのが１点と、それと、森澤区長は、ごみ有料化については、慎重に検討と発言していたと思うのですけれども、今日の資料を見ると、区長会としては、実現に向けた検討を進めると書いてあるのですよね。","respondent":"立木品川区清掃事務所長","answer":"区としてのスタンスですけれども、今回、区長会のほうで出されたものに関しましても、有料化については、２３区一体で検討が行われていくことと認識しておりまして、導入に当たりましては、やはり日々の生活でしたりとか、区民負担につながるものですので。","voiceIndex":131,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"生活している限りごみは出るわけだし、そもそも生産者拡大、生産者責任を問うことが筋なのではないですかとか、いろいろ言いたいことはあるわけですよ。ですから、２３区一体で進めていくべきことというのであれば、先ほど申し上げましたけれども、品川区が反対すれば進まないということではないですか。ですから、ぜひ反対の意見を述べてもらいたいと思うのですけれども、いかがでしょうか。","respondent":"立木品川区清掃事務所長","answer":"そうした中で、繰り返しになってしまうのですけれども、家庭ごみの有料化につきましては、２３区一体で検討が行われていくと認識しておりますので、やはりこれ、導入については慎重な検討を重ねていくことが必要であるというスタンスです。","voiceIndex":133,"id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のやり取りを踏まえて家庭ごみの有料化のことを伺いたいのですけれども、この資料のとおり、区長会での議論は、家庭ごみ有料化の減量効果を含む推計と比較することを行ったということです。家庭ごみの有料化の導入を検討したこととは違うということなのか、そこを教えていただきたいです。","respondent":"立木品川区清掃事務所長","answer":"先ほど申し上げました２３区一斉改修を想定した３つの施策、こちらは区長会のほうでも検討しているというようなところで、資源化可能な事業系古紙の工場搬入規制および廃棄物処理手数料の増額、こちらはロードマップを策定し、着実に進めることとして、繰り返しになりますが。","voiceIndex":135,"id":"exchange-047"},{"speaker":"ゆきた委員","kind":"質問","question":"一枚目の資料の５番に書かれている第６次一般廃棄物処理基本計画についての一番最後の資料１は、パブリックコメントについての資料かと思われますが、これ、どこにあるのか教えてほしいのと、あと、パブリックコメントが一部事務組合で実施されていますが、これは広報しながわとかで周知がされているものなのかどうかお聞きしたいと思います。","respondent":"立木品川区清掃事務所長","answer":"今のところは、パブリックコメントに関しまして、広報しながわ等での周知はしてございませんで、２３区清掃一部事務組合での周知という形になります。","voiceIndex":137,"id":"exchange-048"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。練馬区で、確認させてもらったのですけれども、第６次一般廃棄物処理基本計画のパブリックコメントについて周知していますというふうになっていることも確認させていただきました。今回の広報を、品川区も構成団体の一員として意思決定に関与していると踏まえると、区民への情報提供というのも重要かと思いますが、ここについてお聞きしたいと思います。","respondent":"立木品川区清掃事務所長","answer":"委員おっしゃるとおり、確かにこれは２３区に関係することですので、今回は、広報に掲載させていただいてないのですけれども、そういったところを十分気をつけて今後取り組んでまいりたいと思います。","voiceIndex":139,"id":"exchange-049"}]},{"id":"topic-06","title":"粗大ごみリユース事業の見直し","agenda":"粗大ごみリユース事業の見直し","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"粗大ごみとして回収されたもの、また、自分の車で持っていった粗大ごみの中で、まだまだ使えるものといいますか、ソファだったり、タンスだったり、ちょうど３月は引っ越しのシーズンですから、私のマンションの前にも様々粗大ごみがありましたけれども、まだまだ使えるものも当然あるわけです。見た目で何かリユース・リサイクルに回す仕組みとしては残っているのか、ここだけ確認させてください。","respondent":"立木品川区清掃事務所長","answer":"区民の方からに関しましては、粗大ごみとして持ち込む際にも処理手数料がかかってしまいますので、それをかけずに、まずは持ち込むかどうかというところの段階で、こちらのリユースのサイトをご利用いただくというようなことで周知をしてまいりたいと考えていることになります。","voiceIndex":145,"id":"exchange-050"},{"speaker":"安藤委員","kind":"確認","question":"今、ご答弁で、結局、今までは１,０００万円かかっていた事業経費が、効率化されて、書いてあるように７６万円余になるという理解でよろしいのかということが１つ確認と、それと、これは民間のサービスということなのですが、私はあまり詳しくないもので、当該民間サービスの信頼性というのですか、品川区がＷｅｂページも開設してご案内するということですのですが。","respondent":"立木品川区清掃事務所長","answer":"こちらは独自で調べたところですと、おいくらのほうでは、１１区が既に連携しておりまして、品川区で１２区目、ジモティーも１０区が連携しておりまして、こちらは品川区分で１０区という形になっております。","voiceIndex":147,"id":"exchange-051"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"今回の見直しについて、我が会派で、昨年の決算特別委員会において見直しを求めていた内容が、今回しっかりと反映されたものと受け止めております。新妻委員長が訴えてきたものです。これまで委託料約１,０００万円に対し、売上げが数十万円規模にとどまっていた費用対効果の課題についても改善が図られるものであり、区民の利便性向上に資するものとして大変に歓迎したい取組だと捉えています。","respondent":"立木品川区清掃事務所長","answer":"やはり事務処理の面での経費節減という部分になりますので、そちらは、すみません、例えば何人ですとか、そういったような形では試算してございませんで、相当数の工数削減にはなると見込んでいるところです。具体的な数字は出せなくて申し訳ございません。","voiceIndex":150,"id":"exchange-052"},{"speaker":"ゆきた委員","kind":"質問","question":"もう１点なのですけれども、今回の見直しで区民の利便性は向上する一方で、個人間取引が基本ということになると思いますが、トラブル防止に向けた周知と注意喚起も重要になると考えています。その辺の対応についてもお聞きできればと思います。","respondent":"立木品川区清掃事務所長","answer":"昨今、特殊詐欺等でいろいろ、先ほど信頼性という面でのご心配もご意見としていただきましたが、そういったところも、しっかりサイトと連携いたしまして、周知をしてまいりたいと考えております。","voiceIndex":152,"id":"exchange-053"}]},{"id":"topic-07","title":"しながわ水族館リニューアル事業計画","agenda":"しながわ水族館リニューアル事業計画","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"やはり引き続き重視すべき視点なのではないかなと思うのですけれども、今回のリニューアルに当たって、そこら辺は切り替えるということなのか、そこら辺をお伺いしたいというのが１点目です。子ども料金の無料の検討は、今回、水族館で行われたのでしょうか。対象にならなかった理由などがあれば伺いたいのと、最低限、リニューアルを機に無料にしていただきたいのですけれども、いかがでしょうか。","respondent":"大友公園課長","answer":"続きまして、子どものアイデアの募集をする方法についてです。こちらの募集、対象といたしましては、区内在住・在勤・在学で年齢不問、また、来館者によるアイデア募集をかける予定です。募集の内容といたしましては、部門を３つに分けて募集したいと考えているところです。","voiceIndex":158,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"続きまして、資料で、概要版について幾つかお伺いしたいのですけれども、２番の６）の近隣住民への配慮というところなのですけれども、これは具体的にどういうことなのか、後段の営業時間とも関わってくることなのでしょうか、伺いたいと思います。最後、第５章の「区内の企業が事業に参加しやすい募集要件」とあるのですが、これはどういうことなのか、どういう要綱なのか伺いたいと思います。","respondent":"大友公園課長","answer":"区内企業へ参画しやすい要件というところなのですけれども、こちらにつきましては、区内事業者を組み入れた事業者の体制であったり、区内事業者への発注額、また、区内事業者と連携した企画などを事業者選定の際の評価に加えたり、展示などに取り入れるデジタル技術など。","voiceIndex":160,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"様々分かりました。いいことばかりではないのではないかと思うのです。先ほど、子ども料金の話もしましたけれども、品川区で、やはり公定でやっていることによって自由度も上がるようなところもあるのではないかというところで、今回のＤＢ方式プラス維持管理と運営、一括発注ということをとることのデメリットについては、率直にどういうものが考えられるのかということを最後に伺いたいと思います。","respondent":"大友公園課長","answer":"しかしながら、今回のＤＢ方式、デザインビルド方式ですけれども、民間の創意工夫ということで、こちらは魅力的な水族館をつくるメリットとして考えられるところになります。","voiceIndex":162,"id":"exchange-056"}]},{"id":"topic-08","title":"下水道管老朽化対策事業（再構築事業）","agenda":"下水道管老朽化対策事業（再構築事業）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回は老朽化対策事業とのことなのですけれども、この工事は、耐震化につながるものなのかどうかということを伺いたいと思います。それと、下にある管きょ更生工法は、道路を掘って開削しない工法なのかを伺いたいと思います。こういう老朽化対策事業を、今回は２か所ということなのですが、今後どこでいつまでに行うなどの区内の実施計画は、今後の状況はどうなっているのか、分かれば教えてください。","respondent":"関根河川下水道課長","answer":"冒頭ご説明申し上げたとおり、現在、品川区において対象となっているのが目黒川の北側だけですが、今年の３月に東京都下水道局が公表いたしました新たな計画の中で、品川区の大部分を占める目黒川の南側、こちらについて、今後５年間の計画の中で。","voiceIndex":172,"id":"exchange-057"}]},{"id":"topic-09","title":"気象庁による新たな防災気象情報の運用開始に伴う区の対応","agenda":"気象庁による新たな防災気象情報の運用開始に伴う区の対応","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"なので、警戒水位の段階で防災無線はしないと、サイレンが鳴ったら避難というふうに、正直言うと、疑問を感じてしまうのですけれども、冒頭言ったように、比べて、区独自の対応である、国の言われたとおりということであれば、それをご説明いただきたいのと、そうは言っても、警戒をするということは、ＳＮＳや防災アプリはもちろんですけれども、やはりサイレンの音で少し緊張感が出ますので。","respondent":"羽鳥防災課長","answer":"それを裏返すと、区民の方は、サイレンが鳴ると、避難しようというふうに直感的に思われるのだなと認識いたしまして、今回の見直しをしたです。これは区の独自の判断で、特に国等のガイドラインに沿っての取組ではないというものです。","voiceIndex":178,"id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"このためにはあったのだなという。そう思うと、今回の区独自の判断は、様々な方の意見も聞きつつ、問合せがあったからやめてしまいますではなくて、やはり危機が迫っているということをどう直観的にも伝えるかという手法が、実際に災害が起きたときに、なるほどという理解につながってくると思うのですけれども、これで最後にしますけれども、区の考えを改めて伺いたいと思います。","respondent":"羽鳥防災課長","answer":"委員のおっしゃるとおり、サイレンを鳴らすことで、区民の危機感を、意識を高めるということは十分認識しております。これまでサイレンを鳴らすのは、水位の上昇のときのみだったのです。","voiceIndex":180,"id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"荷物をまとめるのか、家族と連絡を取り合うのか、足の不自由な方は事前にさらに準備するのか、その準備期間を促すお知らせを、ＳＮＳや防災アプリとともに、やはりサイレンで直接届ける、私は、そこでサイレンを使ってもいいと思っているのですけれども、そこはやはり準備をしてくださいと、準備で終わればそれでいいわけだけれども、準備の次に実際の行動につながるように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"今後の予定というところで、周知が少し弱いと思うのです。広報しながわで、雨期に入る前に、少なくともきちんと周知しなくてはいけないのではないかと思うのですけれども、そこについては書いていないような感じがするので、周知の強化については、さらなる工夫が必要だと思うのですけれども、いかがでしょうか。","respondent":"羽鳥防災課長","answer":"出水期が始まる前に、各町会長会議であったり、防災協議会の総会、そういった場を活用して丁寧に説明するとともに、５月２９日に気象庁も発表すると言っていますので、そういう情報を踏まえて、ホームページやＳＮＳ等でも周知はしてまいりたいと思います。","voiceIndex":183,"id":"exchange-061"},{"speaker":"ゆきた委員","kind":"質問","question":"すみません、今の広報の仕方についてなのですけれども、重ねてなのですけれども、広報しながわで６月１日にハザードマップの更新について、予算特別委員会のときに質疑させていただいたときの答弁で、特集を行うというご答弁があったと思いますので、その辺、これ、どういうふうに広報していくのか、同じところで広報されるのか、２回特集を続けて広報されるのか、その辺について。","respondent":"羽鳥防災課長","answer":"９月１１日の被害の状況をマップ上に落としたものがありますので、そういったものも併せて今年度の風水害に備えていただくように、しっかり周知してまいりたいと考えております。","voiceIndex":185,"id":"exchange-062"}]},{"id":"topic-10","title":"品川区小災害見舞金等支給要綱の改正","agenda":"品川区小災害見舞金等支給要綱の改正","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"区の見解をいただきたいと思います。当面、お金を使うこともあるでしょうから、どうぞという気持ちはとても大事だと思います。特に、全壊と半壊では６万円と５万円ですから、再建には全く足りないわけです。規模が大きくなったら、別の仕組みがまた返ってくることにはなるわけですけれども、やはり見舞金と、別建てで支援金の導入、この１点だけ、質問したいのですけれども、いかがでしょうか。","respondent":"星災害対策担当課長","answer":"生活再建につきましては、現在もある程度ある支援の体制等を、今回、９月１１日の際は、事業所や被害に遭われた方にお伝えしているところです。こちらにつきましても、関係各課と連携をして、これからどういった支援が必要かという検討は続けてまいりたいと考えているところです。","voiceIndex":191,"id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"おっしゃるとおり、やはりお見舞いはお見舞いなのですよね。被災された方にお見舞いをするという意味では、この制度は必要だと思いますし、実態に即して充実をすることは、充実改善することは必要です。今、課長がおっしゃったとおり、生活再建策でいうと、９月１１日は、いわゆるエコな冷蔵庫への買換えの助成金で、災害を想定した事業ではなかったけれども、これが使えると。最後にいかがでしょうか。","respondent":"星災害対策担当課長","answer":"先ほどと同じような話になりますけれども、住民の再建支援は、関係各課と連携をして、いろいろな支援策について進めていきたいと考えております。","voiceIndex":193,"id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"見舞金については、今回、改善が一定されたということなのですけれども、２点だけお伺いしたいです。１つは、昨年、戸越銀座をはじめとして、かなり多くの事業所が被害を受けたところなので、かなり事業所で高価な設備とかもやられてしまったわけです。","respondent":"星災害対策担当課長","answer":"今、手元に資料がないので詳しくご説明できなくて申し訳ないのですけれども、例えば、半地下であれば、居住実態があれば、そのまま床上として判断していこうというようなところの基準を用意しているところです。","voiceIndex":195,"id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりかなり商店街には事業所が多いという地域特性もあるのです。生活基盤そのものなのですよね。生活基盤をつくるための事業、職住一体になっているような商店街も多いところなので、ぜひ改善を進めていただきたいなと思いますし、少なくとも住宅と同じ規模には引き上げていく必要があるのかなと思っています。なので、そういったところにも行き届くような制度にぜひ改善していただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-066"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"宿泊見舞金の２泊から３泊への変更については、公明党としても求めてきた内容であり、大変歓迎した要綱の改正であり、また、見舞金の支給額の変更についても、被災者の支援の観点から歓迎したい取組だと捉えています。引き上げてほしいとか、そういった声もあるので、ニーズを把握した上で、そういった声を反映する形で検討していただければと思いますが、ここについてお聞きしたいと思います。","respondent":"星災害対策担当課長","answer":"事業所への見舞金の支給につきましては、委員からのご指摘のとおり、ニーズを把握していきたいと考えています。","voiceIndex":198,"id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7361#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":81208,"voices":202}},{"id":"r08-20260414-9","meetingId":"r08-m0405","date":"2026年4月14日","dateIso":"2026-04-14","committee":"文教委員会","time":"午後 １時００分～午後 ３時４９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和８年度品川区立幼稚園、小・中学校、義務教育学校、園長・校長・副園長・副校長異動者名簿","agenda":"令和８年度品川区立幼稚園、小・中学校、義務教育学校、園長・校長・副園長・副校長異動者名簿","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"そもそもの考え方というのでしょうか、仕組みを伺いたいと思います。これは東京都から配属されてくるのか、区としてこうしたいと要望してやるのか伺います。","respondent":"酒川指導課長","answer":"東京都の人事構想、それから、区の要望、双方があります。","voiceIndex":15,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"それはそうだろうとは思うのですけれども、実際に、そうすると、東京都から何人品川区に入って品川区から出ていくと区に来て、区がその人たちをどこに配置するか、校長とか、副校長とか、園長とかを割り振っていくことなのか伺いたいと思います。なかなか校長、副校長が一遍に替わることもあるみたいなので、その辺の区の考えはどのように反映されているのか伺います。","respondent":"酒川指導課長","answer":"東京都から人材情報の提供がありまして、そういった提供を受けた上で、地域や学校の状況を踏まえて、区で配置校を決定しております。","voiceIndex":17,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"校長、副校長が一緒に替わってしまう。そうすると、結構、運営的に大変なところがあると思うのですけれども、区としてそういう判断をされているのですか。","respondent":"酒川指導課長","answer":"区でも、管理職２人を一遍に替えるのは、実際は行いたくないところではありますけれども、こちらで予期していなかった退職管理職がいて、様々な流動的な状況で、最適化という意味で、苦渋の判断をした部分もある状況です。","voiceIndex":19,"id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問","question":"誰かをどこかに入れればいいというものでもないと思っています。指導課長が今また少しおっしゃったのですが、一般論として、校長と副校長が同時に替わったときに、学校運営上、どんな問題が発生し得ると認識していらっしゃるのでしょうか。","respondent":"酒川指導課長","answer":"地域や保護者の状況がどういった状況なのかも把握しづらいという状況はあると認識しておりますけれども、その点については、前校長、これからの校長、それから、前副校長、これからの副校長へ引継ぎを行っていただき、今の時期、真っ最中かと思いますけれども。","voiceIndex":22,"id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問","question":"今お話にあったように、とにかく４月は学校の先生方も異動して大変な状況の中で、校長先生、副校長先生が替わるということですから、立ち上がりが非常に不安定になる。それから、管理職同士の役割分担、意思疎通である程度動いていたのが、また時間がかかるので、現場にしわ寄せがかかる。ですから、区教委として努力されたのだと思うのですけれども、そこを改めて、２年続けてというところをお尋ねします。","respondent":"酒川指導課長","answer":"一部繰り返しになりますけれども、やはり校長と副校長が２人とも同じ年度に替わるのは、学校、また、様々なところに負担、しわ寄せが行くことは承知しておりまして、これも繰り返しになりますが、なるべく避けたいと考えておりますけれども、昨年度と少し違う状況で、今年度。","voiceIndex":24,"id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、そこの今同時に替わったところは、個別の学校名は置いておいて、本当は残っていただける予定だった方が退職して同時になってしまったという認識でよろしいでしょうか。","respondent":"酒川指導課長","answer":"なかなか学校名まで挙げて申し上げるのは難しいのですが、そういった状況で、２人替えになった学校はあります。","voiceIndex":26,"id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問","question":"いろいろ学校名はあれですので、そうすると、逆に言うと、先ほどのご答弁にあった人材の提供が東京都からある。それを区で配置していくというお答えだったのですけれども、品川区教育委員会としては、東京都教育委員会に対して、同時の異動はこちらとしては困る、そのような状況は、常時、いつも明確にお伝えしていらっしゃるのでしょうか。","respondent":"酒川指導課長","answer":"同時の異動は、今回、東京都の都合ではなく、先ほど申し上げましたが、本人の退職希望などによりますので、そういったいなくなった校長先生のところを埋めるべく、優秀な人材の要望はしております。","voiceIndex":28,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問","question":"今年はそういう事情があったということで、ここでまた一般論になりますけれども、通常、品川区教育委員会としては、同時に替わることは、区としては、いろいろ大変な影響があるから避けたいと、都教委には通常伝えているのでしょうか。","respondent":"酒川指導課長","answer":"区として、当然、管理職２人を同時に替えるのは避けたいわけですけども、同時に替えるか替えないかというのは区の判断になりますので、東京都への要望というものではございません。","voiceIndex":30,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"区が替えることには、非常に混乱やいろいろな影響があるので、避けたいという意思があるということは、区教委としては替えない体制でやっているということも１つ確認で、このようにして替わってしまうことは、やはり当然ながら、現場の混乱等、負担が生じますし、しわ寄せは子どもたちに行くので、先ほどもご答弁いただきましたけれども、同時に替わったところに対しては丁寧に教育委員会として支援。","respondent":"酒川指導課長","answer":"第１回目のヒアリングが４月の下旬から始まりますので、こういったところで状況を確認するとともに、今年度、管理職、主に校長ですけれども、替わった学校については、私自身が訪問して状況を伺う、把握していくことも考えております。","voiceIndex":32,"id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"やはりなかなか学校も、まず１つは、先生方がそうなって大変だと声は上げにくいところがありますので、それを拾っていただくのと、あと、地域で、両方とも替わってしまったというところで、地域とのつながりが、継続性が止まるので、その辺りも含めて、今お話のあったような支援をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-010"},{"speaker":"若林委員","kind":"質問","question":"今の続きで、管理職が替わったところについて、教育委員会のバックアップがされているということで、逆に、校内の体制として、校長先生、副校長先生を支える、今回、主幹教諭でしたか、主任教諭とか、新しいネーミングもあって、そちらの校内からの新しい体制を支える気遣いとか工夫は何かあるのか。あれば、教えてください。","respondent":"酒川指導課長","answer":"校内においては、ナンバー３に当たる主幹教諭が副校長、校長の経営を補佐する立場にありますので、主幹の立場にある教員については、こちらから毎年度言うまでもなく、そういった立場であることを理解して取り組んでいただいてあります。","voiceIndex":36,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問","question":"今、主幹という言葉が一致しましたので、そこも含めて、この表でいう黄色のところで、そういう支える、ナンバー３ですね。主幹の方も替わっているところは、学校名でお話しするのか、ナンバーでお話しするのか、何か所という表現なのか、そういう事例があれば教えてください。","respondent":"酒川指導課長","answer":"校長、副校長の異動と、やはり主幹の異動というのもバランスを取らなければいけないところで、校長が異動した学校、副校長が異動した学校、そして主幹が異動した学校、それぞれに数字をお示しするのはできないわけですけれども、そういった学校を含めて。","voiceIndex":38,"id":"exchange-012"}]},{"id":"topic-02","title":"令和８年度（９年度採用）品川区立学校教育職員採用候補者選考日程","agenda":"令和８年度（９年度採用）品川区立学校教育職員採用候補者選考日程","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、若干名の採用ということで、目標は何人なのかを伺います。","respondent":"酒川指導課長","answer":"長期の目標としましては、全校配置を目標としております。","voiceIndex":44,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"全校配置、今、３０人ぐらいいらしたと思うのですが、それを増やしていくということで、私たちも、区独自の教員として採用しているわけですから、少人数学級の実現とか、対応してやっていただくように求めてもおりますので、そうした前進ができるように、やっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問","question":"（３）の３年生前倒し通過者選考で、報告があったのかもしれませんけれども、すみません、私がそこの記憶が、申し訳ないのですけれども、令和７年度に実施したので何名の方が今、残っている、言い方が正しいのか分かりませんけれども、合格、通過したのでしょうか。","respondent":"酒川指導課長","answer":"前倒し選考、令和７年度については、２名が受験しまして、１名が通過しております。","voiceIndex":48,"id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"その方々は、受験するかどうかはこれからになるわけですね。ということは、逆に言うと、区としては、ぜひ受けてくださいと働きかけができるものなのですか。できないものなのでしょうか。受けていただきたいという意味においてです。","respondent":"酒川指導課長","answer":"昨年度受験して、一次の一部を通過しておりますので、本年度は一次の後半部分の試験から受けていただくことになるのですが、こちら、通知を行いますので、その通知を行うところで、ぜひ受験していただきたいということはお伝えできると考えています。","voiceIndex":50,"id":"exchange-016"}]},{"id":"topic-03","title":"部活動の地域展開","agenda":"部活動の地域展開","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"確認ですが、今ご説明いただいた協議会の回数をなぜ減らしたのか伺いたい。しながわ地域ＴＥＡＭ ＡＣＴの中で、令和５年度はバトミントンをやられていましたが、それがなくなった理由を伺います。","respondent":"酒川指導課長","answer":"バドミントンですが、令和５年度はどのような地域展開ができるかということで、幾つか取り上げた中にバドミントンを入れたわけですけれども、ダンス、ラグビー、ホッケー等々、地域展開の見通しが立ったことから、学校部活動にバドミントンはかなりたくさんあるということで。","voiceIndex":56,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"つまり、協議会はロードマップの作成が１つの大きな仕事だということですね。一定役割を終え、続けていくということですけれども、そうすると、今後連携をしていく、いろいろな問題とかを共有していく場になっていくのか。位置づけ的に何か変わるものがあるのか伺います。","respondent":"酒川指導課長","answer":"このビジョンに基づいてしばらくはやっていくと合意を得たです。当然ながら、地域展開ですから、地域移行は今後も考えていくものですので、国の動きや都の動きも把握しながら、この場は、今年度１回としておりますが、協議の場としては維持する考えです。","voiceIndex":58,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"実際に地域移行を進めていくと、料金が発生してくるのかどうかも含めて伺いたいと思います。やはり今までの部活動の部分を残す、教員が指導するのも残すということですけれども、教育の中でやってきた。教育的な視点をどう今後担保していくのかも１つ重要と思うのですが、そこの考えを伺います。","respondent":"酒川指導課長","answer":"当然ながら、これを全て、部活動という名前が適当かどうか分かりませんが、子どもの活動の場所を地域に移していくとなると、費用はかかってくるので、その辺りは行っていくとなったときには課題になると認識しております。","voiceIndex":60,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり部活動としてやっている中では、子どもたち、参加したいと思えば参加できる状況ですけれども、民間に移していくと、そういった課題が出てくるので、ぜひ生徒たちが選択してできるようにしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"酒川指導課長","answer":"地域に完全に移行していったときには、教育的視点、費用、様々な課題があると思いますので、それをどう捉えるかもありますけれども、そういった課題整理は進めていきたいと考えています。","voiceIndex":62,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"課題はあるということで、今まで何で学校でやってきたのかは、教育として必要な部分があったということだと思いますので、そうした教育的視点は残していただきたいと思いますし、いろいろこの間も協議会等で評価されてきたということだと思うのですが、実際、受け持ちたいという教員の方もいらっしゃると思いますし、あと、教員の負担も軽減していかなくてはいけない中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-021"},{"speaker":"まつざわ委員","kind":"質問","question":"校区協働委員会の人が、部活動を地域移行する場合、生徒理解などの技術的指導の部分が必要となるという一意見が出ていますけれども、やはり民間委託していくのはこれから絶対必要なことだと思っているのですが、でも、高い指導というメリットがある以外に、こういった指摘が出てくると思っていて、例えば、そういった外部指導員と教員、これが日頃の情報共有。","respondent":"酒川指導課長","answer":"おっしゃるとおり、生徒指導上の問題ですとか、その日の生徒の課題を抱えたまま部活動に参加することがありますので、１００％教員が指導や関わりを絶つわけではなく、当然、そういった状況の場合は、観察といった形で指導に関わるという状況はあります。","voiceIndex":66,"id":"exchange-022"},{"speaker":"まつざわ委員","kind":"質問","question":"１点、地域部活動のラグビー、私もラグビーをやっていたので、興味があって、ＪＲ東日本東京総合車両センター、これをこうやって一緒にやっていくのは本当にすごい、とてもいい機会と思っていたのですけれども、お話を聞いていると、ここもだんだん使えなくなっていくとお話の中であった。そういった部活動で必要な活動場所、そういった誘致の課題はどうなのか、少し心配があるので教えてください。","respondent":"酒川指導課長","answer":"昨年度から引き続き、一部の活動は区立学校の校庭を使って実施予定ですが、残りをどこの場所を使ってやるかは現在検討中です。いずれにしましても、利便性と安全性の確保を、ラグビー協会とも情報共有しながら、最適な場所を見つけていきたいと考えています。","voiceIndex":68,"id":"exchange-023"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"地域資源を活用するのは本当にすごくすばらしいことなので、でも、見ても、品川区はほかにあるかといったら、難しいと思いますけれども、ぜひこういった取組は引き続き検討していただきたいと思います。四、五人ではなかなか楽曲にならない。そこら辺も１個、地域移行、これからの今後のテーマとして、ぜひ検討していただきたいということ。私はそう考えているのです。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-024"}]},{"id":"topic-04","title":"これからの市民科について（第２次案）","agenda":"これからの市民科について（第２次案）","exchanges":[{"speaker":"まつざわ委員","kind":"質問・要望","question":"教員の意見の中で、地域の人材は眠っているという一方で、授業、行事が多いため、地域と連携する人探しをする時間がない、そういった現場の声がここに書かれています。だから、そういった地域の大人たちと中学生が触れ合う機会、これをぜひ教育委員会で組織的に構築していただきたいと思いますけれども、いかがでしょうか。","respondent":"高木教育施策推進担当課長","answer":"今言っていただいた地域人材の活用、非常に重要な内容であると認識しております。区としましても、一貫プラン・探究的な学習の充実に向けて、各学校の取組について今収集しております。","voiceIndex":75,"id":"exchange-025"},{"speaker":"まつざわ委員","kind":"質問","question":"まとめているという。国も特別の教科道徳、これをやっていきましょうというのと、品川区独自の市民科、これ、本当にすごい、すばらしいと思っているのですけれども、今言った道徳と市民科、やっているのでしょうが、市民科の中に道徳が入っているのでしょうけれども、これをどうこうやって抜き出して、道徳を充実させてほしいという教員の声を反映させて、考えていくのか。","respondent":"高木教育施策推進担当課長","answer":"市民科を遡りますと、そういった理念の下に特別活動と合体させたところがありますので、市民科の全単元において、どこにおいても道徳的要素は入っていると指導しておりますし、その認識で教員も指導しておると考えております。","voiceIndex":77,"id":"exchange-026"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"全て道徳が入る。ですから、ＰＴＡと連携するとか、私がＰＴＡ会長時代は、道徳教育ではないですけれども、学校が親や保護者に言えない部分はＰＴＡでやっていこうという心構えで３年間務めさせていただいたので、そういったＰＴＡとの連携もぜひ進めていただきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-027"}]},{"id":"topic-05","title":"品川区いじめ防止対策推進基本方針の改訂","agenda":"品川区いじめ防止対策推進基本方針の改訂","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"１つは、スクールロイヤーは名称を変えるだけですか。子どもたちは悪いことだとは分かっているはずです。やはり教育の営みの中で解決していくことが基本だと思いますので、そこだけ押しつけても、どういう背景があっていじめをしているのか、いじめをしてはいけない理由とか、そういったところをしっかりと学んでいくのが１つ重要だと思いますけれども、いかがでしょうか。","respondent":"保土澤教育総合支援センター長","answer":"専門的な知見からご助言もいただきながら、様々な課題の早期対応、早期解決を図ってまいりたいと考えています。もう１点、いじめの禁止についてですけれども、やはり行為を禁止すればなくなるということではないとのご指摘かと考えています。私も同様に考えております。","voiceIndex":84,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした姿勢を基本方針にも入れていただきたいと思います。言葉が適切か分かりませんが、加害者がいじめをしなくなるまで、人間的に立ち直っていくまで徹底したケアを行っていくことが、やはり再びいじめを繰り返さないことにもなっていき、いじめを減らしていくことになると思いますので、いじめをした側への徹底したケアをしていくというのをぜひ位置づけていただきたいと思うのですが、いかがでしょうか。","respondent":"保土澤教育総合支援センター長","answer":"だからこそ、ご指摘のとおり、学校での風土づくり、それから人間関係づくり、こういったものを各学校で引き続き進めていく必要があり、そして、仕組みのご指摘もありましたが、いじめを予防するため、早期対応するためにどうするかだけではなくて、いじめがやはり認知された後。","voiceIndex":86,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"それぞれ取り組んでいただけるという答弁だったと思います。実際にスピード感を持って対応していく、今回の変更だということで、スピード感を持って解決をしていく決意などがあれば、伺います。","respondent":"保土澤教育総合支援センター長","answer":"本当にスピード感というところは各学校に引き続き指導しながら、教育委員会といたしましても、そこを重視した対応を進めていきたいと考えています。","voiceIndex":88,"id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"意見","question":"今、スクールカウンセラーの全校配置とお話があったのですけれども、現状もというのは、令和７年度までもスクールカウンセラーは区立学校に配置されていたわけですが、それとどのように変わるのか、別の発表だと追加配置という表現になっているのですけれども、その辺、令和７年度とどのように変わるのか、お願いします。","respondent":"保土澤教育総合支援センター長","answer":"今年度からは、全ての小・中学校に区のスクールカウンセラーを追加で配置をしていくです。人数につきましては、４３名追加という形で配置を進めてまいります。これまでも都から配置されるスクールカウンセラーにつきましては、全校に配置されていたものです。","voiceIndex":91,"id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"８校だったのが全ての小・中学校ということですけれども、予算特別委員会でも質問したのですが、スクールカウンセラーの教育委員会としての要望が２億円ぐらいあって、それで、予算査定で１億１,４００万円ぐらいになって、スクールカウンセラー派遣時間数とあるのですけれども、これは先ほどのだと１週間に最大４日勤務と書いてあるのです。","respondent":"保土澤教育総合支援センター長","answer":"そういった実態から、１日でもそういった専門職と連携して、子どもの理解や様々な対応、こういったものに学校が対応できることが望ましいと考えておりました。","voiceIndex":93,"id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、スクールカウンセラーが令和７年度に入っている学校だと、相談というよりも、特に支援が必要なお子さんとかについて、何曜日の何時間目はここ、何時間目はここという感じでやっている学校もあると聞いているのですけれども、そういう体制とはもう少し違って、いじめなどに関係して、現状、相談は都費でやって、区費の現状のスクールカウンセラーの方、また違った形で支援している認識なのですけれども。","respondent":"保土澤教育総合支援センター長","answer":"それに加えて、学校での相談、保護者や子どもたちのカウンセリングのニーズがあれば、そこも担っていくようにという優先順位で、区費のスクールカウンセラーについては業務を伝えてあります。もう１点、時間は短いことはなく、全て同じ時間帯での勤務と認識しております。","voiceIndex":95,"id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問","question":"私の認識が誤っていたのかもしれませんけれども、巡回して、クラスなどの支援をする子たちを見ていくという表現ですね。令和７年度の幾つかの学校では、支援ですか、そのようなところが主だった、いろいろな人としての素地、そういう部分もあったという意味なのですけれども、そういうのもやりながら、今みたいな、課長が説明していただいたようなこともやる感じでよろしいですか。","respondent":"保土澤教育総合支援センター長","answer":"今お話しいただいたイメージのとおりです。","voiceIndex":97,"id":"exchange-034"},{"speaker":"まつざわ委員","kind":"質問","question":"スクールロイヤーを明記された。大変すばらしいことだと思います。１点、このスクールロイヤーは、例えば管理職が何かあったときに、相談体制ですよね。例えば、こういった課題があったときに、教員の方がすぐにこうやって直接つなげる、何かそういう仕組みを考えているのか、そこを教えてください。","respondent":"保土澤教育総合支援センター長","answer":"スクールロイヤーにつきましては、やはり学校管理職の判断をもって、そして、スクールロイヤーと連携して課題解決を図るという学校での判断の下に連携をしていくものです。","voiceIndex":100,"id":"exchange-035"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"１点、いじめの早期発見について、要は見えないＳＯＳというのですか。その子と話をしているときに、これを表面化することによって、被害者、加害者と明確に言えるのは、子ども的にも親的にもそうですかというお話を受けた案件があったときに、やはりそういった見えないＳＯＳを探していく、これを強化するのは本当にすばらしいことだと思っています。一方で、これ、すごく難しいです。","respondent":"保土澤教育総合支援センター長","answer":"実際には、先ほども少し触れましたが、各学校に追加で配置した区のスクールカウンセラーが、区で今取り組んでいる調査ツール、日々取り組むものと、月１回取り組むものなど様々ありますけれども、そういったものを学校と一緒に確認して、実際の加害、被害の訴え以外にも。","voiceIndex":102,"id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほどあれだったので、申し訳ありません。スクールカウンセラー、今、全校ですけれども、そういったスクールカウンセラーを見つけていくのが大変だと言われているのですが、複数を１人が兼ねるとしても、配置に関しては現状で整備されているのでしょうか。","respondent":"保土澤教育総合支援センター長","answer":"何とか配備をできたところです。","voiceIndex":105,"id":"exchange-037"}]},{"id":"topic-06","title":"区立学校におけるいじめの重大事態の発生状況および調査結果","agenda":"区立学校におけるいじめの重大事態の発生状況および調査結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、この間、報告書が今回２つ出たということですけれども、公表希望なしになってしまって、この事案を今後に活かしていくことがなかなかできていないということを指摘させていただいているのですけれども、その中で学校では共有できるようにしていきたいとお話があったのですが、それが今どこまで進んでいるのか伺います。","respondent":"保土澤教育総合支援センター長","answer":"令和７年度に１３件という件数ですけれども、確かに令和６年度と比較すると、件数としては増えております。増えているのですが、これはあくまで重大事態として認知したのが令和７年度ということで、対応が令和６年度から続いているものも中にはあります。","voiceIndex":111,"id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ今後の取組にも活かしていただきたいと思いますし、当然、保護者、本人の希望も尊重しつつですが、できるところで議会にも公表できるように、検討を進めていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-039"},{"speaker":"まつざわ委員","kind":"質問","question":"そうすると、私などが考えると、叩いた、暴力行為は事件だと思います。そうすると、警察の案件と思っていて、例えば、こういった暴力事件があったときの対応の中で、こうやって警察と連携して区としてやっていっているのか。例えば、どこまで警察が入ってくる基準があるのか。それを教えてください。","respondent":"保土澤教育総合支援センター長","answer":"その指導で改善が見られず繰り返していくような場合には、保護者との面談も含めて指導を行って、そして、必要に応じて警察と連携することも考えられます。警察と連携する場合には、被害届等も出るかどうか。そういったところも１つポイントになると認識しております。","voiceIndex":118,"id":"exchange-040"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"例えば、被害者が転校したら、それで解決かというと、それは全然解決になっていないと思うのです。こういった事案は、しっかりと警察の指導を入れるところは入れるという部分も含めて、厳しくぜひやっていただきたい。家庭の環境とか、流れなどは私は分からない。いろいろあると思いますけれども、そこら辺を厳しく、言い方はきついですけれども、ぜひしっかりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問","question":"それを表現しないで発表するのは、区の条例とか国の法律にないと思うので、いわゆる小学校、中学校、義務教育学校の前期か後期かを分けるように公表するほうがよいと思いますので、もし何か条例なりを変えなければいけないのだったら、そこで変えるべきだと思うのですが、その点はいかがでしょうか。","respondent":"保土澤教育総合支援センター長","answer":"今ご指摘いただいた点については、どのような条例と関わるのか私も確認したいと思いますけれども、実際どのような公表、学校種以外の公表が適切なのかどうか含めて、私も勉強して、いろいろなところからも意見をいただきながら考えていきたいと思います。","voiceIndex":122,"id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"学校種で公表しなければいけないというルールがあるならばしようがないのですけれども、そうでなく、義務教育学校として公表して、これも決まっていないと思うので、そこをすることが可能であれば、ほかは小学校、中学校とあるし、現実が分からないですよね、義務教育学校のどちらで起きたか。これは要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-043"},{"speaker":"筒井副委員長","kind":"質問","question":"先ほども一部関わって、出た質問だと思うのですけれども、重大事態の分類、１号に当たるのか２号に当たるのか、その分け方なのですが、私も、いじめの態様4)番、ひどくぶつかられたり、叩かれたり、蹴られたりするとあったら、これ、１号に当たると思ったのですけれども、挙げられている事案だと、事案番号１３でも２号になったり、事案番号４でも２号になったりするのですけれども、その点の分け方、１。","respondent":"保土澤教育総合支援センター長","answer":"本件について、結果、様々な望ましくない関わりがあって、そして、不登校という状態になって、一定期間、学校にも通えなくなってしまったというところが、本件で最も保護者や本人にとっても苦しいといいますか、改善すべきところという判断で２号となったと認識をしております。","voiceIndex":126,"id":"exchange-044"},{"speaker":"筒井副委員長","kind":"質問","question":"今ご答弁を伺うと、やはり結局、プロセスはともかく、不登校になったことは結構大きなポイントで、そうすると、例えば、１号の要件を満たしていても、不登校ということで２号に吸収されてしまうのか、その辺りどうなのですか。逆に、重大事態１号と２号、同時に当たるという、同時適用はあるのですか。","respondent":"保土澤教育総合支援センター長","answer":"ご指摘のとおり、１号と２号同時に当たる事案もあります。その辺りも組織的に個別に判断をしております。","voiceIndex":128,"id":"exchange-045"},{"speaker":"筒井副委員長","kind":"質問","question":"結局は今回、調査結果も出ているのですけれども、事案番号４と１、それで、結局、その調査結果が出たのはいいのですけれども、いじめの被害者の方は、要は、問題は解決したのですか。例えば、不登校が解消されたとか、生命、心身、財産の重大被害が収まったとか、解消されたとか、被害者の抱えている被害状況はもう解消されたのですか。おおむね過去の傾向からでも結構です。","respondent":"保土澤教育総合支援センター長","answer":"様々なケースがありますので、個別にはお答えできないです。","voiceIndex":130,"id":"exchange-046"}]},{"id":"topic-07","title":"令和７年度、就学・転学相談の結果","agenda":"令和７年度、就学・転学相談の結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"転学・通級相談が増えているということで、先ほど特別支援教室の利用が増えているというお話だったと思いますが、結果の受け止め、支援が必要な子が増えているということなのかどうかも含めて伺います。特に小学校で、プラス３２名ですか、特に増えていると思うのですけれども、そこの関係も伺います。","respondent":"新井特別支援教育担当課長","answer":"こちらにつきましては、やはり一般論として、いわゆる発達障害等と言われるお子さんが増えているのもあると認識していますけれども、利用につながるためには、校内委員会という、学校内での支援の検討が必要になってきます。","voiceIndex":140,"id":"exchange-047"},{"speaker":"のだて委員","kind":"質問","question":"全体として増えているところでは、校内委員会がうまく機能しているということでしたけれども、今回、なぜうまくいったのか分かれば、理由を伺いたいと思います。","respondent":"新井特別支援教育担当課長","answer":"そういった意味で、これまでの研修の継続による効果と、あとは、そういった地道な巡回相談員による側面支援が実を結んできていて、校内委員会がきちんと開かれて、より内容があるものになってきていることが１つ要因として捉えてあります。","voiceIndex":142,"id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"今のご説明ですと、やはりしっかり手が届いて、必要な人に支援が行き出しているということだと思いましたので、ぜひそれは進めていただいて、子どもたちがしっかりと適切な教育を受けられるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-049"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで保護者の方々への、実際は保育士たちに対するアドバイスですけれども、そういう巡回相談や、さらに、全くこれは違う所管ですが、５歳児健診をすることによって、保護者の方々のそういう認識が広がった、就学相談を受けることにつながったかどうかは、なかなか答弁しにくいと思うのですけれども、就学相談につながって、しっかりとした支援を受けるか受けないか。","respondent":"新井特別支援教育担当課長","answer":"実際にはまだないのですが、就学相談を受けるべきかどうか悩む保護者がいらっしゃった場合には、私どもにぜひ連絡くださいということもチラシでは書かせていただいておりますので、そういった意味で、保護者の方が、例えば５歳児健診の結果をどう受け止めるかということもあって。","voiceIndex":146,"id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"意見","question":"所管がいろいろありますけれども、１人の５歳のお子さんをいろいろ支援する仕組みが区の中では整いつつありますので、しっかりと小学校へのつなぎ、うまく、特別支援をするしないに関わらず、その子たちがしっかりと小学校生活を送れるように、ぜひ連携して支援をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-051"},{"speaker":"まつざわ委員","kind":"質問","question":"特別支援教室の情緒が増えているという数字の中で、利用が多くなったときに、例えば、学校で専用のスキルのある巡回の方たちの配置が十分なのかというのと、教室がどうなっていくのか、教室の配置も心配なので、そこも教えてください。特別支援学級が増えていますね。","respondent":"新井特別支援教育担当課長","answer":"２点目の自閉症・情緒障害の特別支援学級の、いわゆる固定の学級の今後の考え方ですけれども、予算のご議決をいただきまして、令和９年４月に、中学校では３校目となる冨士見台中学校に自閉症・情緒障害の特別支援学級を開設する予定です。","voiceIndex":149,"id":"exchange-052"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"制度の要因があることは分かりました。でも、やはりこういったものは、大変になってからやる後手後手の施策だと駄目だと思っていますので、先手の施策というのも変な話ですけれども、こうなるであろうというある程度の方向性の中でやっていただいていると思いますけれども、引き続き、こうなるだろうという見込みの中での考え方もぜひ取り入れていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-053"}]},{"id":"topic-08","title":"自閉症・情緒障害特別支援学級の開設","agenda":"自閉症・情緒障害特別支援学級の開設","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、冨士見台中学校に新たに自閉症・情緒障害特別支援学級を開設するということで、そうすると、現状では、これは必要な子どもたちは入れる、足りているのか。今、増加が見込まれるということで冨士見台中学校が増えるわけですけれども、さらに今後どうなっていくのか、この見通しを伺います。","respondent":"新井特別支援教育担当課長","answer":"今後については、何とも難しいところですけれども、やはりいわゆる自閉症・情緒障害の特別な支援を必要とする児童・生徒の推移をきちんと見極めた上で、開設というのを先々を見据えて検討していきたいと考えています。","voiceIndex":156,"id":"exchange-054"}]},{"id":"topic-09","title":"「品川区社会的養育推進計画」の策定","agenda":"「品川区社会的養育推進計画」の策定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"パブリックコメント５番の意見で、障害相談が１割あるけれども、障害児に関する取組の記載が１か所しか見当たらないと書いてあるのですが、それに対して区は、別の障害児福祉計画で記載していると答えているのですけれども、実際、障害児が社会的養護を必要としたときにはどういった対応になるのかを伺いたいです。","respondent":"柴田子ども施策連携担当課長","answer":"もちろん通報を受けてというのもあるのですけれども、通報を受けないで行っているケースとしましては、所管は保健部門になるのですが、新生児の赤ちゃん訪問を実施しておりまして、それは保健センターと。","voiceIndex":163,"id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々やられているということで、ぜひ取りこぼしがないように、あと、職員配置についても意見を言う場はあるということですので、ぜひケースなど含めて、配置が考慮されるように力を尽くしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":165,"id":"exchange-056"}]},{"id":"topic-10","title":"品川区乳児等通園支援事業に係る子ども・子育て支援事業計画の代用計画策定","agenda":"品川区乳児等通園支援事業に係る子ども・子育て支援事業計画の代用計画策定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"すみません、説明を聞き逃してしまったと思うのですが、別紙１の表で、必要定員数は、利用者数から割り出された必要な人数、枠ということなのか伺いたいと思います。私が見ていた中で、利用者数が令和８年４月１日でいくとニーズが５９２で、下の必要定員数が整備した数と思ったのですが、そこを伺いたい。あるいは、デメリットはないかもしれませんが、デメリットがあるのかどうか伺います。","respondent":"佐藤保育事業担当課長","answer":"子ども・子育て会議で出てきました意見についてですけれども、委員の方に子育てをされていらっしゃる方がいらっしゃいまして、そういった方から、実際に利用するまでの経緯、流れを伺いたいとご質問をいただきまして、国のシステムを活用してオンラインでご申請をいただいて。","voiceIndex":170,"id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、この必要定員数、４月１日時点では１０７人必要ということで、実際、定員がどれだけ埋まっているかで決まってくるので、具体的なところは分からないと思うのですけれども、現状として枠が足りるのかを伺います。この枠が１歳児、２歳児が１０人ずつで、ほかから見ると結構大きな枠で、ゼロ歳児はやらない、そうした内訳にした理由を伺います。","respondent":"佐藤保育事業担当課長","answer":"現状、この枠で足りるのかというご質問にお答えします。５月時点での空き枠が既に発表されてございまして、本事業を実施する事業所の空きの状況が、合計で２００を超える空きがありますので、算定させていただいている１０７の必要な枠に関しては足りると現状では認識しています。","voiceIndex":172,"id":"exchange-058"},{"speaker":"まつざわ委員","kind":"意見","question":"定員に限りがある中で、例えば、多胎児であったりとか、双子とか三つ子だったりとか、そういった家庭とか、親族の支援が得られない、近くに親がいなくて助けが必要、そういった支援の必要性が高い、そういったご家庭などが優先的に利用できるような、何かそんな枠組みはあるのか。","respondent":"佐藤保育事業担当課長","answer":"支援が必要なご家庭に対する支援の仕組みですが、基本的に我々、試行的事業で令和５年度から実施してございまして、そうしたご家庭のお預かりというのも継続して実施していますので、そこにつきましては、今後についてもしっかりと対応していきたいと考えているところです。","voiceIndex":177,"id":"exchange-059"}]},{"id":"topic-11","title":"その他","agenda":"その他","exchanges":[{"speaker":"若林委員","kind":"意見","question":"そうすると、そういう製造ラインは、よくテレビとかで見かけることがあるのですが、ノズルは１つではなくてたくさんありそうですが、そこら辺との兼ね合い、全てのノズルに付着していたのか、幾つもあるノズルのうちの１つだけれども、安全性を云々ということなのか、そこだけ。","respondent":"石井学務課長","answer":"安全性につきましては、雪印メグミルク株式会社からの報告を待っているところですけれども、全てのノズルについていたというよりは、消毒作業のために消毒液を噴霧するためのラインから出たものだと聞いております。ですので、現状は一部のノズルであると考えられます。","voiceIndex":185,"id":"exchange-060"},{"speaker":"のだて委員","kind":"質問","question":"明日からはきちんと届けられるということでしたけれども、それは別の製造ラインでやるのかをお伺いできればと思います。","respondent":"石井学務課長","answer":"復旧作業ですけれども、先ほど消毒のための消毒液噴霧の部分において見つかったということで、異物自体は現在除去されているのですが、消毒のやり方を変更するような形で対応ができるということで、通常どおりの出荷体制が組めるとの報告です。","voiceIndex":188,"id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7359#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":44555,"voices":191}},{"id":"r08-20260414-5","meetingId":"r08-m0405","date":"2026年4月14日","dateIso":"2026-04-14","committee":"総務委員会","time":"午後 １時００分～午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和８年陳情第１１号、身体の不自由な人がもっと投票しやすくなるよう現行制度の改善を求める陳情","agenda":"令和８年陳情第１１号、身体の不自由な人がもっと投票しやすくなるよう現行制度の改善を求める陳情","exchanges":[{"speaker":"西本委員","kind":"質問","question":"制度があるのは分かっているのですけれども、この「利用がしづらい」というのは、どういう観点でというところを教えてほしいのと、それから、介護状況になっているときに自分の意思判断がどこまでできるのかと思っていて、周りは連れていきたいと思っていても、やはりこれは自分の意思がしっかりと反映できるのが選挙であるべきだと思うのです。","respondent":"東野選挙管理委員会事務局長","answer":"ガイドヘルパーの利用につきましても、事業者が来てもらいたいと言っている時間に来られないとか、または同行する方が時間的に難しいですとか、そういうマッチングの問題もあるかと考えています。","voiceIndex":39,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"それと事前に申請するということなのですけれども、選挙がある場合には介助をしてほしいというのを、介護認定とか何か申請するときに、それは事前に申請はできるものなのでしょうか。介護認定するときに、自動的にお願いすることができれば登録できるのではないかと思うのですけれども、それはどういう仕組みになっているのでしょうか。","respondent":"東野選挙管理委員会事務局長","answer":"その中に訪問介護サービスを受けたいということであれば、そこの訪問介護サービスの中の身体介護のところに、官公署への届出の同行などという項目がありますので、そういったところを、あらかじめこの項目を使いたいと事前に登録しておく必要があるものです。","voiceIndex":41,"id":"exchange-002"},{"speaker":"西本委員","kind":"確認","question":"ありがとうございました。恐らく制度的に分からない方が結構いるかという感じはしています。なのでそこは、こういう陳情があったのも事実であるので、分かりやすく、また忘れないようにとか、介護認定とかいろいろ手続をするときに確認するとか、それももう少し周知できるかと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"実際、投票の方法として、障害者が国に要望などを出していますけれども、郵便投票の対象拡大として、事前にケアプランに入れておかなければいけないとか、施設・病院での不在者投票の要件は、おおむね５０人以上の人数要件があるらしいですけれども、そういうこともあったり、あと代理投票補助の柔軟化と様々な問題があると思うのですが、実際、根本的には国の法律の改正といいますか。","respondent":"東野選挙管理委員会事務局長","answer":"選挙時におけるタクシー等の補助を出したりですとか、バスの巡回をしていたりというのは、地方の自治体ではあります。品川区におきましては、４３投票所がありますので、歩いて行ける距離にはあるところを考えますと、なかなかそういう交通手段の補助は難しいかと考えています。","voiceIndex":44,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"そうすると、今の局長の話をこちらで解釈すると、やはりこれからも体の不自由な人がもっと投票しやすくなるような現行制度の改善は、それぞれ自治体でも国に要望しているし、障害者協議会のほうも国にしっかり要望されているというその方向で、社会全体が今動き出していると考えてよろしいでしょうか。それだけ教えてください。","respondent":"東野選挙管理委員会事務局長","answer":"今おっしゃったとおりでございまして、やはり体の不自由な方対しての投票を、各自治体だけではなく、国全体として今考えているところです。","voiceIndex":46,"id":"exchange-005"},{"speaker":"澤田委員","kind":"質問・要望","question":"本日結論を出す。不採択でお願いいたします。会派としても、ガイドヘルパーの人材を増やす取組について要望したりしていたのですが、それについても、区としてもより多くの人を支援していただけるように、ガイドヘルパーを増やす取組に力を入れてくださっていることもありますし、これからより使いやすくなるのではないかと期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-006"},{"speaker":"山本委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。本陳情の問題意識は重要であると思っておりまして、障害がある方や介護の必要な方々の投票しやすい環境整備は必要だと考えております。これについては、引き続きその要望をしつつ、その動向を見守っていただきたいと思います。支援制度の分かりやすい周知・啓発の強化と、支援制度の使いやすさ、さらなるアップデートをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-007"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"移動支援については、求めに応じて全て移動の支援をしていくのは、なかなか現実的には区の行政サイドの負担が大きいでしょうし、本当に郵便投票の拡充によって、移動支援ではなくて、郵便でできるという方も結構出てくるのではないかということもあると思いますので、そこをしっかりまずは拡充していくことによって、ひとまず陳情されている方の思いに応えられるかなというところが大事かと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-008"},{"speaker":"松本委員","kind":"質問・要望","question":"他の委員の皆さんもおっしゃっているとおり、問題意識としては重要かと考えますが、どのようにやるかは国の事項で、地方としては国に意見書の提出を求めるものでもないところでありますから、現実的には国にまずは変えていただきつつ、あとはできることを区でやっていくことになるかと思います。したがって、この陳情については不採択と申し上げざるを得ないかと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、本日結論を出すことと、採択でお願いいたします。陳情理由の下のほうで書いてありますけれども、よりよい制度に改善していただけるように、国や各自治体に要望すると。「よりよい制度に改善していただけるように望みます」ということですから、社会全体がこの動きになっているならば、私は採択するべきではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。今の適用範囲を広げるのは国のほうの制度ということで、国が今、検討しているということですから、それは待つしかないと思っています。現行制度の改善と言っているのですけれども、今いろいろと対処していただいているということで、私はやはり周知が足りないのではないかというところにあるので、周知をして、使っていただくのをまずはお願いしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-011"}]},{"id":"topic-02","title":"令和８年陳情第１２号（監査実施判断と弁護士相談費用）","agenda":"令和８年陳情第１２号（監査実施判断と弁護士相談費用）","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"その中に、品川区では、議会で選ばれた委員もいます。それが、弁護士が監査委員の中に入ってないですから、またわざわざ別の第三者に聞くのは、何か間違っているのではないかと思うのです。こういうことで今回はこちらのほうでは扱いませんとか、そういう判断をするのが筋道だと私は思うのですが、その辺について、どのようにお考えでしょうか。教えてください。","respondent":"黒田監査委員事務局長","answer":"監査委員の役割といたしましては、先ほどご説明申し上げたとおり、区の事務事業の執行や財務について監査を行うものであり、監査委員の監査は、これらの事務の適法性・能率性の確保を図る観点から行われているものでございまして、これらの監査の事務に当たりましては。","voiceIndex":62,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"私の質問が悪かったのかどうか分かりませんが、監査請求の内容が妥当か違法か不当かなどをきちんと判断して、回答するのが役割ではないですか。それを、監査委員がいるのに、またさらに第三者に聞くなら、監査委員は要らないではないですか。どうなのでしょう、その辺、ご見解をお聞かせください。","respondent":"黒田監査委員事務局長","answer":"今のご質問にありました、監査委員が最終的にその監査の内容について判断は、ご指摘のとおりでありまして、その監査を判断するに当たりまして、資料の作成を事務局で行っておりますので、事務局の資料の作成の際に、先ほど申し上げた技術士でありますが。","voiceIndex":64,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"かみ合わないので、質問してもずっと繰り返しになってしまうので、でも何度も申し上げますけれども、監査委員は、区の方針だ、会計だ、決算だ、予算だ、そういう様々なものをしっかり監査する。そのために監査委員は置かれているので、それは日本全国自治体がそうやっているわけですから、私は品川区もそこはしっかり考え直すべきではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-014"},{"speaker":"松本委員","kind":"質問・要望","question":"先ほどの説明の中で、今回、弁護士費用を出しているということで、３３万ではなく１２万余という話だったと思いますので、これは法令の解釈を監査委員事務局のほうで確認するためにというお話だったのですけれども、そこの流れをもう一回、経緯をご説明いただきたいというか、どういう流れで弁護士に相談することになったのかをご説明いただければと思います。","respondent":"黒田監査委員事務局長","answer":"これは一般的に形式的審査と申していますが、その次に、住民監査請求は区が行う全ての事業が対象となっているわけではございませんで、いわゆる違法・不当な財務会計行為が行われた場合に、いわゆる損害の補填や措置を求めることができる制度ですので。","voiceIndex":67,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"監査委員は何もやらないのですか。これは言い過ぎではないかと思うのですけれども、すごく誤解されているのかと思うのですが、実際は監査委員の方々は具体的にどのような活動をされているのでしょうか。現地とかに行っていろいろと調査しているのだと思うのですけれども、それも含めて結構忙しいのではないかと思うのですけれども、いかがですか。具体的に例があれば。","respondent":"黒田監査委員事務局長","answer":"監査委員の主な職務ですが、先ほどご説明いたしました、事務事業概要の３ページ、４ページをご覧いただきまして、３ページの一般監査にあります定期監査につきましては、前期と後期に、監査結果という形で議会に報告させていただいておりまして。","voiceIndex":69,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"行政ＯＢ、公認会計士の監査委員ということですけれども、多分この陳情で言っているのは、専門家の方を入れるべきではないのかということだと思うのですけれども、外部弁護士というのがあるのですけれども、弁護士さんとかの専門的な方が入ってもいいのではないかとおっしゃっている部分もあるのかなと思っているのですが、これは判断が難しい、この現４人ぐらいいるのかな、で判断がつかないものについては。","respondent":"黒田監査委員事務局長","answer":"監査委員につきましては冒頭、説明させていただいたとおり、区長が区議会の同意を得て、識見を有する者２名と、議員のうちから選任する監査委員２名を選任している状況でありますので、事務局といたしましては、選任された監査委員を支えて、指揮の下。","voiceIndex":71,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"やはり不安というか、弁護士などの専門家が委員であってもいいのではないかと言っているのではないかと思うのです。それは一応こういう決まりになっているからそうやっていますということは分からないではないのですけれども、それは現状は現状であって、でも弁護士とかそういう詳しい人たちに当初から入ってもらうことも必要な部分はあるのではないかと思うのですけれども、いかがでしょうか。","respondent":"中西総務課長","answer":"私どもとしましては、様々監査委員の在り方につきまして議論があることは承知していますが、現在のところ、適正に監査が行われていると思ってありますので、引き続き現在の制度運用を継続してまいりたいと考えています。","voiceIndex":73,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"ということは、弁護士等々の、本当にそういう方には、その都度、聞くだけでいいということですか。私は初めから入ってもらったほうがいいのではないかと思っているのですけれども、そういう検討はする必要はないという結論なのでしょうか。","respondent":"中西総務課長","answer":"現時点においては、この形で適正に運用されていると認識していますので、この運用を進めてまいりたいと考えています。","voiceIndex":75,"id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。その上で、本陳情が求める内容、法的専門性のある外部委員のみで構成することについては、同意しがたいので、不採択と考えます。我が会派としては、監査の独立性や専門性を高める観点から、これまでの監査委員制度に加えて、外部監査制度の導入を政策要望として要望してまいりましたので、これは引き続き要望していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-020"},{"speaker":"塚本副委員長","kind":"質問","question":"やはり行政に精通している者が、ある事業についての予算立て、執行が目的に沿っているのか、また、それは本当に区民の行政サービスとして必要なのか否か、そういったことの監査が通常業務の中では圧倒的に多いので、こういうことを判断すると、やはり行政に精通した人物を選定するほうが意味もありますし、法律的なことについては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-021"},{"speaker":"松本委員","kind":"質問・要望","question":"先ほど確認させていただきましたけれども、この陳情は若干、誤解があるところもあると思うのですけれども、このほかの流れをお伺いしたら、事務局のほうで法令解釈とかを検討されて、さらに法律相談も行われたところかと思います。そのように考えていくと、政策的な観点から、議員選出の監査委員がいたほうがいいというご意見は分かるのですが、それは１人でいいではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は本日結論を出すことと、採択でお願いします。先ほども申し上げましたけれども、監査には、お金を勘定できる公認会計士と、それから弁護士、これは最低限、設ける。それをこれからも続けていこうということなのですが、こういうやり方は私はまずいと思うので、しっかり区としても私は対応を考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。先ほども意見申しましたけれども、専門性が必要になって、これからもっと複雑な問題になってきたり、各行政事業とか監査していかなければいけないことを考えると、私は弁護士を入れてほしいと考えています。別に４名ではなくて、５名にすればいいのではないですか。議員が１人となると、１人の人に負荷がかかってしまうので、やはり複数いたほうがいい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-024"},{"speaker":"松本委員","kind":"質問","question":"陳情書の読み方でいったら、善意に解釈すれば、もちろん法的専門性のある外部委員だけと読まないことも可能ですけど、これは行政の部分が基本的には大事なので、全部弁護士ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-025"},{"speaker":"松本委員","kind":"質問・要望","question":"これは、でも須貝委員、読んでいただきたいのですけれども、監査委員を法的専門性のある外部委員で構成するよう区に求めてくださいなのです。全部弁護士にしますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-026"},{"speaker":"松本委員","kind":"質問","question":"法的専門性のある外部委員で構成すると書いてあるんです。須貝委員の意見と陳情の内容は違うではないですか。この陳情は、あくまで監査委員を法的専門性のある外部委員で構成するようと書いてあるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-027"},{"speaker":"須貝委員","kind":"意見","question":"そこまで深入りするとまずいかなと思って、私は発言はあえてしていませんが、本来なら監査委員に議員がなるべきではないのです。だってほとんど会計制度も分からない、法律制度も分からない、それだったら、内部の職員の方が入って見たほうがまだましです。だって議員はもともと監査される側にいるのに監査委員になるのがそもそもおかしいので、この趣旨は、私は間違ってないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-028"},{"speaker":"松本委員","kind":"意見","question":"伝わらないので、分かりました、私のほうの解釈は、監査委員の法的専門性のある外部委員で構成というのは、少なくとも法的な知識がある人たちで構成してくれという趣旨だと私のほうで解釈いたしまして、やむを得ず。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-029"}]},{"id":"topic-03","title":"令和８年陳情第１４号、オンラインによる情報公開請求における受理通知等の仕組みの整備に関する陳情","agenda":"令和８年陳情第１４号、オンラインによる情報公開請求における受理通知等の仕組みの整備に関する陳情","exchanges":[{"speaker":"西本委員","kind":"質問","question":"個人情報開示請求、個人情報なので、先ほどもご説明の中で結構難しいということもあるのですけれども、でも検討しているとおっしゃっていた部分があるので、どういう検討をなされるのか。私は個人情報開示となると、かなりハードルは高いのではないかと思っているのですけれども、その辺はどういう見解を持って今、進めようとしているのか教えてください。","respondent":"田口戦略広報課長","answer":"個人情報の開示の件につきまして、どのようなオンラインでの手続を検討しているかですが、今、品川区のほうでは電子申請のシステムを用意しておりまして、その中で、マイナンバーを使って本人確認をしてという手続の方法も取れる仕様になっておりますので、今後。","voiceIndex":106,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"すみません、私もあまり詳しくないかもしれません、個人情報というのは、これは自分に対して、いろいろな方々も、他人に対して、どこまで拡大されるものなのですか。","respondent":"田口戦略広報課長","answer":"こちらの保有個人情報の開示請求における個人情報についてですが、こちらはあくまでも申請者自身の情報に関することになりますので、ほかの人の情報は含まれない、自身の情報のみになります。","voiceIndex":108,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"今、検討されているということで、これからめどというか、このぐらいまでにはできるかとかという計画は立っているのでしょうか。","respondent":"田口戦略広報課長","answer":"オンライン申請の、いつぐらいにというめどですが、今年度中もしくは来年度中のうちにはというところで今、進めているところです。","voiceIndex":110,"id":"exchange-032"},{"speaker":"須貝委員","kind":"確認","question":"実際、オンライン情報公開請求となると、相手方の本人確認や受付の仕組みづくりが本当に大変なことになると思うので、それがこれから構築されていくには、まだかなりの時間がかかるのではないかと思います。行けるなら、何年後ぐらいのめどで考えていらっしゃるのか。駄目なら駄目なのか、考え方だけ教えてください。","respondent":"田口戦略広報課長","answer":"電子申請の関係で、どれぐらいのめどで考えているのかですが、まず受付するところについては、今年度もしくは来年度辺りで考えておりますが、ですが受理の通知ですとか、あとは期限の経過通知につきましては、導入されたとしても、対応の予定は考えておりません。","voiceIndex":112,"id":"exchange-033"},{"speaker":"塚本副委員長","kind":"質問","question":"大体ご説明いただきまして、区の対応をお伺いしたところですけれども、この陳情理由の４番のところで、品川区における開示請求の経過通知がされなかったというところがあって、ここについては、そのこと自体を直接的に、対応とかいろいろな今後の再発防止みたいなことは他の所管の範疇ということは一応承知しているのですけれども、戦略広報課として、いわゆる情報公開請求における一連の手続の中で。","respondent":"田口戦略広報課長","answer":"昨年度におきましては、全管理職を対象にしまして、ｅ－ラーニングで情報公開制度の弁護士による講義を受講しております。こちらは、今年度は係長級に対象を拡大しまして、さらにこちらの個人情報の公開につきまして知識を深めて、適切な運用に努めてまいりたいと考えております。","voiceIndex":114,"id":"exchange-034"},{"speaker":"澤田委員","kind":"質問","question":"本日結論を出す、不採択でお願いします。理由としましては、保有個人情報開示請求に係るオンライン申請について、利便性向上に向け現在、検討中であること、期限経過通知については、個別対応されていくということですので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-035"},{"speaker":"山本委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。ただ、方向性としては正しい一方で、ご説明にあったとおり、個人情報の開示については注意すべき点が結構あるということで、オンライン化を進めるとしても、成り済まし防止策や誤送付防止も含め、確実な制度設計をしていっていただいて、情報漏えいしない形で、急がずに、しっかりと仕組みをつくって進めていただきたいと思いますので、これはお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-036"},{"speaker":"塚本副委員長","kind":"質問","question":"本日結論を出すで、不採択でお願いいたします。期限経過通知については、先ほど課長からのご答弁があったとおりで、しっかり現行手続を過つことなくしていただければと重ねてお願いすることにはしておきたいですけれども、本陳情については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-037"},{"speaker":"松本委員","kind":"質問・要望","question":"本日の区民委員会のほうで、こちらの裁判の結果について報告がなされているようでありますけれども、そちらを拝見したとしても、区のほうの対応について問題が指摘されている、それと今回の陳情の１、２、３の大本のところが必ずしも対応するかといったら、そうではないところもあるかもしれませんが、やはり陳情の要旨のところを拝見すると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-038"},{"speaker":"須貝委員","kind":"確認","question":"本日結論を出すことと、今回は不採択でお願いしたいと思います。まだ整備するには時期早尚ということで、私はまだ早過ぎるのではないかと思います。本人確認や個人情報に対する対応でありますが、やはりそういうのをしっかり国の動向を見極めた上で、私は実際、進まざるを得ないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。なのでまだまだ品川区としては、情報公開制度に対して改善が必要だなと強く思っていますので、ぜひこれをきっかけに、オンラインという方法もありますけれども、今回は、より区民の方が請求できて、やはり区民の権利だと思いますので、さらに積み上げて、いろいろ改善すべきところを改善してもらいたいということで、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"これは、期間も含めてどういう形のやり取りになるのですか。これは工期が令和９年２月４日という形になっているのですけれども、そのお金のやり取りがどういう形でやり取りされるのか。品川区の負担はないのですよね、ということ。それと、これは近いですよね。北品川二丁目と三丁目の同じ工事の内容だと思うのですけれども、これを別々にして契約を結ぶのはなぜなのか教えてください。","respondent":"加島財政課長、廣瀬経理課長","answer":"８年度の予算につきましては、債務負担行為を組んだものから８年度に支出するものを現予算として取り扱わせていただいているものになります。基本的に、こちらは東京都からの受託事業ですので、１０分の１０、お金が入ってくるものです。河川下水道課から聞いている限りでお答えいたします。一括で発注した場合、大規模かつ短工期の工事となり、不調リスクが高いことから、より確実に再構築工事を進展させるため、複数の工事で発注したと聞いております。","voiceIndex":129,"id":"exchange-041"},{"speaker":"西本委員","kind":"確認","question":"不調になるおそれがあるからということですけれども、該当する事業者がいればいいのでしょうけれども、まとめてやったほうが、能力もあるか、ないかというのはあると思うのですけれども、金額的に安くなるとかはないのですか。もう一度確認をします。","respondent":"廣瀬経理課長","answer":"繰り返しのお答えなりますけれども、河川下水道課から聞いている限りでは、一括で発注してしまうと、大規模かつ短工期になってしまうので不調リスクが高いということで、複数の工事で発注したと伺っております。","voiceIndex":132,"id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"それによって、今いろいろ問題に違っていますけれども、不調の問題がありますけれども、それが解決されるという考え方になってくるのか、これからのこういう高額になってきた場合とか、法律とか、同じようなものでも、やはり分割してやる方向になっていくのか、そこはどうですか。","respondent":"廣瀬経理課長","answer":"規模や工期ですとかそういったところで、ケース・バイ・ケースにはなってくるものかとは思われますが、基本的には所管課のほうでご判断いただくものかと思います。","voiceIndex":134,"id":"exchange-043"},{"speaker":"須貝委員","kind":"意見","question":"北品川三丁目付近再構築その４工事ですが、報告事項なので、これで決まっているからいいのですけれども、これを総務委員会に出されると、入札金額が、落札したのは１億３,２００万円で、次点の１億３,２１１万円と１１万円の差なのです。何かお互いに入札価格が分かっているように、我々は感じてしまうのです。これでいいのかなと。意見だけ述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":136,"id":"exchange-044"}]},{"id":"topic-04","title":"「品川区ジェンダー平等と性の多様性を尊重し合う社会を実現するための計画」の策定","agenda":"「品川区ジェンダー平等と性の多様性を尊重し合う社会を実現するための計画」の策定","exchanges":[{"speaker":"西本委員","kind":"質問","question":"たくさんいただいた何かきっかけとか、どう評価されているかということと、やはりこれからですよねというご意見が多いかと思うのですけれども、あとこれの期待も結構あるのではないかと思うのですけれども、それについては、ただ単にホームページのほうで、こういうのがありますよと、それで周知できましたみたいなのだけだと、なかなかもったいないなという気持ちもあるので、何か周知するための工夫とか。","respondent":"木村人権・ジェンダー平等推進課長","answer":"その前に、地域の方々に対して説明をする機会をいただければ、まちに出て説明をさせていただいておりましたので、そういった形で周知が進められて、パブリックコメントについてもご意見をいただけたのではないかと推測しているところではあります。","voiceIndex":141,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、いろいろなところでのアプローチを今後もどんどんしていただきたいなと思っています。文章では割と分かりやすいのだけれども、具体的な行動としてどう取っていくのかがなかなかリンクできない部分があるかと思うので、そこも含めて、今後いろいろなイベントとか機会があったら、ご説明もしくはそういう分かっていただくためのイベントなどをしていただきたいなと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7367#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":31179,"voices":149}},{"id":"r08-20260415-21","meetingId":"r08-m0405","date":"2026年4月15日","dateIso":"2026-04-15","committee":"子ども若者支援・共生社会推進特別委員会","time":"午後 １時００分～午後 １時２０分","status":"正式会議録","sourceType":"formal","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"鈴木委員","kind":"提案","question":"委員長からもいろいろと提言のご提案とかもいただいて、改めて読み直してみたりして、区立保育園では支援チームができていて、ベーシックの研修は９割の保育士が受けていて、園長先生から、それから様々チームのリーダーの方とか、５段階の研修があって、いろいろと研修を受けているということがあったので、私は、５歳児健診とかで初めてそのように指摘されたときに、その子どもの親にとってはすごく衝撃で。","respondent":"せお委員長","answer":"議事録等も確認していきたいと思いますし、あと、今の鈴木委員のご意見について、何かほかの委員の方でご意見あったりしますでしょうか。追加することに関して。最後、正副で調整したいとは思うのですが、ご意見はよろしいですか。","voiceIndex":13,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"意見","question":"９月２５日のところで議論しているのですけれども、私立保育園に対してはどのようになっていますかということに対して、区で実施している研修にも私立保育園の職員も参加していただくことができますので、そのような研修を受けて、特別な支援が必要なお子様に対応されていると考えておりますという答弁でした。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これも本当はもっと前に出せばよかったのですけれども、今になって申し訳ないのですが、ご検討いただけたらありがたいと思って、１番のところで、学校および教職員のヤングケアラーへの理解を深めるために、研修を通じて必要な知見の習得に努められたいと書かれているので、これはすごく大事なことだと思ったのですけれども。","respondent":"せお委員長","answer":"（１）の記述に付け加える形で考えていますか。","voiceIndex":19,"id":"exchange-003"},{"speaker":"澤田委員","kind":"質問","question":"啓発の取組については、既にやっていなかったですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これについても様々取組はされている。例えば小学校６年生が対象で、台場小学校と芳水小学校で、出前で寸劇をやったりとか、そのようなところでやっているのですけれども、まだ全ての学校でやっている状況にはなっていないし、そういう点ではまだ始まったばかりという感じなので、それをさらに進めていただきたいという感じです。まだ２校だけなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうですね。啓発についても取組を強化していただきたいという感じです。","respondent":"せお委員長","answer":"よろしいですか。こちらも先ほどと同様、今いただいたご意見を基に、正副委員長で再度調整させていただきまして、次回の委員会で改めて案文をご提示しまして、決定してまいりたいと思います。よろしいでしょうか。","voiceIndex":26,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"重層的支援体制は、本当だったらもっと充実をこれからしていっていただきたいところなのですけれども、区としてもすごく複雑な仕組みになっていまして、地域包括支援センターを来年度地域に設置していくということで、今年検討されるところですし、重層的支援体制をどのように充実、拡充していくのかというのは、今まさに庁内でも検討されている段階なので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7369#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=21&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":5022,"voices":32}},{"id":"r08-20260415-20","meetingId":"r08-m0405","date":"2026年4月15日","dateIso":"2026-04-15","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午後 １時００分～午後 ２時２２分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"中高生リバースメンター事業","agenda":"中高生リバースメンター事業","exchanges":[{"speaker":"あくつ委員","kind":"提案","question":"例えば１番目の投票率の向上については、なかなか公正を保つというところの難しさから、模擬投票は難しいのではないでしょうかといった質疑をさせていただいたことをよく覚えています。２月に区長に事業化検討結果の報告があったと思います。例えば最初の、今回、公開討論会をご提言、ご提案され、事業化されたと書いてありますけれども、これは予算書のどこに載っているのか、まず教えてください。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"こちらは、予算書にリバースメンター事業という形で記載はされてございませんが、各所管課において、予算審議の際に、こちらのリバースメンターの提案を受けてという形でご説明をさせていただいていると考えています。","voiceIndex":21,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"そうすると、予算審議のときに説明をしたということですか。予算特別委員会の中で説明を受けたということでしょうか。","respondent":"石川ＳＤＧｓ推進担当課長、久保田企画経営部長","answer":"予算特別委員会の中でというよりは、各所管課がそれぞれ各委員会の中で、予算化の内容につきましてご説明をさせていただいているものと考えております。我々が既存の事業の中で、こうした提言を受けてやっていったものもありますし、新規で行ったものもありますので、その辺りについては、明確に議会にはご説明はしていないです。","voiceIndex":23,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"提案","question":"明確なご答弁をありがとうあります。ということは、今回初めてこのＳＤＧｓ推進・行財政改革特別委員会の中で、どういったものを事業化したのか説明を受けたという確認をしたかったので、それがまず１つ目です。ここについて、議会とどういう形で調整をしたのか、ご説明いただきたいのが１点。所管部署に投げて予算化をしたということですが、これはどういう議論があったのか確認させてください。","respondent":"久保田企画経営部長","answer":"それで、これに至るまでの経過ですけれども、選挙管理委員会などとは十分詰めて話をしてきておりまして、昨年もあくつ委員からの非常に機微な内容だから十分配慮するようにということを踏まえまして、選挙管理委員会と十分に打合せをした上で、公職選挙法に違反しない範囲の中で。","voiceIndex":26,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"提案","question":"今の内容から私は読み取れていなかったのですが、公開討論会は子ども向けということですか。そういうものを想定するのか、子どもが参加しやすい形での公開討論会を、今のお話だと例示で、別にそうでなければいけないことではないとありましたけれども、子ども向けのというニュアンスでのご提案、事業化ということでよろしいのでしょうか。","respondent":"久保田企画経営部長","answer":"提案された団体があれば、その団体の方たちと話をしていきますし、内容を詰めていく。それと、法律等に違反しない形で、きちんとそれが大丈夫なのか、あくつ委員からの指摘も踏まえて、きちんと捉えてやっていきたいと考えています。","voiceIndex":28,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"提案","question":"それと、十分に配慮していただいた上で、特定の候補に何か有利に働くようなことが絶対にないように、今回は予算の審議では、これは審議できなかったので、そこについて既に事業化されているということですから、ここについては今から撤回、子どもには報告があって我々には報告がないということで、これは日にちが２月２７日でしたか、ここについては報告しようと思えばできたはずなのです。","respondent":"久保田企画経営部長","answer":"ですが、今いただいたご意見もありますので、今年度につきましては何か工夫をして、議会の事前審査など、そういったものもいろいろ配慮して、どういった形で議会にもきちんと報告ができるかは、我々も検討して対応していきたいと思ってあります。","voiceIndex":30,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"事前審査になるのであれば、例えば予算のプレス発表が終わった後であるとか、我々が予算審議の前にそれができるような形で、ぜひお願いしたいと思います。それは幾らでもやりようがあると思います。それは申し訳ないけれども。そこは十分にご配慮いただきたいと申し上げざるを得ないということでご理解いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"それで、質問ですけれども、（２）拡充内容についてお伺いしたいのですが、昨年度１年間行ってきた経験を踏まえた上で、今回検討会を６回に増やすということですけれども、もう少しその理由を伺いたいと思います。これについては、なぜ拡充しようと思ったのかという点もお伺いします。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"具体的には、検討会の２回目に民間企業の事業化プロセスを学ぶ予定です。","voiceIndex":34,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"それと、これは非常に周知が重要だと思うのですけれども、結果的には１０人の枠しかないので、区内の中高生の全ての方には、こういう事業をやっているのだと知ってもらいたいと思うのですけれども、先ほどチラシ配布という話もありましたが、どういう配布の仕方をするのか、できれば一言添えて担任の方が全員に配付をすると同時に、こういう事業があるのですよという感じで。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"１点目の質問で、所管課、現場の感覚ですが、実際かなりＳＤＧｓに理解を示していただいて、中高生リバースメンター事業に対して理解を示していただいている所管課につきましては、かなりリバースメンターの方とも直接連絡を取って。","voiceIndex":36,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"現場の所管課は本当に苦労があるとは思うのですけれども、子どもから大人が学ぶところもかなりある事業だと思うのです。そういった意味では、かなり質的にこれまでの事業とは違う意味を持つ大事な事業だと思うのですけれども、現場の負担には目を配らせながら、ぜひ相互に学びが多い事業にしていただければと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"以前、この委員会の中でも確認をさせていただいたのですけれども、当初、リバースメンターの募集に当たっては、６００字程度の作文の審査が第一段階であり、作文の内容が、イコール出してきた生徒の問題・課題点であるので、そこが当日のプレゼンテーションにつながっていく流れだと確認をさせていただきまして、その検討会を経て、テーマを少し絞っていったり。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"配布先といたしまして、先ほど申し上げましたが、中学生ですとか高校生で、区立のお子様が行くであろう施設、図書館ですとか児童センターについては、今年は配架を考えておりまして、作文の採点の中で。","voiceIndex":40,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"多分これは、子どもたちの意見はしっかりと受け止めていきたいという思いもあってのことだと思うのですけれども、また、検討会の中で事業化にできるような流れをつくっていく視点もあると思うのですが、その辺りは基本、子どもたちの意見は、全員の意見をしっかりと受け止めていくことが前提としてあるのか、その辺りをもう一回確認させていただきたいと思います。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"１点目の、もし公開討論会を実施した場合の留意点で、おっしゃるとおり、新城市の条例内容、規定内容は当然、私どもも留意しなければいけない内容と考えていますので、他自治体の事例がここしかないというのもありますので、当然ここの内容を参考にしながら、ただ。","voiceIndex":42,"id":"exchange-011"},{"speaker":"山本委員","kind":"確認","question":"今までも様々な動きもありましたけれども、私からお聞きしたいのは、事業化検討結果の報告会を聞いた、まさにリバースメンターの皆さんのご感想です。自分たちが提言したものが区政でどう取り上げられたかを聞いたときの感想などはいかがでしたでしょうか。アンケートとかで確認されているのか、何かインタビューしているのか、その辺りをお聞かせください。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"２月２７日の報告会の様子ですが、リバースメンターの方は、一緒に検討を１０人でやってきたというところもありまして、事業化の報告についてもとても喜んでいただきましたし、あとはお互いに横の連携ができたのもありまして、卒業式のような形で、とても穏やかな雰囲気の中で。","voiceIndex":45,"id":"exchange-012"},{"speaker":"山本委員","kind":"質問・要望","question":"それからもう少し、横のつながりができたのもとてもすばらしいことだと思っておりまして、私たちの会派で、先ほども出ました新城市の若者議会を視察に行ったのですけれども、これも１０年ぐらいやっている中で、横のつながりがさらに縦に伸びていって、ＯＢ会みたいなのができて、そういうまとまりの中で、主権者教育がさらに深まっていったところもありますので。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"先ほどの先輩とのつながりというところですが、今年度の検討会につきましても、先輩リバースメンターとして検討会の１回目にご登壇いただいて、体験談とかをご披露いただく想定で考えております。","voiceIndex":47,"id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"新妻委員からもありましたけれども、区内中学生の応募を促す工夫で、私も以前の委員会で申し上げたので、区立学校に通う皆さんにもぜひ多く参加していただけるように工夫して、学校での周知等も進めていただきたいと私からも改めて要望します。ぜひ参加した中学生が、自分たちの声が区政に活かされたと実感できる事業として、さらに発展させていただきたいという思いです。今後の成果に期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-014"},{"speaker":"筒井委員","kind":"確認","question":"先ほどから人数の話も出ていますけれども、応募は１６人でしたか、その確認と、採用された１０人のうち１名が区内の学校の方で、応募の１６人のうちの区内１名ということですか。人数の内訳、区内の内訳を改めてお願いします。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"昨年度の応募状況ですが、応募１６名のうち、区内公立学校につきましては５名、私立につきましては１１名という内訳となっています。","voiceIndex":51,"id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。提言した生徒も、お互いすり合わせて納得した上で進めていく形なのでしょうか。そのときに、提言した生徒は、もう少しこのようにやりたかったのに、区からいろいろアドバイスを受けて修正せざるを得なかったときに、その生徒から何か不満の声とか、おかしいという声はなかったのですか。検討会の状況というか、その辺りを教えてください。","respondent":"石川ＳＤＧｓ推進担当課長","answer":"どちらかといいますと、寄り添って、まさに伴走支援で、中学生と高校生で進捗状況は人によって変わりますが、あくまで委託事業者が一対一で寄り添って、その子が本当に何をしたいのかを突き詰めて、一緒に考えていくというプロセスの検討会となっております。","voiceIndex":53,"id":"exchange-016"}]},{"id":"topic-02","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"確認なのですけれども、今日も中高生リバースメンター事業について議論をしたのですが、本日の議論はどのように反映させる流れなのか、そこだけ伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-017"},{"speaker":"あくつ委員","kind":"確認","question":"確認で、今日、いろいろな質疑がありましたけれども、そこについては新しいものを、今まとめていただいたのは、委員長と副委員長でまとめていただいていますけれども、今日の議論は委員長と副委員長でまとめていただくということでいいのですか。それを次の委員会にという話ですか。それは、中高生リバースメンター事業に関しては載ってくる。当日配られるものを確認するということでいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"また別のことについても、今日この中であればということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"公共施設等総合計画についての（１）ですが、ＰＦＩ等については、共産党としては意見として、当委員会では反対の意見を述べてきたものです。今の状況だと、十分な区民理解を得ることという文言で終わっているのですが、こうなりますと、ＰＦＩ等の導入を認めることが前提というのが固定化する表現になっているように見えるので、できれば慎重かつ丁寧に検討を行うで終わってほしいと、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"行政評価の（５）ですけれども、ゼロベース査定やサンセット条項等の仕組みを活用しとあるのですが、これらについては、共産党としてもろ手を挙げて賛成する内容でもないですし、委員会として意見は出ましたけれども、十分に議論されたわけではないと思うのです。したがいまして、この文言については外していただきたいと思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"行政評価について、（２）番で、全事業を対象とする事務事業評価は作業量が多く負担が大きいことから、制度見直しも含めとあるのですけれども、見直しも含むという話も出ていたのですか。今の森澤区政にとって根幹の制度なので、そこの表現を改めたほうがいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-022"},{"speaker":"こんの副委員長","kind":"提案","question":"議事録をきちんと記憶しているところではないですが、この部分については、皆さんがこの委員会で発言した議事録の中から、こういう趣旨の発言、こういう提案があって、ここに載ってきているので、当然、見直しもというご提案、ご要望があったところでの文言になっております。では、どこの議事録だったか、今そこは具体的にはあれなのですが、それを基に、このまとめの案文を作っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-023"},{"speaker":"あくつ委員","kind":"確認","question":"議論してきた内容を、議長を通して区長に出すということでしょうから、さっき安藤委員からもありましたけれども、安藤委員の会派としてのお考えは会派の意見として、合意して出すわけではないのだから、ただ、こういうものでいいですかという合意は当然必要だと思うのですけれども。だから、先ほど議論の中であったものについては、こういう意見があったという事実として載せるのはいいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7371#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":24792,"voices":88}},{"id":"r08-20260416-22","meetingId":"r08-m0405","date":"2026年4月16日","dateIso":"2026-04-16","committee":"まちづくり・公共交通推進特別委員会","time":"午後 １時００分～午後 ２時３９分","status":"正式会議録","sourceType":"formal","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"ご説明、ありがとうあります。前々からお話ししておりまして、今、やや具体的なことはご説明いただいたのですが、学識経験者が６名ということです。庁舎跡地の活用なので、私、個人的には法学部より、今も少しご説明がありましたけれども、まちづくりの専門的な知見のある方にお願いしたいと思っているのですが、そこの確認をさせていただきたいと思います。","respondent":"泉広町事業調整担当課長","answer":"令和５年から開催してまいりました品川区庁舎跡地等活用検討委員会には、委員からご案内いただきましたように３名の学識経験者に入っていただいてございましたけれども、その３名の方が今回の委員会にも入るかというところのご質問につきましては。","voiceIndex":15,"id":"exchange-001"},{"speaker":"田中委員","kind":"質問","question":"それはそれで、議論は議論で置いておいて、また新たな視点で、特にまちづくりの視点あるいは官民連携の経験がある方が入られることから大きく方向性は変わってくるような気もするというか、今後のことですのでそういうところには期待をしているのですけれども、これまでの検討結果との整合性といいますか、関係性として、新たな策定委員会ではどのようになるものなのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"これまでの検討の経過と関わり方のお話ですが、令和５年から策定してまいりました庁舎跡地等活用検討委員会のそういった成果の報告みたいなところにつきましては、これはやはり区民アンケートでありますとかワークショップなどを重ねまして、いただいてきた貴重な意見ですので。","voiceIndex":17,"id":"exchange-002"},{"speaker":"塚本委員","kind":"質問","question":"委員構成のところで私もお伺いしたいのですけれども、これまでの品川区庁舎跡地等活用検討委員会の構成メンバーから比べると大分人数も減ったし、委員の構成も学識経験者と区議会議員に絞られているということです。こういう構成になったことに対する考え、どうしてかを聞きたいです。","respondent":"泉広町事業調整担当課長","answer":"今回、こういった委員構成になりましたのは、先ほどの説明とも重なりますけれども、今後都市計画に関わるような少し専門性の高いお話も入ってくることに加えまして、非常に幅広い区民ニーズをこれまでいただいているところから。","voiceIndex":20,"id":"exchange-003"},{"speaker":"藤原委員","kind":"意見","question":"庁舎跡地活用プラン策定委員会の設置に関しては分かりましたけれども、この品川区庁舎は品川区民お一人お一人の財産です。今ぱっとできたのではなく、先代、先々代とずっと品川区に住民税を払っていただいて、代々区民であられた方をはじめ、そういう方たちがつくってきたというか、そういうものであると私は思っています。その辺については、どのように考えていますか。","respondent":"泉広町事業調整担当課長","answer":"一方で今回３名という形で計画をしていますけれども、今後特別委員会になるのかはこれからかもしれませんが、こういった区議会の場でも要所要所でご説明、ご報告を差し上げながら、皆様方の様々なご意見を頂戴いたしまして。","voiceIndex":22,"id":"exchange-004"},{"speaker":"藤原委員","kind":"質問・要望","question":"その意見を行政側として、やはりしっかりとつかんでいく。私は、そう思います。ですから、区議会議員が３人入っているでしょうということではなく、議会全体として、また議員として、その辺のことをしっかり考えていただいて、施策として進めていっていただきたいと思うのですけれども、その辺について改めて答弁ください。","respondent":"泉広町事業調整担当課長","answer":"先ほどと重なりますけれども、しっかり委員会の場などを用いまして議論をさせていただきながら、共に進めてまいりたいと考えています。","voiceIndex":24,"id":"exchange-005"},{"speaker":"えのした委員","kind":"質問","question":"ＯＩＭＡＣＨＩ ＴＲＡＣＫＳができて大分にぎやかになって、私たちも視察に行かせていただきましたけれども、先ほど課長から説明があったように学識経験者、都市計画ですとか区民ニーズの専門の方、その中で他の自治体での経験があるというところで、他の自治体でも同じような駅、そして区庁舎、複合施設、そういったものが一体として再開発されたような自治体は、現実事例があるのですか。","respondent":"泉広町事業調整担当課長","answer":"私たちの調べによれば、こういった区分におきまして庁舎に関わらず公有地を活用いたしまして、今回は定期借地の形を想定していますけれども、そういった制度を活用しながらそういったニーズをかなえるために複合の機能を考えてきた事例は様々あると認識をしています。","voiceIndex":27,"id":"exchange-006"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。今、人流というか人の流れというか、隣がＪＲ東日本ですから調査などはされているとは思うのですけれども、庁舎跡地活用検討委員会のときにはフリーワークショップやアンケート、対話型市場調査について。それとも、これは委員会が立ち上がってから考えられていくのか。そちらをお聞かせください。","respondent":"泉広町事業調整担当課長","answer":"ＯＩＭＡＣＨＩ ＴＲＡＣＫＳも区民だけではならず、広域的なところから人がいらっしゃっていると思いますので、そういったことの情報をＪＲからもらっていくのか、また、区のほうからしっかり取りに行くのかはこれからの検討になりますけれども。","voiceIndex":29,"id":"exchange-007"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"全体の話だけ聞きます。そこら辺の日程的なことを教えていただきたいということが１つ。そうすると、今どこのデベロッパーもゼネコンも提案をしてくるのが、タワーマンションが多くなっている。やはり、山手線。道路を挟んだ反対側の再開発も一緒に考えていくことが必要になってくると思っているので、これは何度も言っているからいいのだけれども、そういうものを１回提案してもらう。ここで１回止めます。","respondent":"泉広町事業調整担当課長","answer":"そうしますと、令和１１年度には通常で考えれば基本計画レベルのものが進んでまいりまして、翌年度の令和１２年には基本設計、令和１３年には実施設計までという流れになるのかと考えています。","voiceIndex":32,"id":"exchange-008"},{"speaker":"のだて委員長","kind":"質問・要望","question":"ほかに、いかがでしょうか。私から１点だけ。今回、皆さんからもいろいろ様々な意見がありましたけれども、やはり庁舎跡地ということで皆さん注目されていると思います。この会議は公開されるのかどうか。会議録はぜひ全文公開をしていただきたいということで、区民の皆さんにもしっかりとどういった議論がされているのかが分かるようにしていただきたいと思うのですが、いかがでしょうか。","respondent":"泉広町事業調整担当課長","answer":"ただし、対話型調査のサウンディング調査の結果など、内容によっては慎重に考えなければいけない内容もあるかもしれないと考えられますので、そういったところにつきましては委員会の委員長などとも相談をしながら、考えてまいりたいと考えています。","voiceIndex":35,"id":"exchange-009"},{"speaker":"松本委員","kind":"質問","question":"ご説明、ありがとうあります。８ページですけれども、休日の通行者数の結果で、通常時に比べると１１月１日については１３％増えたかと思うのですが、一方で同じ休日である１１月２日を見ると少し減っている状況かと思います。そこの分析については、今どのようにお考えでしょうか。","respondent":"中道都市開発課長","answer":"一方で、やはりイベントをやっていると通常よりも増える場面が多かったので、一定程度イベントはやはり効果があると実験等で確認しております。","voiceIndex":41,"id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"先ほど周知方法は２ページでご報告いただいていたかと思います。ここで少し気になるのが、公式アカウントを作成なので、多分新たにアカウントをつくってやられたのかと推察するのですけれども、公式アカウントのフォロワー数はどのくらいになったのか。そことの関係で、Ｘだったらいわゆるリツイートと言われているものとかをどのくらいやられたのかを少しお伺いできればと思います。","respondent":"中道都市開発課長","answer":"アカウントを既存のアカウントと連携して急に広げていき、また、いわゆる発信も毎日数回やるような形で広域的な発信を試みました。","voiceIndex":43,"id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"せっかくやっていることを皆さんに周知していく。もう１個気になるところで、今回の考察のところです。少なくとも、いろいろな意見がある中でもここは特によろしくないところだと思うのですけれども、喫煙への嫌悪はもともとここで喫煙している人がいることへの嫌悪なのか、今回のイベントによってこうした喫煙をしている人が見られたのか、この辺りはどのようにお考えでしょうか。","respondent":"中道都市開発課長","answer":"実験の空間としては、特に灰皿を置くなどはなかったのですけれども、やはりそこで吸ってしまわれた方がいらっしゃったのかです。","voiceIndex":45,"id":"exchange-012"},{"speaker":"松本委員","kind":"質問・要望","question":"これは要望です。もう１個、その上のにぎわいのところです。今回の１０ページの考察のところで、にぎわいはＴＲＡＣＫＳ、日常的な生活環境の向上は大井町駅前中央通りという役割分担が求められると書いてしまっているのですけれども、果たしてそれでいいのかは考えないといけないのかと思っています。ここの部分はどのようにお考えでしょうか。","respondent":"中道都市開発課長","answer":"地域の方が実際にそれを見てどのように今後考えていくのか、そういった機運調整も今回の実験の目的になってあります。","voiceIndex":47,"id":"exchange-013"},{"speaker":"松本委員","kind":"意見","question":"最後は１件だけにしておきますけれども、商店街の皆さんへの伝え方も気をつけていただければと思います。お祭りとか何でもそうですけれども、お祭りをやろうとすると実行する側は盛り上げていきたいし、でもそれに対して夜勤で昼は寝ているからやめてくれという側も両方いて、これはどちらの意見も出てくるだろうと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-014"},{"speaker":"えのした委員","kind":"確認","question":"ご説明、ありがとうあります。地域の方たちのお声が一番だとは思いますが、なかなかバランスが難しいと思いつつも、４ページのエリア１で音楽イベントによる観客同士の交流を期待したが、評価としては見られなかったと入っています。交流を期待したがあまりなかったというのは、キッチンカーでアルコールは販売されていたのですか。実際、アルコールは販売されていたのか。こちらを確認したいです。","respondent":"中道都市開発課長","answer":"アルコールは、販売してございません。当初、区といたしましても夕方から夜８時くらいまでアルコールのキッチンカーを出して、こういった夜の涼んでいるときにそこでお酒を飲むみたいな、そういった交流の場もあってもいいのかと考えて計画を進めていました。","voiceIndex":50,"id":"exchange-015"},{"speaker":"えのした委員","kind":"意見","question":"アルコールの販売がなかった。今後、実験をする可能性があるのか。今はアルコールの話だけになりましたけれども、こういったイベントをやると喫煙以外に騒音だけではなくてごみの問題も入っていなかったのですが、やはりごみとか清掃について地域の方はこういったイベントで気にしますので、その辺は今回どのようなお声があったのか、そちらもお聞かせください。","respondent":"中道都市開発課長","answer":"アルコールの件ですけれども、区といたしましてもやはりアルコールがもたらす人と人との交流の効果みたいなところはもちろん認識はしている中で、今回実験でもそういったことをしていきたかったところですけれども、時間をかけて様々そういったご説明をしたのですが。","voiceIndex":52,"id":"exchange-016"},{"speaker":"えのした委員","kind":"意見","question":"ありがとうございました。行く行くはご理解を得て実験することができれば、昼間でもにぎわいを創出できます。こちら、今回この実験に使われたのか。最初に導入するとき、どんたく祭りの関係者にやはりどんたく祭りでトイレを借りているのだと、レンタルしているからそのレンタル代も結構するから、そういったときに使用できませんかとお話もあったので、その辺をどのようにお考えなのかお聞かせください。","respondent":"中道都市開発課長","answer":"常時トラックを置くとなると空間スペースが減ってしまうというバランスもありますので、そういったところも検討しながらいきたいと考えています。","voiceIndex":54,"id":"exchange-017"},{"speaker":"田中委員","kind":"確認","question":"重ならないように質問していきます。８ページの周辺道路への影響についてですが、これは今回の実証実験をする場所にパーキングがあったけれども、それを外したことに伴って周辺にどう影響があるかという視点だと思います。この憩いの場所に来るために外から車でということの要素は入っていないという意味で捉えていいのでしょうか。そこを確認したいと思います。","respondent":"中道都市開発課長","answer":"今、委員からお話がございましたとおり、このイベントに対して車で来場された方は特段いらっしゃいませんでした。","voiceIndex":56,"id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"８ページのこのイベントをやるに当たって、周辺に新たな駐車場なり駐輪場が必要だという視点での調査ではないですか。そういう意味合いは含まれていないのでしょうか。","respondent":"中道都市開発課長","answer":"この大井町駅前中央通りには警視庁のコインパーキングがございまして、非常に毎日このパーキングの利用者が多いことは社会実験前に認識している状況です。","voiceIndex":58,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"一方で例えば自転車で来る方が増えてしまうと、周辺の駐輪場の確保もまた新たな課題になってくるのかとも思えます。それと、１０ページですけれども、こういう実験をする本来の目的は、やはり大井町全体のにぎわいを創出する上での役割として、こういう公共交通空間を有効に活かすことが求められると思うのです。一番下に２月からのスケジュールがあります。ここの意味合いをお伺いしたいと思います。","respondent":"中道都市開発課長","answer":"令和７年度の社会実験ですけれども、初日にハロウィンのイベントと合わせて社会実験を開始いたしました。","voiceIndex":60,"id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"実証実験の結果を拝見しました。そもそもですけれども、この実証実験をするのに１回の実証実験で５,０００万円近く予算を使っています。そうすると、この実証実験だけで１億円近く税金を使うわけです。私は、今年度の実証実験でもう方向性を決めていくと思っているのですけれども、実験２回で１億円。１億円もかけてという思いも実験に関してはあるのですが、その辺についてはいかがでしょうか。","respondent":"中道都市開発課長","answer":"今年度は、東京都からこういった都市計画道路の再編に向けた検討というところで、半額補助が入る形での調整ができましたので、歳入といたしましては２,５００万円入る予定となっています。","voiceIndex":62,"id":"exchange-021"},{"speaker":"藤原委員","kind":"質問・要望","question":"区の全体のと考えたら、７,５００万円は割合的には大きくないかもしれませんけれども、やはり７,５００万円も使って実験するわけですから、改めて方向性だけは出していただきたい。そして、実証実験をしてしまったのだから、必ずやらなければいけない施策なのだではなくて、実証実験をした結果をきちんと踏まえてどういう方向性にするかをしっかり考えていただきたいと思うのですが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"今後の考え方といたしましては、実験を２回やってそれに対してやったから必ず今後に結びつけるかではなくて、今回は実験ですのでやはり実験の結果を踏まえて今後の方向性をきちんと検討していくものかと考えています。","voiceIndex":64,"id":"exchange-022"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"社会実験について１つ聞きたいのは、せっかくこれだけやったのですけれども、回答は１３５件ということをどう捉えていらっしゃるのか教えていただきたいです。１０ページ目に非常にいいことがたくさん書いてあります。例えば、小さい子どもがいたら、公園の水が流れているところで、小さい子どもなんかはそこにつかったり浴びたり、公園なんかは憩いの場という感じが夏なんかは特にあるではないですか。","respondent":"中道都市開発課長","answer":"昨年度、その気持ちで望んだのですけれども、それと同等くらいの非常に強い気持ちをお持ちの方もいたというところで、ちょうど協議の結果、ご説明したような対応をしてきたところです。","voiceIndex":67,"id":"exchange-023"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"店をつくってしまう。歩道とかしゃれたお店をつくっていくとか、社会実験があった後にこれを具体的にやっていくには相当必要性を持って検討していかないとと思うけれど、そこにちょっとしたカフェみたいなものをつくったら、もしかしたら周りの方からはすごく怒られるとか、いろいろあるわけではないですか。だけれども、そこが憩いの場になるのだとしたらそれは成功なわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-024"},{"speaker":"若林委員","kind":"質問","question":"先ほど、都の助成金が２,５００万円とありました。これは都の助成金が入ることによって今年度何か縛りが出てくるのか教えてください。","respondent":"中道都市開発課長","answer":"実験の内容について、特に何か東京都の条件等があるものではございませんので、昨年度と同様に様々区としまして検討していきたいと考えています。手続としましては、補助金を歳入でいただきますので、それに対しての書類等について、東京都への報告があります。","voiceIndex":71,"id":"exchange-025"},{"speaker":"若林委員","kind":"質問","question":"都市開発で見る、いわゆる社会実験の中での大井町駅周辺全体のエリアは、どういうイメージなのでしょうか。","respondent":"中道都市開発課長","answer":"そこに合わせまして今後都市開発課並びに都市計画課、そういったところで対応していきたいと考えています。","voiceIndex":75,"id":"exchange-026"},{"speaker":"若林委員","kind":"質問","question":"都市開発課と都市計画課で検討して、今のお話だとさらに広げていくお考えだと認識をいたしました。どうもこのプラスは取ってつけたような、言葉遣いがすみません。商店街が発展することなのか、町会が発展することなのかが見えないので、どういうことなのですかという聞き方を僕はできないような気がするのですけれども、これは意見として言わせていただきます。質問にはいたしません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-027"},{"speaker":"のだて委員長","kind":"質問","question":"ほかに、いかがでしょうか。なければ、私から幾つか伺いたいと思います。いろいろアンケートを行われており、来街者のアンケートは出ておりますけれども、事業者の方からのアンケートの声ではどんな声があったのかを伺いたいです。でも、ＡＩの評価指標で見るとあまり変化がなかったということで、これをどう見ていらっしゃるのか伺いたいと思います。この評価の仕方についての区の考えを伺いたいと思います。","respondent":"中道都市開発課長","answer":"もちろんこういった空間ができることによって、自分が今後出店できるのかみたいな前向きな回答もいただいており、こういった新しいことをやることに対しては非常に様々な声をいただきました。","voiceIndex":78,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7373#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=22&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":29033,"voices":89}},{"id":"r08-20260423-10","meetingId":"r08-m0405","date":"2026年4月23日","dateIso":"2026-04-23","committee":"議会運営委員会","time":"午後 １時００分～午後 １時０７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特別委員会の調査事項等","agenda":"特別委員会の調査事項等","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"１点、まちづくり・公共交通推進特別委員会の備考で、大井町駅周辺地区の回遊性とあるのですけれども、私たちとしては回遊性という名の下に、例えばＣ地区や下神明など、周辺地区の新たな再開発を、そこに住む地域住民の頭越しに議会のほうで進めるようなことがあってはいけないと思っているのですが、特別委員会の運営に当たってはその点、留意していただきたいと思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"議会選出委員の推薦","agenda":"議会選出委員の推薦","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"合わせると５名ということですけれども、共産党としては、１番の庁舎跡地活用プラン策定委員会のほうにぜひ立候補したいと思っているのですが、例えば１番と２番を分けるというよりも、合わせてそちらで考えていただいて、庁舎跡地活用プランのほうに共産党を入れていただくとはいかないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"配分はそれで結構かと思いますけれども、細かいことを教えてください。区の庁舎跡地活用プランの策定委員会については、ここ何年間かずっと議員を入れてくれという話をいろいろなところでしてきて、ようやくこういう形で出てきたのですが、もし何か執行機関から全体の構成が何人で議会として何人出してほしいというご説明があったのであれば教えていただきたいと思います。","respondent":"大澤区議会事務局長","answer":"４月１６日のまちづくり・公共交通推進特別委員会で説明があったと聞いておりますけれども、委員の構成は９名、学識経験者が６名、区議会議員が３名となっております。","voiceIndex":12,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"確認","question":"そのときどういう質疑があったのか分かりませんけれども、学識経験者が６名、大学の先生なのでしょうか、ちょっと分かりませんけれども、区議会議員が３名ということで、私が思っていた形とは違うのかなというところもあるのですが、入れていただいたところは敬意を表しますので、なぜそのような構成になったのかというのは特別委員会で質疑があったのかもしれないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7375#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":2778,"voices":21}},{"id":"r08-20260511-6","meetingId":"r08-m0405","date":"2026年5月11日","dateIso":"2026-05-11","committee":"区民委員会","time":"午後 １時００分～午後 ２時１３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和５年陳情第３１号、行政が運営主体となる新規火葬場建設を求める陳情","agenda":"令和５年陳情第３１号、行政が運営主体となる新規火葬場建設を求める陳情","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"陳情も、これ、３年前の状況なのですけれども、このときの議事録を読みまして、震災のときに桐ヶ谷斎場は受け入れてくれるのかという、その辺の心配と、コロナの患者は今はそういったものは話題ではないのですが、やはり同じような感染症が起きたときに、桐ヶ谷斎場の受入れはどうなっているのか。その辺りの話合いというのは、このときからまた区として進んではいるのでしょうか。","respondent":"赤木生活衛生課長","answer":"こちらの陳情の中にも当時のコロナ禍のお話がありましたけれども、当初、国から示されたガイドラインの内容で、ウイルスがどういったウイルスなのか分からない状況だったというところで。","voiceIndex":6,"id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問・要望","question":"民間の企業ですけれども、必要なものですので、引き続き対話は続けていただきたいと考えています。災害時も、公益で考えているということですので、個別でも協力しますという強い返答みたいなものをもらえると、少し安心できるのかと思います。今、臨海斎場の増築計画が大分滞りなく進んでおりますが、直近の臨海斎場の利用率みたいなものが分かれば、教えていただきたいと思います。","respondent":"築山戸籍住民課長","answer":"今、臨海斎場から公式に出ているものが令和６年度のものになっていまして、令和７年度につきましては、この後また組織区での会議体がありますので、そこで発表されることになると思いますけれども、今手元にあるのが令和６年度ですので、その数値でいきますと。","voiceIndex":8,"id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問","question":"やはり大田区の方が一番多くて、次が品川区という割合でしょうか。そこは変わらず。","respondent":"築山戸籍住民課長","answer":"おっしゃるとおりでして、大田区が最も多くて、次が品川区になっております。","voiceIndex":12,"id":"exchange-003"},{"speaker":"こしば委員","kind":"質問・要望","question":"この問題というのは、結局、個々の火葬場の火葬能力というのですか、そういったものに結構起因してくるものかと思っていまして、先ほどの質疑応答の中で、臨海斎場の稼働率は８１.９％という答えだったのですけれども、対して桐ヶ谷斎場は、調べたら、４３％。その現状について、教えていただきたいと思います。","respondent":"赤木生活衛生課長","answer":"もう１点、永続性の部分についてですけれども、火葬業を永続的に運営していくためには、火葬炉がしっかりと管理された状態で、しっかりと修繕だったり、その他もろもろ、そういった管理が徹底されているというところの部分がある程度計画的に行われないと。","voiceIndex":16,"id":"exchange-004"},{"speaker":"こしば委員","kind":"質問","question":"営利性の話なのですけれども、葬祭業と火葬業の収支が一体化されている状況にあるので、調査をしているということでよろしかったですか。要は、その調査をして、本来であれば、火葬と葬祭は別の会計処理がなされて、火葬は特に非営利性が要求されるもので、葬祭もそうなのですけれども、そこがやはり徹底されていかなければいけないのですが、現状ではそれがまだ一体化しているという。","respondent":"赤木生活衛生課長","answer":"会計の分離がされていなかったのが令和４年度まででございまして、東京博善側から令和５年度より会計の分離をするというところで回答がございまして、それ以降の会計につきまして、令和６年度、令和７年度、なので。","voiceIndex":18,"id":"exchange-005"},{"speaker":"こしば委員","kind":"質問","question":"まだ分からないのですか。今調査をしていると言ったので、調査しているということは、それに対しての結果が出てくるわけですよね。","respondent":"赤木生活衛生課長","answer":"令和８年度、今年度につきましては現在調査中ですけれども、実績としまして、令和６年度の調査、令和７年度の調査において、会計がしっかりと分離されていることについてはこちらで確認させていただいたです。","voiceIndex":20,"id":"exchange-006"},{"speaker":"こしば委員","kind":"確認","question":"要は、調査の結果、しっかりと会計が分離されていて、非営利性があると確認をしたということ。認識いたしました。今後、臨海斎場の火葬炉を２０炉に増やしていくということなのですけれども、そうした場合に、今時点、稼働率が８割なのですが、どのくらいまで抑えられそうなのか、その辺の予測について、下がっていくのかと思うのですけれども、その辺りの見通しについて教えてください。","respondent":"築山戸籍住民課長","answer":"直近の火葬件数を臨海斎場に聞いたところ、令和４年度がコロナ禍でピークで年間９,８４１件あったのですが、それ以降、減少しておりまして、令和６年度から令和７年度で、数字はまだ出ていないのですが、令和６年度からも火葬件数が下がってるということを聞いておりますので。","voiceIndex":22,"id":"exchange-007"},{"speaker":"こしば委員","kind":"質問・要望","question":"今後の見通しとしては、明るい見通しというのは承知いたしました。確かに営利性がないということは調査などで確認されたかもしれませんが、今後、東京都と、あと、区長会も厚生労働省に法律の改正などを求めておりますので、その辺を注視して、なるべく斎場ごとの格差が広がらないような対策を、品川区だけの問題ではないかもしれませんけれども、ぜひ取り組んでいただきたいと思います。","respondent":"築山戸籍住民課長","answer":"アクセスについてですが、これは増築に向けて、臨海斎場や組織区５区とともに、また引き続きアクセスについては、在り方について検討していくということで継続していきたいと考えております。","voiceIndex":24,"id":"exchange-008"},{"speaker":"こしば委員","kind":"質問","question":"継続でお願いいたします。理由としましては、先ほど話したとおり、地域の火葬場を増設することで全てが解決するわけではなく、やはり稼働率、また、火葬能力の話になってくると思いますので、その辺、火葬場の格差というのをなくしていく努力を模索していかなければならないと考えますので、継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"},{"speaker":"おぎの委員","kind":"意見","question":"継続でお願いします。２万７,０００円の助成金制度もできたのですが、根本解決になっているわけではありませんので、火葬場の在り方について引き続き考えていかなければいけないのかと思いますので、継続でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-010"},{"speaker":"こんの委員","kind":"質問・要望","question":"本陳情は継続でお願いしたいと思います。その理由は、先ほど課長からもご説明がありました、臨海斎場の増設です。その一方で、今後、安定した葬儀・火葬行政、こうしたものがあることによって、安心した区民の死後に対応できると考えると、一方で、都議会公明党ではこのことについて代表質問をしておりまして、公営火葬場の新設を考える自治体に対して支援を求めたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-011"},{"speaker":"せらく委員","kind":"質問・要望","question":"継続でお願いいたします。令和５年に陳情が出てきたときから、審議の中でもお話を伺ってきまして、必要性があると理解しているのですけれども、やはり新規火葬場の建設は難しいという現実があると認識します。区民葬儀の助成や臨海斎場の機能拡充を確実に進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"継続でお願いいたします。どうしても荏原地区だとアクセスが悪いというのが、区もそれは承知しているかと思うのですけれども、ぜひバス事業者にも働きかけて、アクセスがしやすいようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-013"}]},{"id":"topic-02","title":"マイナンバーカード更新会場の増設","agenda":"マイナンバーカード更新会場の増設","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"何点か確認させてください。それから、初歩的な確認で、事務の取扱いです。それは今までどおり庁舎に来ていただくのかというところの確認と、３点目が、予約制で対応してくださるということなのですが、そうすると、１人当たりどれぐらいの時間を、２４件ですので、業務時間内で割り返すとというところなのでしょうけれども、どれぐらいを見込んでいらっしゃるのか。","respondent":"築山戸籍住民課長","answer":"職員につきましては、今年度、会計年度任用職員を各センターごと３名ずつ配置しておりますので、その中でやりくりをしていくということで、計画を立てているところです。","voiceIndex":37,"id":"exchange-014"},{"speaker":"こんの委員","kind":"質問","question":"いずれにしても、区民の方が効率的に手続が進められる方法を考えてくださっていることなので、ここは私たちとしても、こういうところでもやっていますという周知も図っていかれるようにしたいと思いますので、細かくそうしたこの体制も、今後、整えていってというか、教えていただければと思いますので、最後、先ほどの既存のところでの予約制というのは今後どうでしょうかというところはいかがでしょうか。","respondent":"築山戸籍住民課長","answer":"は荏原第五地域センターと大井第二地域センターで予約制を導入しますので、そういった状況等を見ながら、もし可能であれば、検討していきたいと思います。","voiceIndex":41,"id":"exchange-015"},{"speaker":"おぎの委員","kind":"質問","question":"更新会場の増設の件ではないのですけれども、関連して１点だけお聞かせください。荏原郵便局が業務委託で、２０２３年から証明書の会場として、手続できる方本人限定で、委託をお願いしている状態ですが、こちらは１年ごとの更新で、双方が同意して更新を続けている状態かと。過去の資料を見ると、そういった認識ではありますけれども、現状は郵便局はどんな感じなのでしょうか。","respondent":"築山戸籍住民課長","answer":"荏原郵便局での対応ですけれども、特段、現場から何か困ったという声は聞いておりません。","voiceIndex":44,"id":"exchange-016"}]},{"id":"topic-03","title":"地方創生ベンチャーサミット２０２６への参加","agenda":"地方創生ベンチャーサミット２０２６への参加","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"今年度初めて参加されるという認識でよろしいのでしょうか。こういったものに参加されますと、官民協力して、地域課題解決であったり、地域の産業のスタートアップ支援みたいなものにつながるのかと思うのですが、品川区以外で過去こういったものに参加されて、ほかの自治体とかで、この交流から生まれた実績みたいなもの、実例みたいなものをお聞かせいただけると、イメージが湧くと思うのですが。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"ほかの自治体がこれを通してどういった実績があるのかというのは把握し切れていないところではありますけれども、品川区としましては、これに限らずいろいろなところに出ていって、区の施策をＰＲしたり、呼び込みをすることで、例えば。","voiceIndex":50,"id":"exchange-017"},{"speaker":"おぎの委員","kind":"確認","question":"昨年も参加されて、今年２回目ということで、少し交流とか、昨年の参加、発信から動きが出てきているということは、今確認させていただきました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"確かにこういった、１自治体ではできないところをいかにして解決するかといったところは、まさにご指摘のとおり、様々な人脈ですとかネットワーク、それから、おっしゃったように。","voiceIndex":52,"id":"exchange-018"},{"speaker":"おぎの委員","kind":"質問・要望","question":"力強いお言葉、ありがとうあります。こういったイベントで、今回区長も登壇者で出られるということで、本当に力強く品川区の産業や文化などを発信して、ぜひいろいろ共感を得てきていただきたいと考えています。イベントだけでなく、その後の実装の部分でもサポートしていただいて、品川区らしい文化や産業などが発展していくようによろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-019"}]},{"id":"topic-04","title":"品川歴史館企画展「学芸員のイチオシ！」","agenda":"品川歴史館企画展「学芸員のイチオシ！」","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これ、チラシにも記載がないですよね。本来ならば、国際博物館の日は５月１８日ですよね。これ、前後して、このように無料とするのであれば、くどいようですけれども、もっと周知をして、来館者数を伸ばしていただきたいというのが私の要望なので、要望でとどめます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-020"}]},{"id":"topic-05","title":"子どもの施設使用料無料化","agenda":"子どもの施設使用料無料化","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"１点だけ確認させてください。施設の使用の手続に関して、カードの申請、あと、郵送してくださるということなのですが、申請からカード到着まではおよそどれぐらいが所要時間というか、想定されるのでしょうか。教えてください。","respondent":"山下スポーツ推進課長","answer":"長くて２週間なのですが、１週間から２週間で、ＮＧになった場合が一旦お戻しをしてという形になるので、そのほうで２週間程度でお届けできる予定を見込んでおります。","voiceIndex":66,"id":"exchange-021"},{"speaker":"こんの委員","kind":"質問","question":"２週間程度だということで、そうすると、タイミングの問題もあるかと思うのですけれども、申請が始まって、７月１日から無料化が始まります。７月１日には施設を使いたいといって申し込んだのだけれども、２週間かかって、そのときにカードが手元になくてみたいなことがままあるかと想定される。その辺はどのように対応が可能でしょうか。","respondent":"山下スポーツ推進課長","answer":"原則はカードがお手元に来てからという形で周知、広報する予定になっております。","voiceIndex":68,"id":"exchange-022"},{"speaker":"こしば委員","kind":"質問・要望","question":"多分、そのロッカーの総数が定員なのかという認識ではあるのですけれども、ロッカーの総数を超えるぐらいの児童・生徒がいらっしゃった場合というのは、当然、ロッカーを増設するだとか、そういったほかの対応も求められてくると思うのですが、その辺りはどのように取り組んでいかれるのか。考え方について教えていただきたいと思います。","respondent":"山下スポーツ推進課長","answer":"そういう形で現在のところは整理しております。","voiceIndex":71,"id":"exchange-023"},{"speaker":"高橋（伸）委員","kind":"確認","question":"スケートボード場は、愛好者が一定いると思うのです。そのときに、これ、区報で保護者が知ったならば、それを申請すればいいのだけれども、結局、スケートボード場に来る人は、結構若い人でも１人で来て、区報とかを見ない人もいるわけではないですか。そういうときは、公園管理事務所から、こういうカードがあります、無料化になるというのは、お伝えしていただくということでいいのですか。そこを確認だけ。","respondent":"山下スポーツ推進課長","answer":"どこも安心・安全の管理というのは大切なのですけれども、スケートボードは、けがをしてしまった場合は恐らく大けがという形になるので、もう少し本人確認情報を補足した内容で事前に利用登録という形を取らせていただいておりますので、今回。","voiceIndex":74,"id":"exchange-024"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。ぜひ区が案内していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7403#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":21425,"voices":81}},{"id":"r08-20260511-7","meetingId":"r08-m0405","date":"2026年5月11日","dateIso":"2026-05-11","committee":"厚生委員会","time":"午後 １時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"地域包括支援センター在り方検討","agenda":"地域包括支援センター在り方検討","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"地域包括支援センターについては、品川区は地域に１か所もつくらないということでずっと来ましたので、３職種が配置された地域包括支援センターを地域に設置していただきたいということでずっと要望し続けてきましたので、今回、地域包括支援センターを地域に設置するという方向に転換されたこと、共産党としては大きく評価しているところです。","respondent":"冨田地域包括支援センター担当課長","answer":"最後に、地域包括支援センター担当課ができたのかというご指摘ですけれども、担当課長ということで私が着任させていただきましたが、あくまで高齢者福祉課の、中にあるわけではないのですけれども、位置づけとしては中にあるような位置づけになりまして。","voiceIndex":8,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"在り方検討会の名簿が報告書の４８ページに出ていますけれども……、この５０ページにわたる報告書そのものは地域包括支援センター運営協議会のメンバーには行っているのかどうなのか先ほど伺ったので、概要版はそこでも資料として出されましたので、それは承知しているのですけれども、この中身を見ないと、概要版だけだと詳しい中身は分からないと思うのです。","respondent":"冨田地域包括支援センター担当課長","answer":"自治体にヒアリングに行ったメンバーですけれども、こちら、先ほどご紹介させていただきました高齢者支援第一係、第二係のメンバーの中から必要なメンバーと、あとは株式会社サーベイリサーチセンターも同行の上で自治体へのヒアリングを行ったというところと、あと。","voiceIndex":10,"id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"今現在、在宅介護支援センターの制度を使われている方たちがいらっしゃるわけなので、そういう方たちへの説明の体制というのも、こういう検討の中での深い検討も必要だと思うのですけれども、生活者ネットワークとしては、地域の人たちがこれをどう理解してどう使っていくのだろうかということがすごく気になっておりまして、そのことについてどのようにお考えか、現時点での考えがあれば伺いたいと思います。","respondent":"冨田地域包括支援センター担当課長","answer":"介護の相談とかだったら在宅介護支援センターのほうに行くという形になろうかと思うのですけれども、ちょっと困ったことがあるとか、ちょっと知りたいとか、ちょっと何か地域の方と触れ合えるような場がないのかとか。","voiceIndex":15,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"私、介護保険ができた当初、品川区で相当何回も地域で説明会が開かれていたと認識しておりまして、やはり制度をつくったら、ここで看板を掲げたのだから分かるでしょうみたいな感じではなくて、皆さんにとってこういう使い方ができるようになるのですよみたいな説明会が必要ではないかなと思うのですけれども、その辺の検討はいかがでしょうか。","respondent":"冨田地域包括支援センター担当課長","answer":"ただ、どういうような形で役割分担をしていくかとか、そういったところがまだ固まっていないといいますか、まだようやく検討をこれから始めていくという段階ですので、その辺り、区と、先ほど申し上げた支え愛・ほっとステーション、それから今の在宅介護支援センターですね。","voiceIndex":17,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"地域包括支援センターがどの辺まで包括してくれるのかというのも、地域の方たちからしてみればすごく気になるところかなと思います。そうなると、高齢者とか、そういう範囲を超えた生活福祉の部分であったり、障害者福祉の部分であったり、子育ての部分だったりするところもあると思うのですが、その辺との連携というのはどのようにお考えですか。","respondent":"冨田地域包括支援センター担当課長","answer":"ただ、とは言っても、全世代対応と看板を掲げたのですけれども、では区民の皆様がそういったところで実績として来ているのかというと、昨年度まで私が社会福祉協議会で見ている限りでは、なかなかそういったところは増えていないというところが事実としていますので。","voiceIndex":19,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどの概要のところで伺いたいのですが、在り方検討会での主な意見という１枚目のところで、現行では在宅介護支援センター２０か所、地域センターや支え愛・ほっとステーションは１３か所と、管轄地域が一致していないため整理が必要と書いてあるのですけれども、これは意見ということですが、今後の方向性として、私、細かく読み込んでいないのですが。","respondent":"冨田地域包括支援センター担当課長","answer":"数を一致していくというのは、地域包括支援センターという意味では、委員おっしゃるとおりで、減らしていくという、２０を１３にするという形で検討していきたいと考えております。","voiceIndex":22,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"確認","question":"明確なお答えをいただいたのですけれども、もう少し伺いたいのが、今までの在宅介護支援センターのやり方でのメリット、２層構造のメリットというのは、品川区内の高齢者の情報が品川区役所の高齢者福祉課に一元化されていたというところで、何かあったら、変な話、責任を持って高齢者福祉課が情報を全て持っていて対応するということがあります。","respondent":"冨田地域包括支援センター担当課長","answer":"ただ、これから地域包括支援センターで、いわゆる委託という形にしていきますと、基本的には受託していただいた法人でシステムをつくっていってというのが基本の形になってまいりますので、そうなると、どういうふうに情報共有をしていくかというのは。","voiceIndex":24,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"確認","question":"分かりました。私が考えていたようなことも検討の中での課題として出ているということで確認させていただきました。メリットとデメリット、お互いに多分あると思いますので、デメリットという言い方はちょっとあれかな、メリットと、今までのよかった部分についても引き継いでいけるように、今後も検討のほうよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-008"},{"speaker":"やなぎさわ委員","kind":"質問","question":"主任ケアマネジャーでも、今、制度の延長があって、なかなかやはり、もともと取るのも大変で、今、いろいろな特例とかで延長されていて、どうしても主任ケアマネジャーを取ろうという意思のあるようなケアマネジャーが今減っているような状況もあると思いますので、そういった人員確保について、どのような取組をしていくお考えがあるのかということ、２つお伺いします。","respondent":"冨田地域包括支援センター担当課長","answer":"保健師につきましては、１４名ほど数字上は最低必要になってくるという形になるのですけれども、在宅介護支援センターの中で、準ずる者も入れますと１２.３人という形になっておりますので、あくまで数字上だけのお話ですけれども。","voiceIndex":28,"id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"質問","question":"すみません、ちょっと今、私、聞き漏らしてしまったかもしれないですけれども、居宅介護支援事業所の数というか、例えば今ある体制で、制度というのは変わっていくけれども、その中で足りるというご認識、お考えだということでよろしいですか。","respondent":"冨田地域包括支援センター担当課長","answer":"現状のプランを作成するというところだけに特化してお話をすると、今、プランは作成できていますので、在宅介護支援センターも含めて、予防・介護は在宅介護支援センターがやって、居宅介護支援事業所は介護をやって、予防も一部やっていただきますけれどもというところで。","voiceIndex":30,"id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"現在、ケアマネジャー事務所は大体３６％か３７％ぐらいはたしか赤字だというようなアンケート結果も出ています。やはり、特に独立系のケアマネジャー事務所はどうしても利益を上げにくくて、当然独立系のほうが参入はしやすいけれども利益は上がらない。これは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問","question":"そういうところでは、そこのところをしっかりと位置づけていくことが必要だと思うのですけれども、そこの位置づけというのはどう考えられているのか、そういう点でも私はしっかりとした報告書をそこに出すべきだと思うのですけれども、そこの位置づけについても伺いたいと思います。","respondent":"冨田地域包括支援センター担当課長","answer":"運営協議会の在り方ですけれども、当然に介護保険制度推進委員と密接に連携するものだからこそ、同じような形で実施していると認識しておりますので、委員からのご指摘も踏まえまして、どのような在り方がいいのかということは研究してまいりたいと思います。","voiceIndex":34,"id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これは要望だけさせていただきたいと思います。方針も出していないし計画も出していないというところだったと思うのですが、そういうことというのも、これから地域包括支援センターの運営方針を出していくことも必要だと思うのですけれども、そこら辺はいつどういう形でどのような検討を基にして出していくのか、その点についても伺いたいと思います。","respondent":"冨田地域包括支援センター担当課長","answer":"現状、今年度の準備の中で、課題のところにも書かせていただいた評価・改善の仕組みというところですね、どこまでまとまるかというところはありますけれども、まさにモデル実施の法人なんかとお話をしていきながら、進めてまいりたいと考えております。","voiceIndex":36,"id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうすると、来年度からはモデル実施が始まるわけですから、それに向けて今年度中に運営方針を区としてつくるということでいいのか、その点について伺いたいと思います。そういうことをここでもぜひとも報告していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、在宅介護支援センターと地域センターとでそれぞれ、場所はばらばらにあるけれどもペアになるみたいな形なのか、場所もまた一緒になるのか。法人は、支え愛・ほっとステーションは社会福祉協議会がやっているわけですから、社会福祉協議会と在宅介護支援センターの法人と２法人がペアになるみたいな、そこら辺のイメージをもうちょっと確認させていただきたいと思います。","respondent":"冨田地域包括支援センター担当課長","answer":"支え愛・ほっとステーションとペアになるというところで、まさに委員ご指摘のとおりのペアという表現が一番正しいかと思うのですけれども、場所は基本的にはばらばらといいますか、場所もこれからの検討の一つに入りますが。","voiceIndex":40,"id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問","question":"来年度から新体制のモデル実施で、１０期のところでモデル実施して、第１１期介護保険事業計画の中で本格実施ということなのですけれども、来年のモデル実施というのは何か所ぐらいで実施というのは検討しているところがあるのか、その点について伺いたいと思います。","respondent":"冨田地域包括支援センター担当課長","answer":"最低でも１か所と考えております。１か所もしくは多くても２か所程度でまずは実施させていただいて、しっかりと検証してまいりたいと考えています。","voiceIndex":49,"id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問・要望","question":"では最後、要望だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、そこの説明は丁寧にやっていかないと、せっかくいい方向に進んでいるのに、区民にとっては今までとどこがどう違っていくのって、急に前と違うわけみたいな話になると、本当にせっかくいい方向に進むことが、いい成果を得られない可能性があるので、そこだけは本当にお願いですから丁寧に説明をしていただきたい。これはぜひ要望で、もし何かあったらご答弁を伺いたいと思います。","respondent":"冨田地域包括支援センター担当課長","answer":"今までの仕組みをがらっと変えてしまうような形になりますので、一遍に何か所も変わるというよりは、少しずつ地域を絞ってご説明していきながら、課題を見つけながら、展開するときには。","voiceIndex":52,"id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"確認","question":"１つ確認なのですけれども、令和７年度に厚生労働省のほうで地域包括支援センターの設置運営についてという要綱が改正されたと思うのですが、その中で示されている、例えば若年性認知症の方への視点ですとか、２０４０年問題のことですとか、あと、そのほかでいうと重層的な支援体制の整備事業、単身高齢者身元保証問題とか。","respondent":"冨田地域包括支援センター担当課長","answer":"今、委員にご指摘いただいたような問題も、どのようなところが、今、各課でまたいでいるところもありますので、認知症の関係ですと高齢者福祉課をまたぐような形になりますので、そういったところも今、在り方検討会の中で。","voiceIndex":54,"id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"しっかり議論していただけるよう要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7401#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":27557,"voices":62}},{"id":"r08-20260511-8","meetingId":"r08-m0405","date":"2026年5月11日","dateIso":"2026-05-11","committee":"建設委員会","time":"午後 １時００分～午後 ４時４２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区営住宅・品川区立区民住宅指定管理者候補者の公募","agenda":"品川区営住宅・品川区立区民住宅指定管理者候補者の公募","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"３点伺いたいのですが、区民住宅について、ファミーユ西五反田西館・東館のみ除いている理由は何なのかを伺いたいのと、２つ目は指定管理の契約の在り方なのですけれども、指定管理を受けた民間事業者が指定管理料をもらうことになるわけですけれども、入居者からの使用料はどのような扱いになるのかという辺りを伺いたいと思います。","respondent":"川原住宅課長","answer":"当然、コスト面におきましても、今現在管理を行っていただいている株式会社品川宅建管理センターについても、区内の業者であること、そして不動産管理専門会社であるというところで、そういった建物の維持・管理や修繕、そして入居者対応については、かなり知識があることと。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほど少し説明があったようには思うのですが、指定管理でどのような点を民間に期待しているのかというのを伺いたいのと、あと、先ほどの質問で、コストに見合った管理であると言いましたけれども、純粋にコスト面でいうと、本当に指定管理にしたほうが安くなったりするのですかというのを伺ったので、そちらについての区の考えを伺いたいと思います。","respondent":"川原住宅課長","answer":"何点かご質問を頂きました。福祉的な視点が必要なのではないかというご質問です。こちらは特に区営住宅のことをおっしゃっていらっしゃるのかと思うのですけれども、区営住宅は、低所得者の方、困窮している方への対応というところ。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"確認","question":"最後にもう一回伺いたいのですけれども、では、特に、コスト面で安くなるから指定管理を導入しているわけではないというのが区のお考えということでよいか。何度聞いても、コストで安くなるとは言わないので、そういう認識でよろしいのか、そこだけ最後に確認させてください。","respondent":"川原住宅課長","answer":"ただ、年々、やはりどうしても住宅の維持というところでは、原状回復、１部屋を取っても資材の高騰等はどうしてもありますので、そういったところで当初の予算より維持・管理に経費がかかってしまったところについては、区もそこで判断させていただいて。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"指定管理者の公募ということですけれども、冒頭の説明で、指定管理者が行う主な業務ということで、１、２、３、４の説明がありました。伺いたいのは特に区営住宅のほう、区民住宅ももちろんそうですけれども、滞納業務、あと生活再建は、指定管理者が行う業務に入るのか、入らないのか。入るのであればどこに入るのか。そこを伺いたいと思います。そこをご説明いただきたいと思います。","respondent":"川原住宅課長","answer":"実際の滞納整理の業務は、指定管理者の業務の１つの事項としても入ってはいるものの、実際に区と連携して行っているといったものが実際のところです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の説明ですと、明渡しや退去の指導ということで、使用料を適正に確保するということの言わば裏返しで、確保できない場合にはその対応をするということだと思うのですけれども、区と連携しているとはいえ、（４）の「適正な使用の確保」の中には、生活再建が業務として入っていないということでよいのかを伺いたいと思います。","respondent":"川原住宅課長","answer":"滞納整理にあたりなかなか、特に区民住宅で収入が下がってしまって、今の住まいが難しいといった場合は、当然、住宅課の業務の範囲で収まるものではなかったりしますので、例えば収入の援助の相談などといった、今後の相談業務に関しては、当然、指定管理者についても。","voiceIndex":14,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"条例上の規定では、（４）の中に生活再建策は入っていないということです。それが滞ったときに、何か生活上のトラブルといいますか、困難といいますか、問題が起きているのではないかと。むしろ、区営住宅であれ、区民住宅であれ、いわゆる公営住宅に当たるわけですから、家賃が集められなくなったときこそ、自治体の役割が発揮されるべきだと思うのです。そこだけ最後に確認させていただきたいと思います。","respondent":"川原住宅課長","answer":"そういった面会も、本来であれば滞納指導の一環というところではあるのですけれども、そのまま福祉の窓口に、区役所に来ていただいた方をそこの窓口にご案内するといったこともありますので、生活再建の一環にもなっているのかなと考えているところです。","voiceIndex":16,"id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問","question":"先ほどの長期滞納の住宅使用料の件に重ねてなのですけれども、今回、区営住宅・区民住宅の指定管理者を公募するに当たって、ここに載せられている指定管理業務に限らず、滞納の早期把握や福祉部門との連携と、あと生活困窮の兆候があった場合の把握の視点などについて、どのように評価項目として反映していくのか。そういったところをお聞きしたいと思います。","respondent":"川原住宅課長","answer":"１か月だけだと、たまたま口座の引き落としを忘れてしまった、入れるのを忘れてしまったという方もいらっしゃいますが、二か月以上、二か月、三か月続いている方は、ある程度、区でもピックアップさせていただいておりまして。","voiceIndex":19,"id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"今、ご答弁いただいたのは、どういう対応をされているかというお話だったと思うのですけれども、指定管理者の評価項目としてどういうふうに反映するかという点についてお聞きしたいと思います。","respondent":"川原住宅課長","answer":"入居者の管理計画の４点入れているものの、まず１点目というところで、滞納者に対する納付の指導対応はどうかというところで、評価の一つとして非常に重要な項目として点数をつけさせていただいている形です。","voiceIndex":21,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"提案","question":"区営住宅も区民住宅も、セーフティーネットの役割があると捉えています。住宅管理の実績はもちろんですけれども、福祉部門と、先ほども議論があったと思うのですが、連携実績とか、あと相談支援体制についても、提案内容の中で適切に評価していくということが必要であると考えますが、ここについて、要望も含めて、改めてお聞きしたいと思います。","respondent":"川原住宅課長","answer":"福祉部門との連携に対しての、区の評価の部分ですが、今後７月に公募の内容の募集要項を発表するので、その中で、今、選定基準として設けている納付指導対応というところで、きちんと、あちらからのプレゼンテーションの中に含めていただきたいということは。","voiceIndex":23,"id":"exchange-009"}]},{"id":"topic-02","title":"東五反田二丁目第４地区における再開発事業に係る事業者による近隣説明会の開催","agenda":"東五反田二丁目第４地区における再開発事業に係る事業者による近隣説明会の開催","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"これは都市再開発法なのか、それとも区の条例や指導要綱なのか、伺いたいと思います。それで、説明会で様々、住民からの意見が出て、その後、今後の予定というところで、事業者から区への要望、企画提案を受けて、手続を進めていくとあるので、計画案ということは、説明会で出された意見などを受けて、それが企画提案に反映されていくという段階ということなのですか。","respondent":"中道都市開発課長","answer":"今回の準備組合が行う説明会で、まず周辺住民の方がどのような意見を出すのかというのは、行政としてもしっかりと把握に努めていきたいと考えています。","voiceIndex":30,"id":"exchange-010"},{"speaker":"安藤委員","kind":"提案","question":"基礎的なところで伺いたいのですが、東五反田二丁目の地域ですが、昨年４月１日からの変更で、今年度中に都市計画決定がなされなければ国庫補助金の対象から外される地域だと思うのですけれども、それでいいのか、確認したいと思います。今後の予定ですけれども、企画提案を受ける時期や、２回の説明会や都市計画審議会、都市計画決定、それぞれのおおよその時期やスケジュールについて伺いたいと思います。","respondent":"中道都市開発課長","answer":"今後の予定ですけれども、企画提案書がいつ出てくるのかですけれども、今までの再開発の例を踏まえますと、１か月か２か月後ぐらいに企画提案書が出てくる。それを踏まえまして、特に問題がなければ、夏ぐらいにこういった説明会が開始されていくという予定です。","voiceIndex":32,"id":"exchange-011"},{"speaker":"安藤委員","kind":"提案","question":"そして続けて伺うのですが、今後、事業所からの企画提案について、都市計画手続を進めるかどうかというふうになるのですけれども、区としては、どのような条件が整ったら、その企画提案を受けて都市計画手続に入ると考えているのか、伺いたいと思います。どれぐらい同意があるのだったらみたいなことがあれば、伺いたいと思います。マンションに残る条件というのは、実際どれだけ確保されているのか。","respondent":"中道都市開発課長","answer":"残りの１人の方は、拒否しているわけではないのですけれども、もう少し検討したいというお話を頂いていますので、そういったところも、きちんとご説明の回数を重ねて、同意をいただいた上で進めていければいいというところで、事業協力者、また準備組合には、今。","voiceIndex":34,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に、現時点での事業費の補助金についてなのですが、これはこの段階まで来ているわけですから、幾らぐらいなのかという概算を、現時点のものでいいですので伺いたいと思います。１つのマンションが確かに入っています。なので伺っているのですけれども、区として説明会では、現時点での事業費と補助金が幾らかというのを説明するように指導するよう求めたいと思うのですけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"説明会の中でも、どの程度そういったものが表現できるのかというのは、過去を見ると、任意説明会の中で事業費や補助金額を提示できるような状況ではないというのが、いわゆる市街地再開発事業の手続の進め方となっています。","voiceIndex":36,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"ですから、区としての責任を果たすためにも、ぜひ要請してほしい。現時点では区に提出されていないということでしたけれども、であるならば、都市計画案は、程なく１か月か２か月後に出るということですから、それ以降の、１６条・１７条の説明会では説明できると、私は理解しています。これは、必要な住民への説明の要素なのだということで、ぜひ説明してほしいと思いますけれども、最後にいかがでしょうか。","respondent":"中道都市開発課長","answer":"ですので、やはりそういった金額というのは、一定程度、精度が高まったときに、きちんとした時期に対応をご報告していくというところが重要かと思いますので、そういった中で、時期が来たときに、きちんと事業者にも、そういった事業費補助金額というのは提示するよう。","voiceIndex":38,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"これまでも、気候危機の問題、莫大な税金を使う問題、あと住宅高騰の問題、様々指摘して、こうしたタワーマンションの建設を品川区が一緒になって進めるのはやめなさいと求めてきましたけれども、改めて腹立たしく思っております。そこを１点、伺いたいと思います。意見の違いは混乱ではないですから。３分の２以上というのが何人なのか、単純に数字を伺いたいと思います。３つ目。","respondent":"中道都市開発課長","answer":"ですので、繰り返しになりますけれども、やはり検討して精度が高まった状態で、報告すべき時期にきちんと報告するというのを事業者には求めていくべきと考えています。","voiceIndex":41,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"それで、品川区はそうした三井不動産レジデンシャル株式会社の言い分を聞くのではなくて、やはり納税者である区民に対して、今後変わる可能性はあるけれども、現時点での概算として、それは別にその時点での事実ですから、例えば「５０億円の税金を使います。７０億円の税金を使う事業です。これは、指摘、要望で結構です。そういう面からも、進めるべきではないと思いますが、それぞれいかがでしょうか。","respondent":"中道都市開発課長","answer":"地域の方も今、同意率も非常に高く、行政協議も一定程度整ってきたというところで、こういった説明会を開催するという報告を受けたところですので、区といたしましては、周辺状況でどういった意見が出るのか、この任意説明会も踏まえまして。","voiceIndex":43,"id":"exchange-016"},{"speaker":"中塚委員","kind":"提案","question":"なぜならば、これを認めると、五十億円、六十億円、事業費が膨らんだ分、また補助金も膨らむわけですから、そんな税金を垂れ流していいのかと私は思うのです。何なら説明会の案内を出してほしい。何なら建設委員会も傍聴してほしいぐらいだけれども、ぜひ都市計画審議会に、区からの報告だけではなくて、自分で見聞きする機会の案内をぜひ出していただきたいと思いますけれども、いかがでしょうか。","respondent":"中道都市開発課長、高梨都市計画課長","answer":"ちなみに、当該地区の市街地再開発事業は、総合実施計画の中でも、令和８年度に都市計画決定を目指していきたいというようなことを、以前より報告を受けていたですので、いわゆる社会資本整備総合交付金の要綱改正があって。市街地再開発事業以外にも、様々なまちづくりをはじめ、説明会等のスケジューリングの話もありますので、委員の意見も聞きながら検討を進めてまいりたいと考えています。","voiceIndex":45,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"冒頭言ったとおり、法律上の地権者は５人なのです。土地建物が４人。１人は、１８０人のマンション１棟が１人と数えられる。この５人の同意で、五十億円、六十億円。なぜ区はかばうような説明をするのか分かりませんが、三井不動産株式会社は夏までに認可を取らないと補助金は取れないことを知っていると思います。事業者ですから当然でしょう。そこだけ最後にご説明いただきたいと思います。","respondent":"高梨都市計画課長","answer":"頻度はどのぐらいになるべきなのか。そういったところを我々の中でも考える。委員からも意見を聞くということで、検討を進めてまいりたいと考えています。","voiceIndex":48,"id":"exchange-018"},{"speaker":"ゆきた委員","kind":"確認","question":"防災の観点から１点だけ確認できればと思います。３、今後の予定のところで、「防火・準防火地域の変更」というのがあるのですけれども、第４地区の今回の再開発区域内だけの変更となるのか、それともまた周辺地域とのバランスやつながりを踏まえて、区域外を含めてどのように整理・検討が進められていくのか、ここだけお聞きできればと思います。","respondent":"中道都市開発課長","answer":"ソニー通りの沿道２０メートルは防火地域になっているところです。ですので、周辺はもう既に防火地域になっている。それで、今回は当該地区で行っていく再開発の中で防火地域に変更するといったことを、今、検討しているという状況です。","voiceIndex":51,"id":"exchange-019"}]},{"id":"topic-03","title":"リニア中央新幹線シールド工事の再開","agenda":"リニア中央新幹線シールド工事の再開","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、近隣の集合住宅に、ＪＲ東海による個別の説明があったとも聞いているのですけれども、そちらについて、区などは把握しているのでしょうか。区の要望書の中で、「不安や懸念は依然として払拭されたとは言い難い」と書いておりますけれども、そういったことも把握した上での文書なのかなと思いまして、その辺について伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の集合住宅の個別の説明会ですが、こちらにつきましては、実は区にも、お住まいの方から、「説明会に参加したのだけれども、内容がよく分からなかったので、もう一回やってほしいということをＪＲ東海に伝えてください」ということのご依頼があったことから。","voiceIndex":59,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。これは要望です。２月の説明会では、説明自体が推測に基づくというものに終始していたと思います。そこでは、やはり区というのはそれだけの力を持っていると思うので、改めて、なし崩し的に工事を再開することは許さず、住民が納得していないのですから、再度の住民説明会の開催というのを区として求めていただきたいのですけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"区といたしましては、ＪＲ東海が十分な説明をするなど、責任を持って対応すべきものと考えているため、４月１７日の申入れにおきましても、様々な方法により区民への丁寧な説明を行うよう求めているところです。","voiceIndex":61,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、納得を得るまで工事はやはり再開してはいけないというのが、これまでの流れからいっても当然の流れだと思いますし、残念ながらそういう状況には今なっていないということで、ぜひ、先ほどの近隣の集合住宅の方の出された意見なども把握していただいて、様々な手法と言うにとどまらず、再度の住民説明会の開催というのを区として求めていただきたいと思います。最後にいかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"改めてですけれども、委員ご指摘のとおり、区民への説明方法といたしましては、委員ご指摘の教室型の説明会も含めて様々なものがあると、区も認識しています。","voiceIndex":63,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。オープンハウス型はオープンハウス型で大事だと思います。ただ、一斉説明型とありましたけれども、やはり教室型説明会で深まることもありますし、それを住民が望んでいるわけです。私のところにもそういった要望が届けられています。教室型説明会の開催も含めて様々な説明方法があると認識しておりますので、改めて機会を捉えて、ＪＲ東海に要望をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区は、区民の生命・生活を守る立場から、ＪＲ東海に対してリニア中央新幹線工事の中止を求めるよう、強く要望しておきたいと思います。勝手に工事を再開したわけですけれども、４月１７日付の森澤区長のＪＲ東海への文書、要望書ということでいいのでしょうか、文書ということについて、その真意というか内容を伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"４月１７日に申入れをした文書に書かれております「適切な措置」ですが、こちらは、区民の不安や懸念を払拭するため、工事を安全に進めていくためなど、その状況や事象に応じ、ＪＲ東海の責任と判断によりまして最適な手段を取ることを指しているものと考えています。","voiceIndex":67,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"適切にやってほしいという願いとはどういうことなのか、もう一度伺いたいと思います。もう少し説明を頂きたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"こちらの「適切な措置」につきましては、今現在進めているところですが、区民の不安や懸念をまずは払拭するために、それと、ＪＲ東海が再開の判断をした、今後工事を進めていくならば、しっかりと安全を担保していくような形を、しっかりと、その状況や事象に応じて。","voiceIndex":69,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"でも、今、課長の答弁で言うと、安全を担保してほしいということと、最適な判断・手法を使ってほしいという説明がありました。課長というか品川区にも伺いたいのですけれども、どれぐらい抜くことが必要だったのか、どれぐらい抜けば事故が防げたのか、だから今回これぐらい抜きますという数値が全く示されていない中で、安全が担保されたと言えるのか。私は言えないと思うのですけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"ではこれで安全が担保されるのかですが、今回示された再発防止策につきましては、ＪＲ東海が設置しています、第三者で構成されていますトンネル施工検討委員会のシールドトンネル部会でも、しっかりと諮問がなされて公表されているものと考えています。","voiceIndex":71,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"つまり、「１０抜かなければいけなかったところを、５しか抜けなかったから空気が噴き出しました。だから今後は１０、空気を抜き出すようにしましょう」という、数値化された説明がないわけです。これ自体は、私は問題だと思うのですけれども、区の認識を伺いたいと思います。いかがでしょうか。これで安全が担保されたと、やはり私は思えないのですが、改めて区の見解も伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の、１週間前から空気がたまっていたと、説明会で委員が説明を受けたですが、区としてそういった詳細を把握していないので、どういったご答弁ができるかあれなのですけれども、私たちが聞いているのは、ＪＲ東海からは、１日１回程度、空気を抜いていたが。","voiceIndex":73,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"逆の言い方をすると、ずさんというのか。そこの専門家の意見も聞きたいと思いますけれども、区もそういう意味では専門家ですから、ＪＲ東海に対して、明確な対策が示されていないと。そこを示すことをＪＲ東海に要望していただきたいと最後に思いますけれども、いかがでしょうか。ここをもっと深めていかないと、区は区なりの見識で求めていかないといけないと思うのですけれども、最後にいかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"逆に、委員ご指摘のとおりで、例えば定量的に１０メートル行ったら５回抜けばいいのかといった設定をしてしまうと、それが本当に正しいのかというところが、なかなか判断が難しいというところで、区間ごとにしっかりと状況を見ながら、適宜。","voiceIndex":75,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言だけ述べします。シールド工事で、定量化・定式化ができないのだと。実際、事故が起きて、どれぐらい抜けば防げたのかということも数値化できない。私の意見は私の意見としてＪＲに届けていただけるということで、私も説明会のときに同じ話をしましたのであれですけれども、品川区として、ぜひこの立場でＪＲ東海に意見を上げていただきたいと、再度要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-029"},{"speaker":"ゆきた委員","kind":"確認","question":"区としてもＪＲ東海に対して申入れを行って、説明会の実施や情報発信など対応が進められていると認識しています。その上で確認の意味でお伺いしたいと思いますが、現在も区民の皆様から様々なお声や意見が区に対して寄せられているのか。現状と、また区に寄せられた声があれば、区としてどのようにＪＲ東海に伝達して、今後、情報共有や連携をつなげていくのか、併せて伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"公表を受けて、区に問合せが２件ほどございました。１件目は、先ほど安藤委員のときにお話のありました集合住宅の方から、いわゆる補償の有無などについて、そういったものがあるのかどうかというところで、１件お問合せがございました。","voiceIndex":79,"id":"exchange-030"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"確認できました。引き続き、区民の皆様からは不安の声がありますので、引き続き丁寧な対応を進めていただければと思います。こちらは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-031"}]},{"id":"topic-04","title":"令和８年度しながわゼロカーボンアクション助成の開始","agenda":"令和８年度しながわゼロカーボンアクション助成の開始","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"３番目の助成対象事業のところなのですけれども、新規事業と、件数を拡充した事業について、対応の理由を伺いたいのと、あと東京都や国からの補助制度などはあるのかについて、それぞれ伺いたいと思います。","respondent":"長谷川環境課長","answer":"少し要件が細かいのですけれども、新築注文住宅・戸建て住宅の建築主となる個人または購入予定となる個人が対象となっておりまして、ＺＥＨですと５５万円の補助が予定されていて、東京都でも同様に、４０万円から２４０万円程度の補助金が設置されているところです。","voiceIndex":87,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ今回のようなゼロカーボンアクションのパッケージの中に、今後こうしたメニューも入れていって、目標達成を目指していっていただきたいのですけれども、いかがでしょうかというのが１つです。担当部署としては、こうした家庭部門の目標達成を目指すに当たって、この辺の超高層再開発の抑制というのですか、そういったことについてはどのような認識をお持ちなのかというのを、２つ目に伺います。","respondent":"長谷川環境課長","answer":"本提案に関しましては、さきの予算特別委員会でもご答弁していますけれども、再エネ電力の調達に関する重要性は認識しており、区としても連携協定を締結し、再エネ電力の発信を今強めているところです。","voiceIndex":89,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうですね。再エネへの切替えというのは区もやっていて、それはＰＲになると思います。やり方はいろいろあるのですけれども、様々広がっていますので、各家庭が切り替える際の補助みたいなもの、ぜひそちらに踏み出していただきたいということですので、今後とも検討していただきたいと思います。発信もしていただきたいと思いますので、引き続き、そうした問題意識を持っていっていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-034"},{"speaker":"ゆきた委員","kind":"質問","question":"昨年度は、太陽光発電と蓄電池の助成について、申請開始から約２か月で受付終了となり、大きな反響があったと思います。昨年から翌年度のしながわゼロカーボン助成について、行われるという問合せを私自身も受けていますが、申請前の段階ですけれども、区への問合せというのは現段階でどれだけ来ているのか、お聞きできればと思います。","respondent":"長谷川環境課長","answer":"蓄電池・太陽光の家庭用の助成に関しましては、それぞれ昨年度の段階で、８月前の段階で予定件数に達したということで、大変人気のあった助成事業であったと捉えております。今年度に関しましても、ホームページでの公開以降、もう既に問合せは頂いております。","voiceIndex":93,"id":"exchange-035"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"繰り返しになってしまいますが、令和８年度の冊子を確認いたしましたが、東京都や国の制度については、昨年と同様にＱＲコードによる案内が中心になっています。例えば代表的な組合せというのを、申請時によくある問合せの内容の中で紹介するなど、区民目線での情報提供について、要望も含めて、今後の工夫・検討についてお聞きできればと思います。","respondent":"長谷川環境課長","answer":"今ご提案のございました、代表的な組合せ等について、よくある問合せのところに記載したらどうかということに関しましては、引き続き、より分かりやすい記載の一つとして、課内で検討していきたいと考えています。","voiceIndex":95,"id":"exchange-036"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"個別に全てを紹介するというのはかなり難しい点があると思いますが、太陽光発電のみの場合や、太陽光発電と蓄電池を併用する場合など、よくあるケースごとに、区民の理解と負担の軽減につながる案内を要望したいと思います。チラシが、周知方法の６月から実施されるということもお話がありましたが、ここでもそういったことは展開されるのか。今後についてもお聞きできればと思います。","respondent":"長谷川環境課長","answer":"チラシの配布、あるいはエコルとごしでパネル展示等、あるいは説明会を実施しますけれども、刷り物に関しては同一のものを使用しますが、可能な限り、口頭でのご案内を補足できるように、職員と打合せを進めていきたいと考えています。","voiceIndex":97,"id":"exchange-037"},{"speaker":"せお副委員長","kind":"質問・要望","question":"２点伺いたいのですけれども、細かいところで申し訳ないですが、宅配ボックスについては昨年から変更があったと思うので、変更点をご説明いただきたい。なぜ変更したのかという理由も教えてください。区民からしたら、暮らしやすさとか、そういったところでの視点でしかないと思うのです。所管が違うところもありますけれども、その辺りの検討事項がありましたら教えてください。","respondent":"長谷川環境課長、川原住宅課長","answer":"必要に応じて、関係各課へは環境課の事業等を紹介し、ひもづけて紹介していただくよう努めておりますけれども、引き続き、全庁一丸となって対応できるよう、適切な情報共有を図っていきたいと考えています。今の２点目のご質問について、補足のご説明をします。","voiceIndex":100,"id":"exchange-038"},{"speaker":"せお副委員長","kind":"質問・要望","question":"宅配ボックスなのですけれども、ＩｏＴのほうは確かに需要がなさそうなので、そこは理解いたしました。私は、結構、宅配ボックスのことを区民の方から聞かれるのです。それで、ただ購入しただけでは助成が出ない。ほかの部署もありますので、連携を取っていただきたいのと、ホームページで情報を得られる方はそちらがいいのかなと思いました。先ほどの宅配ボックスだけ、１点、聞かせてください。","respondent":"長谷川環境課長","answer":"宅配ボックスの助成要件の４番のところに、「移設できないよう固定されていること」と記載されておりますものは、あくまでも備品として買ったものに対する助成というよりは、設置してあるものに対する助成であるという趣旨から、業者による設置工事を要件としています。","voiceIndex":103,"id":"exchange-039"},{"speaker":"せお副委員長","kind":"意見","question":"最後にごめんなさい。私がご意見を頂くのは、新築だったらついている、設置するのかもしれないのですけれども、今から宅配ボックスだけ購入するときは、ほとんど設置工事はしないですというものです。置くだけなので、そこの要件がなかったらいいなというご意見を結構頂いたので、その辺りを少し柔軟にできないのかなと思っています。検討など今後していただけたらと思いますので、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-040"}]},{"id":"topic-05","title":"品川区立環境学習交流施設指定管理者の公募","agenda":"品川区立環境学習交流施設指定管理者の公募","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"５番の（３）の選定基準の７番に、「運営に係る経費の節減を図る」とあるのですけれども、指定管理を行う目的に、コスト削減というのは入っているのでしょうか。伺いたいと思います。１つです。その辺りを区はどう考えているのか。そうしたことをどのように防ぐ考えがあるのか、それともそういう考えはないのか、伺いたいと思います。","respondent":"長谷川環境課長","answer":"指定管理者の募集要項の中で、選定基準というところを設けておりまして、その中では、全体経費の妥当性や、運営に係る経費の節減を図るものというところで、１つ、コストに関連する記載はしています。しかしながら、これが人件費削減に直結するということは考えておりません。","voiceIndex":112,"id":"exchange-041"},{"speaker":"安藤委員","kind":"質問","question":"結局そういうふうにならないということはおっしゃるのですけれども、それを防ぐ仕組みというのですか、区がきちんと人件費を、雇用状況がどうなっているかというのをチェックするなど、そういう仕組みや担保がないと、そういうふうにはなかなか言えないと思うのですけれども、そこについて、この施設を運営するに当たっての区の考えというのを、もう一度最後にお伺いします。","respondent":"長谷川環境課長","answer":"モニタリングを実施しておりまして、毎年度、指定管理者の業務内容の適切性に関しましては、外部の目で確認させていただいているというところが、１つ、担保になってくるかと考えています。","voiceIndex":114,"id":"exchange-042"}]},{"id":"topic-06","title":"「品川区大井町駅周辺地区バリアフリー計画（改定素案）」に係るパブリックコメントの実施","agenda":"「品川区大井町駅周辺地区バリアフリー計画（改定素案）」に係るパブリックコメントの実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"併せまして、概要版の最後にご説明があった右下の部分、可能な限り当事者参画による検討を進めながら計画を推進していくのだということがありますけれども、当事者参画というのを明記されているというのは本当にすばらしいことだと思うのです。これは具体的にはどのような形で進められていくのかも伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"住民説明会については、こちらに記載のとおり、３か所でそれぞれ約１００名弱という形でご参加いただいております。","voiceIndex":121,"id":"exchange-043"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません。最後に２つなのですが、１つは、視覚障害者福祉協会から、ＪＲ大井町駅の中央口のエレベーターの件について、ずっと要望が出ているわけです。地図があるほうの資料の一番左下に、「主な継続検討事業」というところにちらっと書いているのですが、こうした視覚障害者福祉協会の皆さんの要望というのは、どのような形で、今、検討されているのでしょうか。そちらも含めてお伺いしたいと思います。","respondent":"櫻木地域交通政策課長","answer":"その辺りを踏まえながら、説明会の実施については研究させていただければと考えています。","voiceIndex":123,"id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"資料を拝見させていただきました。ぜひトイレについてもしっかり位置づけて方向を出していただきたいと思いますけれども、いかがでしょうか。信号機のこともそうです。どうすることもできないといいますか、出かけた先で、トイレが使える状態なのか、どこにあるのか。この計画にあまり位置づけや方向性が見当たらなかったので、位置づけていただきたいと、まず思うのですけれども、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"それで、今回の計画上は、車椅子用のバリアフリートイレという形では明記はしておりませんが、当然、概念の中には入っておりますので、今後、事業者との具体的な事業計画の策定の中で、どこまで書けるかということは検討させていただければと思います。","voiceIndex":126,"id":"exchange-045"},{"speaker":"中塚委員","kind":"提案","question":"いろいろ説明が長くなりましたけれども、当事者と懇談の場でつくってほしいというところを、当事者の要望を基準に落とし込んで、新しい施設はやはり快適に使えるようにしていただきたいということと、現状についても、基準に対して足りないところは、追加でできる工事が結構多いので、ぜひ進めていただきたいと、大井町のバリアフリーに関連して提案させていただきたいのですけれども、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"例えばカームダウン・クールダウンルームも、計画上、位置づけるというよりは、やはり皆さんに、例えば知的障害のある方がパニックになったときに落ち着ける部屋が必要だということを、認識していただくなどということも含めて。","voiceIndex":128,"id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"意見だけ。取り替えやすいやつだったのです。せっかくつくったのに使いづらいということをよく聞くので、最後は要望で終わりにしますけれども、トイレの要望や基準を整理していただいて、誰が担当者になっても、少なからず新しくつくるものは利便性が高いものに、そこに照らして足りないもの、今あるものを改善していくという、知識や技術や経験を重ねていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-047"},{"speaker":"ゆきた委員","kind":"質問","question":"改定素案の３７ページに、心のバリアフリーの取組の一環として、安全で快適な移動空間の確保に向けて、自転車利用のマナー向上が位置づけられています。今後、どのように啓発や対策を強化していくのか、お聞きできればと思います。","respondent":"原交通安全担当課長","answer":"キックボードと自転車の安全対策というところですが、やはり４月から青切符制度が自転車に導入されたということで、非常に皆様の関心が高くなっているところです。区におきましても、警察等と連携いたしまして、自転車の安全利用に関する啓発活動を実施していく予定です。","voiceIndex":132,"id":"exchange-048"},{"speaker":"ゆきた委員","kind":"質問","question":"今後予定されているまち歩き点検や心のバリアフリーワークショップにおいても、こうした交通実態や地域の具体的な計画、声を計画に落とし込んでいくのも必要だと思いますが、最後にお聞きできればと思います。","respondent":"櫻木地域交通政策課長","answer":"既に実施させていただいたまち歩き点検と、協議会の中で、地域の方々から、やはり区役所通り、自転車・歩道は、歩いていて危ないというお声は頂いておりますので、その辺りの言葉が、まさにこういう形でお声を反映させて記載させていただいたという状況です。","voiceIndex":134,"id":"exchange-049"},{"speaker":"せお副委員長","kind":"質問・要望","question":"先ほどの中塚委員のトイレの話なのですけれども、私からも１点だけ。ぜひ検討していただきたい。今回、ＯＩＭＡＣＨＩ ＴＲＡＣＫＳに大型ベッドが置いてあるトイレがないと伺っているのです。","respondent":"櫻木地域交通政策課長","answer":"トイレの大型ベッドの件は、今回、非常に私としても印象深いというか、お声を頂いたところではございまして、委員のご指摘のとおり、なかなか後からつけるのは難しいという、施設の構造上の問題等もありますが、最近、ポータブルというか。","voiceIndex":137,"id":"exchange-050"},{"speaker":"せお副委員長","kind":"質問・要望","question":"その辺も含めて、移動式を含めて、計画に落としていただきたいと考えていますので、ぜひ検討をお願いします。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-051"},{"speaker":"新妻委員長","kind":"質問・要望","question":"ほかによろしいでしょうか。すみません。私からも１点確認させていただきたいのですが、計画の素案の中の３０ページに、大井町駅周辺地区における生活関連施設一覧があります。建物しか入っていない、この縦分けはどうしてなのかというところ。宿泊施設では、もう一個、東横インがどんたく通りにあると思うのですけれども、ここが入っていないのはなぜかというところを教えていただきたいと思います。","respondent":"櫻木地域交通政策課長","answer":"入っているホテルと入っていないホテルがあるということですが、基本的には客室数が５００室以上という定義がありまして、その基準にのっとってこういう形で整理させていただいたところです。","voiceIndex":140,"id":"exchange-052"}]},{"id":"topic-07","title":"大井町駅周辺放置禁止区域の変更","agenda":"大井町駅周辺放置禁止区域の変更","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１,０００台増えたにもかかわらず、放置自転車は多く見受けられる。これは、放置自転車が減っていない、あるいは増えているという意味なのかなと思うのですが、それはなぜなのか、区としてはどのように考えているのか伺いたいのと、それと放置禁止区域に指定されると、具体的には自転車を放置しているとどうなるのか、何が変わるのかというのも併せてお伺いします。","respondent":"原交通安全担当課長","answer":"続きまして、周辺の自転車の放置状況です。こちらは、３月から４月にかけて、巡回する形で周辺の実施調査を実施しておりますが、まず区役所通りにつきましては４月中に調査いたしまして、平均すると毎日４台ぐらいとめられているような状況。","voiceIndex":148,"id":"exchange-053"},{"speaker":"安藤委員","kind":"提案","question":"分かりました。区としては、そちらの現状や利用状況というのは把握しているのでしょうか。伺いたいと思いますし、あと、放置禁止区域になることによる、その後の対策というのはどのように考えているのか。当該ビルの管理者と、打合せや相談などは行った上での今回の変更の提案なのか。その辺も併せてお伺いしたいと思います。","respondent":"原交通安全担当課長","answer":"こちらは２月・３月に実施いたしております。区役所通りにつきましては都道になりますので、こちらは東京都と調整いたしまして、また管轄する警察署にもお話をして調整しています。","voiceIndex":150,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。了解しました。最後に、新たに今回、近隣施設に１,０００台分の駐輪場が増えたということで、今回、放置禁止区域を拡大するということなのですけれども、区として駐輪場整備の必要性というのか、現時点で新たに整備が必要だと考えているのか、それとも考えていないということなのか、そちらの点を、最後に認識をお伺いしたいと思います。","respondent":"原交通安全担当課長","answer":"区として自転車駐輪場の整備の必要性といたしましては、大井町に限らず、放置自転車が多い地区においては、駐車場の整備は必要だと考えております。","voiceIndex":152,"id":"exchange-055"},{"speaker":"ゆきた委員","kind":"質問","question":"今回の放置禁止区域の拡大について、歩行者の安全確保や景観の維持などという観点から、必要性は認識しています。禁止区域を広げるのと同時に、施設内駐輪場の利用者が適切に利用できる環境整備が重要と考えますが、区として施設側とも連携してそういったことが可能なのか、今後どのような対応を進めていくのか、お聞きしたいと思います。","respondent":"原交通安全担当課長","answer":"今ご質問がありましたＯＩＭＡＣＨＩ ＴＲＡＣＫＳに関する周知ですけれども、先ほども今後の予定で話を致しました、放置禁止区域の拡大に伴う案内ということで、この付近にとめている自転車の方には、ＯＩＭＡＣＨＩ ＴＲＡＣＫＳ以外にも。","voiceIndex":155,"id":"exchange-056"},{"speaker":"ゆきた委員","kind":"質問","question":"景観への配慮ということも重要であると思うので、動線の案内もやたらにつけることは、難しいと思います。事前周知については先ほど、連携しながら事前の広報ですか、周知していくというのがあったと思うのですけれども、利用者の円滑な誘導につなげるものとして、施設との連携による情報発信の仕方について、もう一度、区の認識をお聞きできればと思います。","respondent":"原交通安全担当課長","answer":"景観の維持といったところにつきましても、区としても対応いたしますし、またＯＩＭＡＣＨＩ ＴＲＡＣＫＳと駐輪場に関してどういった連携ができるのかというところも含めまして、今後、放置禁止区域の指定に向けた動きの中で、検討してまいりたいと考えています。","voiceIndex":157,"id":"exchange-057"}]},{"id":"topic-08","title":"品川区営自転車等駐車場における指定管理者候補者の公募","agenda":"品川区営自転車等駐車場における指定管理者候補者の公募","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"３点、伺います。ぜひ導入を進めていくべきなのではないかと思うのです。区としての考えを伺いたいというのが２点目です。指定管理の協定の労働報酬下限額が時給１,５００円ということになっていますので、確認なのですけれども、今回の指定管理の会社についても、最低賃金を上回る最低１,５００円以上が保証されることになるということでよろしいのか、確認させていただきたいと思います。","respondent":"原交通安全担当課長","answer":"併せて、利用者に対するサービスといたしまして学割制度というのも、また今後の検討課題といたしたいと考えています。","voiceIndex":165,"id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7399#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":67006,"voices":172}},{"id":"r08-20260511-9","meetingId":"r08-m0405","date":"2026年5月11日","dateIso":"2026-05-11","committee":"文教委員会","time":"午後 １時００分～午後 ２時４２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区教育ビジョン概要版（１から６年生版および７から９年生版）の配布","agenda":"品川区教育ビジョン概要版（１から６年生版および７から９年生版）の配布","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"最後のページにいろいろ子どもたちからの意見をもらって、この計画にはその声がたくさん詰まっていますと書かれているのですけれども、その声が反映された部分はどこなのか、以前ご説明があったかもしれませんが、改めて伺いたいと思います。","respondent":"舩木庶務課長","answer":"こういった趣旨を、今回については子どもの概要版ですけれども計画の中に反映をして、今後の５年間の教育ビジョンを示す内容となっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"やはり子どもの教育は、子どもたちがいて、それを糧にこれからの人生を歩んでいくというものになりますので、子どもたちを主人公にしていくことは本当に重要だと思いますし、これから品川区が子ども権利条例を策定していく中でも、そういったことはしっかり続けていかなくてはいけないと思います。今、４つの点が反映されたということでしたが、もう少し具体的にご説明できる部分があれば伺いたいと思います。","respondent":"舩木庶務課長","answer":"それから併せまして、これからの児童・生徒に求められる資質を大きなビジョンとして示しておりますので、先ほど答弁いたしました子どもたちからの４つの意見を反映して、それぞれがそれぞれの内容について本編では柱を３つ立てて。","voiceIndex":7,"id":"exchange-002"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"例えばこういう羅針盤を中心に、家庭内での対話を家庭に落とし込むような工夫、家でこういうことを話しましょうとか、何かそういった工夫を教育委員会で考えているのなら教えていただきたいのと、子どもたちへのｉＰａｄでの資料が提示されていますけれども、例えばこういった保護者向けの説明資料とか、あと保護者会の積極的な周知は行っていく考えがあるのか、そこら辺を教えてください。","respondent":"舩木庶務課長","answer":"子ども向けの概要版につきましては、冒頭の答弁の繰り返しになりますけれども、まず主役である子どもたちに、いろいろな場面での活用方法が考えられると思いますし、各学校の授業の中でこの概要版を使用してくださいと指定する性質のものではないのですけれども。","voiceIndex":9,"id":"exchange-003"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ぜひ、やっていただきたい。私が気になったのは、概要版の中に二次元コードが出てきて、ぱっとやると確かに教育委員会のホームページのそこを一面抜いただけのあれがぱっと出てきて、例えば私が子どもとして見たときにどうなのかとすごく感じたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問","question":"この計画の合い言葉は云々ではっきりと品川区教育ビジョン、１年生から６年生だから品川区教育振興基本計画と言ったらきっと分からないから、それを品川区教育ビジョンという名前で今回区は作りましたみたいな表現が入っていないのですけれども、その辺はこれを作るときに何か議論があったのでしょうか。","respondent":"舩木庶務課長","answer":"本概要版の作成にあたりましては、学校現場であったり教育系の管理職であったり、それからもちろん教育委員会での議論を含めて決定したものですが、今の委員のご指摘で申し上げますと、その１から６年生版の概要版の２ページ。","voiceIndex":12,"id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"意見","question":"これを見たときに、小学生が今自分が読んでいるこの計画を作りましたというのが、品川区教育ビジョンなのですという一文があると、もっと分かりやすいと思った次第ですので、これは意見で結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-006"}]},{"id":"topic-02","title":"令和８年度、学級編制","agenda":"令和８年度、学級編制","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"実際、中学１年生も３５人学級が始まったのは、法律で決まっていると思うのですけれども、こうした学級編制がどうしてできるのか、なぜなのかを伺いたいと思います。もう１つ、児童数が、小学校では全体を見ると昨年と比べて７９人減っている。私立に進学する子どもが減っていると少し思ったのですけれども、伺いたいと思います。","respondent":"石井学務課長","answer":"いずれは大体３年間ぐらいにおいて、普通教室の整備をすることを条件として、この経過措置が適用されておりますので、順次、我々としてもこの法改正に対応できるように進めていきたいと考えております。最後の児童数が、まず小学校が７９人減少、そして中学校は１４８人減少。","voiceIndex":19,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"これから３年かけて３５人学級を中学校でもやっていくことになりますけれども、そうした教員が子どもたちにしっかりと向き合える環境を作っていっていただきたいと思いますので、お伺いします。","respondent":"石井学務課長","answer":"法律事項で４０人学級から３５人学級になった経緯につきましては、よりきめ細やかな教育が叫ばれているところです。我々としても、法令の趣旨にのっとってきちんと対応してまいりたいと考えております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"意見","question":"これはその１００人増えていることに関してのお考えと、東京都で特別支援教室の指導に関してはどんどん増えていった部分があって、それは対応していただくからいいのですけれども、そこで通級に対応させるのを年数を区切って、言い方は少しいけないかもしれませんけれども、結構厳しく、そういったラインを作っていったと思いますけれども、その点で今後増えていく可能性と、それに本当に対応して。","respondent":"石井学務課長、新井特別支援教育担当課長","answer":"これは、特別な支援が必要なお子さんがいるということで、よりきめ細かな支援をするときにクラスを増やしたですけれども、こちらにつきましては、両学校とも固有教員を充てることによって対応しております。達成されていないのであれば、指導延長という形でさらに１年間延長することで目標が達成されるかといったことを各学校できちんと精査をした上で、必要な場合には１年で退室ではなくて。","voiceIndex":23,"id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"小学校は固有教員の方ということで、プラス１になっているとしても、これが６年生を担任するとは限らないわけです。学校の中でどこに配置するかは決めていくのだと思います。今は特別支援教室のお話だったのですが、これはやはり教室が去年５８０人で、６８０人だと１００人増えているわけです。ですから、そこはそれだけの対応ができるようになっていくのかをお尋ねするのが１つ。","respondent":"新井特別支援教育担当課長","answer":"固定級のいわゆる特別支援学級の児童数が増えていることについても、学校施設という限られたスペースではございまして、通常の学級の教室、あとは家庭科室ですとか特別教室との兼ね合いもあるので、特別支援教育だけで何か決められるものではありませんが、学務課。","voiceIndex":26,"id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"意見","question":"対応していっていただけるという状況が分かりました。今、学年ごとに、途中から３年生、４年生、５年生で増えていったというのは実に注目すべきであって、やはりこれを特別支援教室で指導していただいているのは非常にいいことで、そういう状況を学校が判断したときに、特別支援教室で指導を受ける体制にしていただいているのは大変ありがたいと思います。","respondent":"新井特別支援教育担当課長","answer":"そういった中で、直接私どもから保護者の方に働きかけるのはなかなか難しいところですが、校長先生とあと教員の方々に対して、お子さんの情報、必要な支援をきちんとタイムリーに情報提供して、それで校内委員会にかけていただいて。","voiceIndex":28,"id":"exchange-011"},{"speaker":"横山委員","kind":"質問・要望","question":"私からも１点だけ確認ですけれども、弾力的運用の際にどういうフォローをしているのかお聞きしようと思っていたのですが、先ほどの高橋しんじ委員の質疑の中で、小学校は固有教員の方がいらっしゃるということで、中学校ですと、特にティーム・ティーチング等を例年はしていたけれども、今年度についてはどういったフォローがされるのかを確認したいと思っていたのです。","respondent":"石井学務課長","answer":"これにつきましては、例えば具体的に教室数を増やすとか、そういったことはいろいろ検討していかなくてはいけない課題でありながらも、やはり我々としてもそういった課題を踏まえながら、どうやって学校の支援をやっていけるのかを考えてまいりたいと考えています。","voiceIndex":30,"id":"exchange-012"},{"speaker":"横山委員","kind":"質問・要望","question":"現時点では、その具体的な何かというのはこれから検討していくと思うのですけれども、義務教育学校、学園系と言いますか、そういう大規模校の先生方の負担が少し気になっています。ぜひ教育委員会からも様々フォローをしていただけるように検討を進めていただきたいと思いますので、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-013"},{"speaker":"まつざわ委員","kind":"意見","question":"小学校での弾力的運用の数を増やしていって、特別な配慮が必要ない場合、例えばこれは、芳水小学校とか第四日野小学校だけではないという感覚があるのです。そこら辺は小学校全体を見たときにどのような感じなのか。例えばそういう声が上がっているけれども、実際に先生も教室も足りないからそういう弾力的な運用ができないのか、そこら辺を聞かせてください。","respondent":"石井学務課長","answer":"いろいろ担当ベースでの相談はあり、最終的に調書の提出に至ったのがその２校ではありながらも、それぞれ課題はあると思いますので、引き続きそこについてはきちんとコミュニケーションを取ってまいりたいと考えています。","voiceIndex":33,"id":"exchange-014"},{"speaker":"まつざわ委員","kind":"意見","question":"例えば私が校長だったとして、そういう課題を、なかなかこうやって上げるのは難しいと思うのです。今回２校がこうやって上げたのはいいことで、いろいろ課題があると思いますけれども、引き続き何かそういった困ったことはすぐに言えるような関係性を、ぜひ引き続き構築していただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-015"},{"speaker":"筒井副委員長","kind":"質問","question":"私からは、小学校・義務教育学校（前期課程）の児童数について、４年生と５年生の数字をそれぞれ見ますと、４年生で１８２人減っていて、５年生で１４０人増えているのです。このときどのような状況、事象でこうなったのか、区としてどのように分析されているのかを教えてください。","respondent":"石井学務課長","answer":"確かに今のこの５年生の人数は、少し例年に比べて多いという感触を持っておりまして、そういったところが増減の要因にはなってきますので、単純に１８２人減ったから、例えば転出が増えたとかではなく、もともとの母集団自体が、学年が上がるにつれて変化している状況です。","voiceIndex":36,"id":"exchange-016"}]},{"id":"topic-03","title":"令和８年度、移動教室および林間学園","agenda":"令和８年度、移動教室および林間学園","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"どのようなことをされてきたのか、一定、文教委員会でもこの駆除作業をやってきたという報告をいただいたと思うのですが、その後にそういった作業は、今回４月２２日までの間にやったということはあったのかお聞きしたい。今回発見されたのはどういう形で報告が入ったのか、誰がどういう形で発見したのか、その発見した経緯を伺います。","respondent":"石井学務課長","answer":"４月１５日に発見された経緯につきましては、これまで同様日常の点検をしたところ、光林荘の従業員がそれを見つけた上で、今１匹出ましたと、教育委員会事務局と、あとは地域振興部に電話連絡があったものです。","voiceIndex":42,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"駆除作業をこの間やってきたのかを伺ったのにご答弁がなかったので、ご答弁いただきたいのと、あと今回、４月２２日に駆除作業を実施したということで、それ以降は今のところ発見されていないのか、お聞きしたいと思います。それで、今年度はこの移動教室・林間学園については、全校で昨年同様に代替施設で実施するということでいいのか確認をさせていただきたいと思います。","respondent":"石井学務課長","answer":"今年度の実施につきましては、全校代替施設について行うことを検討しておりまして、今後、どのようにするかは、まず今回は代替施設での実施を主眼に調整してまいりますので、それと並行した上で、検討してまいりたいと考えております。","voiceIndex":44,"id":"exchange-018"},{"speaker":"まつざわ委員","kind":"質問","question":"２年連続ですね。例えば、こういう言い方をしてはいけないのかもしれないですけれども、やはり２年こういう同じことが起こるとなると、ではこの責任の所在はどこなのかという疑問が残るのですけれども、まずそこを説明してもらっていいですか。","respondent":"石井学務課長","answer":"だから発生源を１００％特定することがすごく難しいものであると、非常にその辺りの困難さがあるとは言われておりまして、今後も含めてどのような形でやっていくかについては、検討していきたいと考えております。","voiceIndex":47,"id":"exchange-019"},{"speaker":"まつざわ委員","kind":"質問","question":"そうしますと、例えば光林荘は区がこうやって持ってやっているわけです。お話のとおり、トコジラミがゼロは多分ない中で、本当にお答えはいいですけれども、これからいろいろ考えていってほしい。だから少し会派の中で出たのが、例えば磐梯に行きます。でも磐梯だと、今度は熊が出ます。そうすると、では磐梯に子どもたちが行っていいのか、そういった話などにはならなかったのですか。","respondent":"石井学務課長","answer":"ただ、いずれにしてもこういった校外学習活動については、様々な危険がつきものですので、そういった中で、今後どうやってこの行事自体をやっていくのか、またその教育内容の位置づけですとかそういったことも検討していかなくてはならないだろうというところで。","voiceIndex":49,"id":"exchange-020"},{"speaker":"まつざわ委員","kind":"意見","question":"何せ安全に行ってもらうのが一番、もう本当にそれが全てだと思います。個人的に、やはり林間学園は私も経験したから、例えば子どもたちも経験したときに、それがパパのときはこうだったけれども、どういうことをした、こうした、というのがまた親子の良い交流になったので、ぜひ光林荘は続けてもらいたいという思いがあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問","question":"そのためには光林荘ではなくと言っていくのか、それとも光林荘を絶対そのようにしてくださいと言っていくのか、何かその交渉、その検討が少しあれなのですけれども、どちらがどうイニシアティブを持っていくのか、もう保養所ではなくなるので、そこをどのようにしていくのですか。","respondent":"石井学務課長","answer":"教育委員会としてやはりこの施設がすごく大事だと伝えてまいりましたけれども、一方でこのリスクの部分について、今回トコジラミが出て、当然、では今度トコジラミ以外のものも出るかもしれないとか、それを運営するときにどのようにやっていったらいいのかですとか。","voiceIndex":52,"id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この行事、移動教室および林間学園の重要性を区長部局にお話ししているということですが、今後光林荘の大規模改修という話になってくるので、こちらは区民委員会の話になってしまうのでしょうけれども、そのことも考えてやるのかどうかにもつながっていくので、やはりこれはこの文教委員会の話ではないのですけれども、教育委員会として光林荘でやることの意義。","respondent":"石井学務課長","answer":"当初、区民保養所のあり方検討会のときには、教育的意義もそうなのですけれども、やはり例えば２３区の教員については、大概日光を選んでいる。教員の負担軽減も日光という地の利は非常に有効である。","voiceIndex":54,"id":"exchange-023"},{"speaker":"若林委員","kind":"確認","question":"現場を見るというのは私も当然理解するのですが、現地確認等ということで、何を見てどういう報告が区に、また教育委員会になされたのか、１つお聞きしたいと思います。卵の話がありました。最後に、残念ながら今年度については、来年３月までの期間で光林荘以外の宿泊施設でやる。ご苦労されるのはどのような方なのかを具体的にお聞きしたいと思います。","respondent":"石井学務課長","answer":"今回は移動教室関係の全教員も含めて実地踏査に行く予定だったところ、そこの予定を切り替えて、地域振興部とあと教育委員会事務局の職員と一緒に、学校長の中でも校外教育部という形で移動教室ですとかそういった関連の人たちを含めて現地確認を実施し。","voiceIndex":56,"id":"exchange-024"},{"speaker":"若林委員","kind":"質問・要望","question":"先ほどもありましたサイクルが１つ出来つつあるという大きな懸念材料だと思います。関連して誰が困るか、こういう急遽の対応、またこれを前提にやっていくのもこれほどおかしな話もないわけで、やはり何かにつけてきちんと毎年安定した事業の実施、これがやはりいわゆる教員不足とか何とかと言われている時代の中にあって、来年はどうなるのだろう、新年度になって急遽３月までにどうにかしなくてはいけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-025"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"先ほど来、委員の方からご意見が出ておりますけれども、光林荘については教育宿泊行事に使うにあたって、固定の施設ですから安定性があるということで、また教育施設として維持していきたいというご答弁がありましたけれども、２年連続でこうしたトコジラミが発見されてしまった事態を受けて、教育施設としての安定性としてはなかなか不安定になってきたと考えていますので、この点も鑑みて。","respondent":"石井学務課長","answer":"昨年８月に発生したものにつきましては、それが実際には外から持ち込まれたのかどうなのか、原因の特定は難しかったのと、今回４月に発生したものについては、これは駆除業者から聞いた話によると、恐らく越冬したものである。","voiceIndex":59,"id":"exchange-026"},{"speaker":"筒井副委員長","kind":"質問","question":"そういったことで、やはり越冬したというお話もありましたけれども、もうある程度何匹かその数は分からないですが、住みついている状況は推測されるということでよろしいでしょうか。","respondent":"石井学務課長","answer":"当然柱の例えば傷の中とか、そういったところにも入り込むので、どれだけのものがいるかはまだ現時点ではっきりしないので、それにつきましては今後駆除の状況を適宜報告を受けながら、判断してまいりたいと考えております。","voiceIndex":61,"id":"exchange-027"},{"speaker":"横山委員","kind":"質問・要望","question":"確認ですけれども、今回に関しては特にそういったキャンセル料の発生とか、何か費用的なもので前回と違った部分がもしありましたら、確認させてください。そして昨年度、もし課題等があれば、それは今回しっかりと改善していく視点もまた大切だと思うのですけれども、そうした振り返りの状況等が今どうなっているのかを確認させてください。","respondent":"石井学務課長","answer":"ただ一方で、今年度も同様に実施するような形にはなりますけれども、当然、昨年は１０月以降の実施になってしまいましたけれども、今年度はできるだけ光林荘でやるならばこういう効果が期待できたものを。","voiceIndex":63,"id":"exchange-028"},{"speaker":"横山委員","kind":"質問・要望","question":"様々な実現の手法、実施方法というのは、今、将来を見通すことがなかなか難しいところがありますので、そういった虫の駆除をしてもなかなかゼロリスクが難しいのもあって、また、今後１年先、２年先、どういったことが発生するか分からないような中で、１か所に依存し続けるのがどれだけリスクがあるのかも含めて、今後のことは検討していただきたいと思いますので、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-029"}]},{"id":"topic-04","title":"令和８年４月入園申請状況等","agenda":"令和８年４月入園申請状況等","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"不承諾数が３８３人ということで、いわゆる隠れ待機児童になると思いますが、この内訳を伺います。特に１歳児がこの不承諾の中では６割を占めていて多くなっているわけですけれども、その理由を伺いたいのと、この隠れ待機児童の解消に向けてはどのように考えているのか伺います。","respondent":"佐藤保育入園調整課長","answer":"園の運営も考えまして、こういった数で受入れを確保しており、需要に対しては適切に対応している状況ということで認識をしています。","voiceIndex":70,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"なので、この１歳児では入りたくても入れない人が結構いると思うのですが、そこの受け止めを伺いたいのと、あと不承諾のところでは、求職活動を休止している者は今年度はいないということですか。応募がなかったので、そこの確認をさせていただきたいのと、特定の保育園を希望している方で、そのうち１園のみ希望している方がどれだけいらっしゃるのか。","respondent":"佐藤保育入園調整課長","answer":"それ以外の方の状況では、入園可能数のところも含めまして一定程度対応できる状況にあると考えています。それから求職のお話がございましたが、こちらは委員おっしゃるとおりゼロと今年度はなってあります。","voiceIndex":72,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問","question":"１歳児のところでも対応できているというお話だったのですけれども、転園とかはもう既に確かに入っているので、でも多分多数の兄弟がいて別の園に通っているということだと思うので、やはりそうした大変さはあると思います。やはりそれを解消していくことが必要だと思うのですけれども、いかがでしょうか。","respondent":"佐藤保育入園調整課長","answer":"こちらも入園可能数も含めまして用意して、それから、先ほど申し上げましたけれども、保育園の定員の状況は空き過ぎず、年度途中の入園も含めて対応できるような数を確保していますので、ここにつきましてはまた就学前人口の増ですとか。","voiceIndex":74,"id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"年度途中で入園できるようにするのは重要だと思います。そこに加えて、やはり必要な方がいると思いますので、必要な方がしっかりと利用できるようにしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-033"},{"speaker":"まつざわ委員","kind":"質問","question":"１歳児まではなかなか入れなくて、５歳児は４００枠ぐらい空いている。５歳児が空いているということは、それだけ運営する側も結構大変ではないですか。例えば何かそういうことができるかできないかは別として、誰でも通園制度が今度できて、その５歳児と１歳児とかの規格は多分違うのですよね。","respondent":"佐藤保育入園調整課長","answer":"全体の定員と、それから設備の部分がありますので、そういったところは今回のこういった入園、それから申請の状況も踏まえて、各施設等の情報を把握しながら区として対応を整理していきたいと考えております。","voiceIndex":77,"id":"exchange-034"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"つる委員長","kind":"質問","question":"続きまして私からご挨拶申し上げます。１年間大変お世話になりまして、ありがとうございました。この１年間、委員長としての感想は、特に一般質問や予算特別委員会等で、委員会で視察に伺った内容を基にした質疑が数多くなされたという印象を持っておりまして、この常任委員会としての役割を果たすことができたと考えています。本当に１年間、ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7397#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":29877,"voices":84}}]);
